const e={id:"social_q01",subjectId:"social_science",chapterNumber:"પ્રશ્ન 1",title:"જોડકા (જોડકું 1 થી 4)",subtitle:"વિભાગ A • 18 જોડકા પ્રશ્નો",questionTypeLabel:"જોડકા",isFreeUnlocked:!0,questions:[{id:"ss_q01_01",questionText:"1) જોડકું ૧: ધોળાવીરા — ________ (નમૂનાનું પેપર 2024-25)",options:["સુરત","અસમ","ભાવનગર","કચ્છ"],correctIndex:3,explanation:"ધોળાવીરા ગુજરાતના કચ્છ જિલ્લાના ભચાઉ તાલુકાના ખદીરબેટમાં આવેલું હડપ્પીય સંસ્કૃતિનું પ્રાચીન નગર છે, તેથી સાચી જોડ 'કચ્છ' છે."},{id:"ss_q01_02",questionText:"2) જોડકું ૧: જરીકામ — ________ (નમૂનાનું પેપર 2024-25)",options:["સુરત","જામનગર","જેતપુર","પાટણ"],correctIndex:0,explanation:"ગુજરાતમાં સુરતનું જરીકામ ભારતભરમાં વિખ્યાત છે. ચાંદી અને સોનાના તાર વડે થતું જરીભરત સુરતની આગવી ઓળખ છે."},{id:"ss_q01_03",questionText:"3) જોડકું ૧: કાઝીરંગા — ________ (નમૂનાનું પેપર 2024-25)",options:["ગુજરાત","રાજસ્થાન","અસમ","કેરળ"],correctIndex:2,explanation:"કાઝીરંગા રાષ્ટ્રીય ઉદ્યાન અસમ રાજ્યમાં આવેલું છે, જે એક શિંગી ભારતીય ગેંડા માટે વિશ્વપ્રસિદ્ધ છે."},{id:"ss_q01_04",questionText:"4) જોડકું ૧: બોક્સાઇટ — ________ (નમૂનાનું પેપર 2024-25)",options:["લોખંડ","એલ્યુમિનિયમ","તાંબુ","જસત"],correctIndex:1,explanation:"બોક્સાઇટ એ એલ્યુમિનિયમ ધાતુની કાચી ધાતુ (અયસ્ક) છે, જેમાંથી એલ્યુમિનિયમ મેળવવામાં આવે છે."},{id:"ss_q01_05",questionText:"5) જોડકું ૧: ઊર્જાનો મુખ્ય સ્ત્રોત — ________ (નમૂનાનું પેપર 2024-25)",options:["કોલસો","પેટ્રોલિયમ","સૂર્ય","પવન"],correctIndex:2,explanation:"પૃથ્વી પર તમામ પ્રકારની ઊર્જાનો મુખ્ય અને અખૂટ સ્ત્રોત 'સૂર્ય' છે."},{id:"ss_q01_06",questionText:"6) જોડકું ૨: હેમચંદ્રાચાર્ય ગ્રંથાલય — ________ (નમૂનાનું પેપર 2024-25)",options:["મુંબઈ","ભોપાલ","પાટણ","કોલકતા"],correctIndex:2,explanation:"શ્રી હેમચંદ્રાચાર્ય ગ્રંથાલય ગુજરાતના પાટણ શહેરમાં આવેલું પ્રસિદ્ધ ગ્રંથાલય છે."},{id:"ss_q01_07",questionText:"7) જોડકું ૨: ભારતીય સંગ્રહાલય — ________ (નમૂનાનું પેપર 2024-25)",options:["મુંબઈ","ભોપાલ","પાટણ","કોલકતા"],correctIndex:3,explanation:"ભારતીય સંગ્રહાલય (Indian Museum) પશ્ચિમ બંગાળના કોલકતા શહેરમાં આવેલું ભારતનું સૌથી પ્રાચીન અને મોટું સંગ્રહાલય છે."},{id:"ss_q01_08",questionText:"8) જોડકું ૨: છત્રપતિ શિવાજી મહારાજ સંગ્રહાલય — ________ (નમૂનાનું પેપર 2024-25)",options:["મુંબઈ","ભોપાલ","પાટણ","કોલકતા"],correctIndex:0,explanation:"છત્રપતિ શિવાજી મહારાજ વાસ્તુ સંગ્રહાલય (અગાઉ પ્રિન્સ ઓફ વેલ્સ મ્યુઝિયમ) મુંબઈ ખાતે આવેલું છે."},{id:"ss_q01_09",questionText:"9) જોડકું ૨: રાષ્ટ્રીય માનવ સંગ્રહાલય — ________ (નમૂનાનું પેપર 2024-25)",options:["મુંબઈ","ભોપાલ","પાટણ","કોલકતા"],correctIndex:1,explanation:"રાષ્ટ્રીય માનવ સંગ્રહાલય (ઇન્દિરા ગાંધી રાષ્ટ્રીય માનવ સંગ્રહાલય) મધ્યપ્રદેશના ભોપાલ શહેરમાં આવેલું છે."},{id:"ss_q01_10",questionText:"10) જોડકું ૩: બહુચરાજીનો મેળો — ________ (માર્ચ 2024)",options:["બનાસકાંઠા","જૂનાગઢ","મહેસાણા","પાટણ"],correctIndex:2,explanation:"બહુચરાજીનો પ્રસિદ્ધ મેળો ગુજરાતના મહેસાણા જિલ્લામાં બહુચરાજી ખાતે ભરાય છે."},{id:"ss_q01_11",questionText:"11) જોડકું ૩: પંડિત અહોબલે — ________ (માર્ચ 2024)",options:["સંગીત રત્નાકર","સંગીત પારિજાત","સંગીત મકરંદ","નાટ્યશાસ્ત્ર"],correctIndex:1,explanation:"પંડિત અહોબલે ઈ.સ. 1665માં ઉત્તર ભારતીય સંગીત પદ્ધતિ માટે 'સંગીત પારિજાત' ગ્રંથની રચના કરી હતી."},{id:"ss_q01_12",questionText:"12) જોડકું ૩: કુદરતનો સફાઈ કામદાર — ________ (માર્ચ 2024)",options:["ગીધ","વાઘ","મોર","હંસ"],correctIndex:0,explanation:"ગીધ મૃત પશુઓનું માંસ ખાઈને પર્યાવરણને સ્વચ્છ રાખતું હોવાથી તેને 'કુદરતનો સફાઈ કામદાર' કહેવામાં આવે છે."},{id:"ss_q01_13",questionText:"13) જોડકું ૩: પવન ઉર્જા — ________ (માર્ચ 2024)",options:["મહેસાણા","પાલનપુર","લાંભા","વડનગર"],correctIndex:2,explanation:"ગુજરાતમાં જામનગર પાસેના લાંભા ગામે પવન ઊર્જા (વિન્ડ ફાર્મ) મથક આવેલું છે."},{id:"ss_q01_14",questionText:"14) જોડકું ૩: પૃથ્વી પરિષદ — ________ (માર્ચ 2024)",options:["જિનીવા","લંડન","પેરિસ","સ્ટોકહોમ"],correctIndex:3,explanation:"પર્યાવરણની સુરક્ષા માટે પ્રથમ પૃથ્વી પરિષદ ઈ.સ. 1972માં સ્વીડનના સ્ટોકહોમ ખાતે યોજાઈ હતી."},{id:"ss_q01_15",questionText:"15) જોડકું ૪: રાષ્ટ્રીય સંગ્રહાલય — ________ (માર્ચ 2024)",options:["અમદાવાદ","વડોદરા","હૈદરાબાદ","ન્યુ દિલ્લી"],correctIndex:3,explanation:"રાષ્ટ્રીય સંગ્રહાલય (National Museum) ભારતની રાજધાની ન્યુ દિલ્લી ખાતે આવેલું છે."},{id:"ss_q01_16",questionText:"16) જોડકું ૪: સાલારગંજ — ________ (માર્ચ 2024)",options:["અમદાવાદ","વડોદરા","હૈદરાબાદ","ન્યુ દિલ્લી"],correctIndex:2,explanation:"સાલારગંજ સંગ્રહાલય તેલંગણાના હૈદરાબાદ શહેરમાં આવેલું વિશ્વપ્રસિદ્ધ સંગ્રહાલય છે."},{id:"ss_q01_17",questionText:"17) જોડકું ૪: વડોદરા મ્યુઝિયમ — ________ (માર્ચ 2024)",options:["અમદાવાદ","વડોદરા","હૈદરાબાદ","ન્યુ દિલ્લી"],correctIndex:1,explanation:"વડોદરા મ્યુઝિયમ અને પિક્ચર ગેલેરી વડોદરા શહેરમાં આવેલ છે."},{id:"ss_q01_18",questionText:"18) જોડકું ૪: લાલભાઈ દલપતભાઈ સંગ્રહાલય — ________ (માર્ચ 2024)",options:["અમદાવાદ","વડોદરા","હૈદરાબાદ","ન્યુ દિલ્લી"],correctIndex:0,explanation:"લાલભાઈ દલપતભાઈ સંગ્રહાલય (એલ. ડી. ઇન્સ્ટિટ્યૂટ ઓફ ઇન્ડોલોજી) અમદાવાદમાં આવેલું છે."}]},t={id:"social_q02",subjectId:"social_science",chapterNumber:"પ્રશ્ન 2",title:"જોડકા (જોડકું 5 થી 8)",subtitle:"વિભાગ A • 20 જોડકા પ્રશ્નો",questionTypeLabel:"જોડકા",questions:[{id:"ss_q02_01",questionText:"1) જોડકું ૫: તરણેતરનો મેળો — ________ (ફેબ્રુઆરી-માર્ચ 2026)",options:["બનાસકાંઠા","સુરેન્દ્રનગર","મહેસાણા","જૂનાગઢ"],correctIndex:1,explanation:"તરણેતરનો લોકપ્રિય મેળો સુરેન્દ્રનગર જિલ્લામાં ત્રિનેત્રેશ્વર મહાદેવના સાનિધ્યમાં યોજાય છે."},{id:"ss_q02_02",questionText:"2) જોડકું ૫: મેરાયો નૃત્ય — ________ (ફેબ્રુઆરી-માર્ચ 2026)",options:["બનાસકાંઠા","સુરેન્દ્રનગર","કચ્છ","ડાંગ"],correctIndex:0,explanation:"મેરાયો નૃત્ય બનાસકાંઠાના વાવ તાલુકાના ઠાકોર સમાજનું જાણીતું લોકનૃત્ય છે."},{id:"ss_q02_03",questionText:"3) જોડકું ૫: ગીધ પરિયોજના — ________ (ફેબ્રુઆરી-માર્ચ 2026)",options:["૧૯૭૩","૧૯૯૨","૨૦૦૪","૧૯૭૫"],correctIndex:2,explanation:"ગીધોની ઘટતી જતી સંખ્યાને બચાવવા માટે ભારતમાં ઈ.સ. ૨૦૦૪માં 'ગીધ પરિયોજના' શરૂ કરવામાં આવી હતી (જ્યારે ઈ.સ. ૧૯૭૩માં વાઘ પરિયોજના અને ૧૯૯૨માં હાથી પરિયોજના શરૂ થઈ હતી)."},{id:"ss_q02_04",questionText:"4) જોડકું ૫: માનવ ઉપયોગમાં આવેલ સૌપ્રથમ ધાતુ — ________ (ફેબ્રુઆરી-માર્ચ 2026)",options:["લોખંડ","ચાંદી","તાંબુ","સોનું"],correctIndex:2,explanation:"માનવીએ પોતાના જીવનમાં સૌપ્રથમ વખત 'તાંબુ' ધાતુનો ઉપયોગ શરૂ કર્યો હતો."},{id:"ss_q02_05",questionText:"5) જોડકું ૫: ઊર્જાનો મુખ્ય સ્ત્રોત — ________ (ફેબ્રુઆરી-માર્ચ 2026)",options:["કોલસો","ખનિજ તેલ","પવન","સૂર્ય"],correctIndex:3,explanation:"સૂર્ય એ પૃથ્વી પર ઊર્જાનો મુખ્ય અને અખૂટ કુદરતી સ્ત્રોત છે."},{id:"ss_q02_06",questionText:"6) જોડકું ૬: કીર્તિ તોરણ — ________ (ફેબ્રુઆરી-માર્ચ 2025)",options:["સિધ્ધપુર","મોઢેરા","પાટણ","વડનગર"],correctIndex:3,explanation:"સોલંકીકાળનું સુપ્રસિદ્ધ સ્થાપત્ય 'કીર્તિ તોરણ' મહેસાણા જિલ્લાના વડનગરમાં આવેલું છે."},{id:"ss_q02_07",questionText:"7) જોડકું ૬: જરીકામ — ________ (ફેબ્રુઆરી-માર્ચ 2025)",options:["જયપુર","સુરત","પાટણ","વડનગર"],correctIndex:1,explanation:"ભારતમાં જરીકામ ઉદ્યોગ માટે ગુજરાતનું સુરત શહેર વિશેષ જાણીતું છે."},{id:"ss_q02_08",questionText:"8) જોડકું ૬: સ્તંભલેખો — ________ (ફેબ્રુઆરી-માર્ચ 2025)",options:["બ્રાહ્મી લિપિ","દેવનાગરી લિપિ","ખરોષ્ઠી લિપિ","ગુજરાતી લિપિ"],correctIndex:0,explanation:"સમ્રાટ અશોકના મોટાભાગના સ્તંભલેખો પ્રાકૃત ભાષા અને 'બ્રાહ્મી લિપિ'માં કોતરાયેલા છે."},{id:"ss_q02_09",questionText:"9) જોડકું ૬: એલિફન્ટા — ________ (ફેબ્રુઆરી-માર્ચ 2025)",options:["અજંતા","ધારાપુરી","ઈલોરા","બાઘ"],correctIndex:1,explanation:"મુંબઈ નજીક આવેલી એલિફન્ટાની ગુફાઓને સ્થાનિક માછીમારો 'ધારાપુરી' તરીકે ઓળખે છે."},{id:"ss_q02_10",questionText:"10) જોડકું ૬: ભારતીય સંગ્રહાલય — ________ (ફેબ્રુઆરી-માર્ચ 2025)",options:["મુંબઈ","ભોપાલ","કોલકાતા","નવી દિલ્હી"],correctIndex:2,explanation:"ભારતીય સંગ્રહાલય પશ્ચિમ બંગાળની રાજધાની કોલકાતામાં આવેલું છે."},{id:"ss_q02_11",questionText:"11) જોડકું ૭: ગૌતમ બુદ્ધની પ્રતિમા — ________",options:["વડનગર","ગિરનાર","સારનાથ","સિધ્ધપુર"],correctIndex:2,explanation:"સારનાથ ખાતે ગૌતમ બુદ્ધની ધર્મચક્ર પ્રવર્તન મુદ્રામાં અત્યંત સુંદર પ્રતિમા આવેલી છે."},{id:"ss_q02_12",questionText:"12) જોડકું ૭: ભવનાથનો મેળો — ________",options:["મોઢેરા","ગિરનાર","ધોળકા","સિધ્ધપુર"],correctIndex:1,explanation:"ભવનાથનો મહાશિવરાત્રી મેળો જૂનાગઢ ખાતે ગિરનારની તળેટીમાં ભરાય છે."},{id:"ss_q02_13",questionText:"13) જોડકું ૭: સૂર્યમંદિર — ________",options:["વડનગર","મોઢેરા","સારનાથ","ધોળકા"],correctIndex:1,explanation:"ગુજરાતનું વિશ્વપ્રસિદ્ધ સૂર્યમંદિર મહેસાણા જિલ્લાના મોઢેરા ખાતે આવેલું છે."},{id:"ss_q02_14",questionText:"14) જોડકું ૭: રુદ્રમહાલય — ________",options:["વડનગર","ગિરનાર","ધોળકા","સિધ્ધપુર"],correctIndex:3,explanation:"ભવ્ય સ્થાપત્ય 'રુદ્રમહાલય' પાટણ જિલ્લાના સિધ્ધપુર ખાતે આવેલો છે."},{id:"ss_q02_15",questionText:"15) જોડકું ૭: કીર્તિતોરણ — ________",options:["વડનગર","મોઢેરા","સારનાથ","સિધ્ધપુર"],correctIndex:0,explanation:"ઐતિહાસિક કીર્તિતોરણ ગુજરાતના વડનગર ખાતે આવેલું છે."},{id:"ss_q02_16",questionText:"16) જોડકું ૮: ભારતના સૌથી પ્રાચીન નિવાસી — ________",options:["અલ્પાઇન, ડિનારીક","નીગ્રો (હબસી)","ઓસ્ટ્રેલોઇડ (નિષાદ)","મોંગોલોઇડ (કિરાત)"],correctIndex:1,explanation:"કેટલાક ઇતિહાસકારોના મતે નીગ્રો અથવા નેગ્રીટો (હબસી) પ્રજા ભારતની સૌથી પ્રાચીન નિવાસી પ્રજા છે."},{id:"ss_q02_17",questionText:"17) જોડકું ૮: અગ્નિ એશિયા — ________",options:["આર્યો (નોર્ડિક)","નીગ્રો (હબસી)","ઓસ્ટ્રેલોઇડ (નિષાદ)","મોંગોલોઇડ (કિરાત)"],correctIndex:2,explanation:"ઓસ્ટ્રેલોઇડ (નિષાદ) પ્રજા અગ્નિ એશિયામાંથી ભારતમાં આવી હતી."},{id:"ss_q02_18",questionText:"18) જોડકું ૮: ઉત્તર પશ્ચિમ ચીન — ________",options:["અલ્પાઇન, ડિનારીક","આર્યો (નોર્ડિક)","ઓસ્ટ્રેલોઇડ (નિષાદ)","મોંગોલોઇડ (કિરાત)"],correctIndex:3,explanation:"મોંગોલોઇડ પ્રજા ઉત્તર પશ્ચિમ ચીનમાંથી તિબેટ થઈ ભારતમાં આવી હતી; પીળા વર્ણને લીધે તેઓ 'કિરાત' કહેવાતા."},{id:"ss_q02_19",questionText:"19) જોડકું ૮: મધ્ય એશિયા — ________",options:["અલ્પાઇન, ડિનારીક","આર્યો (નોર્ડિક)","નીગ્રો (હબસી)","તમિલ"],correctIndex:0,explanation:"અલ્પાઇન, ડિનારીક અને આર્મેનોઇડ પ્રજા મધ્ય એશિયામાંથી ભારતમાં આવી હતી."},{id:"ss_q02_20",questionText:"20) જોડકું ૮: ભારતની આર્ય સભ્યતાના નિર્માતા — ________",options:["અલ્પાઇન, ડિનારીક","આર્યો (નોર્ડિક)","ઓસ્ટ્રેલોઇડ (નિષાદ)","મોંગોલોઇડ (કિરાત)"],correctIndex:1,explanation:"ભારતની આર્ય સભ્યતાના નિર્માતાઓ 'આર્ય' (નોર્ડિક) લોકો હતા."}]},n={id:"social_q03",subjectId:"social_science",chapterNumber:"પ્રશ્ન 3",title:"જોડકા (જોડકું 9 થી 13)",subtitle:"વિભાગ A • 17 જોડકા પ્રશ્નો",questionTypeLabel:"જોડકા",questions:[{id:"ss_q03_01",questionText:"1) જોડકું ૯: કીર્તિ તોરણ — ________",options:["સિધ્ધપુર","વિરમગામ","જૂનાગઢ","વડનગર"],correctIndex:3,explanation:"કીર્તિ તોરણ મહેસાણા જિલ્લાના વડનગરમાં આવેલું પ્રસિદ્ધ સ્થાપત્ય છે."},{id:"ss_q03_02",questionText:"2) જોડકું ૯: રુદ્રમહાલય — ________",options:["સિધ્ધપુર","વિરમગામ","જૂનાગઢ","વડનગર"],correctIndex:0,explanation:"રુદ્રમહાલય પાટણ જિલ્લાના સિધ્ધપુર ખાતે આવેલું છે."},{id:"ss_q03_03",questionText:"3) જોડકું ૯: મુનસર તળાવ — ________",options:["સિધ્ધપુર","વિરમગામ","જૂનાગઢ","વડનગર"],correctIndex:1,explanation:"મીનળદેવીએ બંધાવેલું ઐતિહાસિક મુનસર તળાવ વિરમગામમાં આવેલું છે."},{id:"ss_q03_04",questionText:"4) જોડકું ૧૦: જામા મસ્જિદ — ________",options:["પાટણ","અમદાવાદ","સિધ્ધપુર","જૂનાગઢ"],correctIndex:1,explanation:"પ્રસિદ્ધ જામા મસ્જિદ અમદાવાદમાં આવેલી છે, જેનું નિર્માણ બાદશાહ અહમદશાહે કરાવ્યું હતું."},{id:"ss_q03_05",questionText:"5) જોડકું ૧૦: સહસ્ત્રલિંગ તળાવ — ________",options:["પાટણ","અમદાવાદ","સિધ્ધપુર","જૂનાગઢ"],correctIndex:0,explanation:"સિદ્ધરાજ જયસિંહે બંધાવેલું સહસ્ત્રલિંગ તળાવ પાટણમાં આવેલું છે."},{id:"ss_q03_06",questionText:"6) જોડકું ૧૦: મહોબતખાનનો મકબરો — ________",options:["પાટણ","અમદાવાદ","સિધ્ધપુર","જૂનાગઢ"],correctIndex:3,explanation:"મહોબતખાનનો કલાત્મક મકબરો જૂનાગઢમાં આવેલો છે."},{id:"ss_q03_07",questionText:"7) જોડકું ૧૧: પોળો ઉત્સવ — ________",options:["વડનગર","મોઢેરા","વિજયનગર","અમદાવાદ"],correctIndex:2,explanation:"પોળો ઉત્સવ સાબરકાંઠા જિલ્લાના વિજયનગર (પોળોના જંગલો) ખાતે ઉજવાય છે."},{id:"ss_q03_08",questionText:"8) જોડકું ૧૧: પતંગોત્સવ — ________",options:["વડનગર","મોઢેરા","વિજયનગર","અમદાવાદ"],correctIndex:3,explanation:"આંતરરાષ્ટ્રીય પતંગોત્સવ અમદાવાદમાં સાબરમતી રિવરફ્રન્ટ ખાતે ધામધૂમથી ઉજવાય છે."},{id:"ss_q03_09",questionText:"9) જોડકું ૧૧: તાના-રીરી મહોત્સવ — ________",options:["વડનગર","મોઢેરા","વિજયનગર","અમદાવાદ"],correctIndex:0,explanation:"શાસ્ત્રીય સંગીતની બહેનો તાના-રીરીની યાદમાં તાના-રીરી મહોત્સવ વડનગરમાં ઉજવાય છે."},{id:"ss_q03_10",questionText:"10) જોડકું ૧૨: જરીકામ — ________",options:["સંખેડા","ખંભાત","બિકાનેર","સુરત"],correctIndex:3,explanation:"સુરત તેના જરીકામ માટે સમગ્ર વિશ્વમાં પ્રખ્યાત છે."},{id:"ss_q03_11",questionText:"11) જોડકું ૧૨: જડતર કામ — ________",options:["સંખેડા","ખંભાત","બિકાનેર","સુરત"],correctIndex:2,explanation:"સોના-ચાંદીના દાગીનામાં રત્નો જડવાની કલા માટે રાજસ્થાનનું બિકાનેર વિશેષ જાણીતું છે."},{id:"ss_q03_12",questionText:"12) જોડકું ૧૨: અકીકકામ — ________",options:["સંખેડા","ખંભાત","બિકાનેર","અમદાવાદ"],correctIndex:1,explanation:"અકીકના પથ્થરો પર પહેલ પાડીને સુંદર ઘરેણાં બનાવવાનું અકીકકામ ખંભાતમાં થાય છે."},{id:"ss_q03_13",questionText:"13) જોડકું ૧૨: લાકડાના હિંચકા — ________",options:["સંખેડા","ખંભાત","બિકાનેર","અમદાવાદ"],correctIndex:0,explanation:"ગુજરાતમાં છોટાઉદેપુર જિલ્લાનું સંખેડા ગામ લાકડાના કલાત્મક હિંચકા અને ફર્નિચર માટે પ્રખ્યાત છે."},{id:"ss_q03_14",questionText:"14) જોડકું ૧૩: વિશ્વ યોગ દિવસ — ________",options:["૫ જૂન","૨૧ જૂન","૨૨ એપ્રિલ","૧૬ સપ્ટેમ્બર"],correctIndex:1,explanation:"સંયુક્ત રાષ્ટ્ર દ્વારા દર વર્ષે ૨૧ જૂનને 'વિશ્વ યોગ દિવસ' તરીકે ઉજવવામાં આવે છે."},{id:"ss_q03_15",questionText:"15) જોડકું ૧૩: પાટણના પટોળા — ________",options:["બાંધણી કલા","જરીકામ","બેવડ - ઇક્ત","ભરતગૂંથણ"],correctIndex:2,explanation:"પાટણના પટોળા તેની 'બેવડ-ઇક્ત' (બંને બાજુ એકસરખી ભાત) વણાટકલા માટે જગવિખ્યાત છે."},{id:"ss_q03_16",questionText:"16) જોડકું ૧૩: મીના કારીગરી — ________",options:["સુરત","જયપુર","ખંભાત","ભુજ"],correctIndex:1,explanation:"સોના-ચાંદીના અલંકારોમાં મીના કારીગરી માટે રાજસ્થાનનું જયપુર શહેર પ્રખ્યાત છે."},{id:"ss_q03_17",questionText:"17) જોડકું ૧૩: પ્રાચીન ભારતનું પ્રથમ યંત્ર — ________",options:["કુંભારનો ચાકડો","હળ","રેંટિયો","ખરલ"],correctIndex:0,explanation:"માટીકામ માટે વપરાતો 'કુંભારનો ચાકડો' પ્રાચીન ભારતનું પ્રથમ યંત્ર ગણાય છે."}]},o={id:"social_q04",subjectId:"social_science",chapterNumber:"પ્રશ્ન 4",title:"જોડકા (જોડકું 14 થી 17)",subtitle:"વિભાગ A • 12 જોડકા પ્રશ્નો",questionTypeLabel:"જોડકા",questions:[{id:"ss_q04_01",questionText:"1) જોડકું ૧૪: જામનગર — ________",options:["જરીકામ","લાકડાનું ફર્નિચર","મીનાકારીગરી","બાંધણી"],correctIndex:3,explanation:"ગુજરાતમાં જામનગર, જેતપુર, ભુજ અને માંડવી બાંધણી માટે ખૂબ જ જાણીતા છે."},{id:"ss_q04_02",questionText:"2) જોડકું ૧૪: લખનૌ — ________",options:["જરીકામ","લાકડાનું ફર્નિચર","મીનાકારીગરી","બાંધણી"],correctIndex:2,explanation:"ભારતમાં જયપુર, લખનૌ, દિલ્હી અને વારાણસી મીનાકારીગરી માટે પ્રખ્યાત છે."},{id:"ss_q04_03",questionText:"3) જોડકું ૧૪: સુરત — ________",options:["જરીકામ","લાકડાનું ફર્નિચર","મીનાકારીગરી","બાંધણી"],correctIndex:0,explanation:"સુરત તેના જરીકામ માટે સમગ્ર દેશમાં પ્રખ્યાત છે."},{id:"ss_q04_04",questionText:"4) જોડકું ૧૫: રમકડાં — ________",options:["પાટણ","ઢાકા","ઈડર","ખંભાત"],correctIndex:2,explanation:"ગુજરાતમાં ઈડર લાકડાના રમકડાં બનાવવા માટે જાણીતું છે."},{id:"ss_q04_05",questionText:"5) જોડકું ૧૫: અકીક — ________",options:["પાટણ","ઢાકા","ઈડર","ખંભાત"],correctIndex:3,explanation:"અકીકના પથ્થરો પર કારીગરી કરવા માટે ખંભાત શહેર પ્રખ્યાત છે."},{id:"ss_q04_06",questionText:"6) જોડકું ૧૫: મલમલ — ________",options:["પાટણ","ઢાકા","ઈડર","ખંભાત"],correctIndex:1,explanation:"પ્રાચીન સમયમાં ઢાકાનું મલમલ ખૂબ જ પ્રખ્યાત હતું, જેનો તાકો દિવાસળીની પેટીમાં સમાઈ જતો."},{id:"ss_q04_07",questionText:"7) જોડકું ૧૬: સંગીત મકરંદ — ________",options:["પંડિત અહોબલો","બૈજુ બાવરા","પંડિત સારંગદેવ","નારદ"],correctIndex:3,explanation:"સંગીત શાસ્ત્રજ્ઞ નારદે ઈ.સ. 900ની આસપાસ 'સંગીત મકરંદ' ગ્રંથ લખ્યો હતો."},{id:"ss_q04_08",questionText:"8) જોડકું ૧૬: સંગીત રત્નાકર — ________",options:["પંડિત અહોબલો","બૈજુ બાવરા","પંડિત સારંગદેવ","નારદ"],correctIndex:2,explanation:"પંડિત સારંગદેવે 'સંગીત રત્નાકર' નામના પ્રમાણભૂત સંગીત ગ્રંથની રચના કરી હતી."},{id:"ss_q04_09",questionText:"9) જોડકું ૧૬: સંગીત પારિજાત — ________",options:["પંડિત અહોબલો","બૈજુ બાવરા","પંડિત સારંગદેવ","નારદ"],correctIndex:0,explanation:"પંડિત અહોબલે 'સંગીત પારિજાત' ગ્રંથ લખીને 29 પ્રકારના સ્વરો વર્ણવ્યા હતા."},{id:"ss_q04_10",questionText:"10) જોડકું ૧૭: ભરતનાટ્યમ્ — ________",options:["શોભા નાયડુ","હેમામાલિની","નયના ઝવેરી","સિતારા દેવી"],correctIndex:1,explanation:"હેમામાલિની, મૃણાલિની સારાભાઈ અને વૈજયંતીમાલા ભરતનાટ્યમ્ નૃત્યના પ્રખ્યાત કલાકારો છે."},{id:"ss_q04_11",questionText:"11) જોડકું ૧૭: કુચીપુડી નૃત્યશૈલી — ________",options:["શોભા નાયડુ","હેમામાલિની","નયના ઝવેરી","સિતારા દેવી"],correctIndex:0,explanation:"શોભા નાયડુ, રાજા રેડ્ડી અને યામિની રેડ્ડી કુચીપુડી નૃત્યશૈલીના જાણીતા નર્તકો છે."},{id:"ss_q04_12",questionText:"12) જોડકું ૧૭: કથક નૃત્ય — ________",options:["શોભા નાયડુ","હેમામાલિની","નયના ઝવેરી","સિતારા દેવી"],correctIndex:3,explanation:"સિતારા દેવી, પંડિત બિરજુ મહારાજ અને કુમુદિની લાખિયા કથક નૃત્ય સાથે સંકળાયેલા છે."}]},s={id:"social_q05",subjectId:"social_science",chapterNumber:"પ્રશ્ન 5",title:"જોડકા (જોડકું 18 થી 21)",subtitle:"વિભાગ A • 14 જોડકા પ્રશ્નો",questionTypeLabel:"જોડકા",questions:[{id:"ss_q05_01",questionText:"1) જોડકું ૧૮: હિમ દિપડો — ________",options:["દક્ષિણ ભારતના વરસાદી જંગલો","કચ્છનું નાનું રણ","હિમાલયની ૩૦૦૦ મીટરની ઊંચાઈએ","સુંદરવનના મેન્ગ્રુવ જંગલો"],correctIndex:2,explanation:"હિમ દિપડો હિમાલયના ઊંચાઈવાળા પ્રદેશોમાં આશરે ૩૦૦૦ મીટરની ઊંચાઈએ બરફમાં જોવા મળે છે."},{id:"ss_q05_02",questionText:"2) જોડકું ૧૮: લાલપાંડા — ________",options:["કાંટાળા જંગલો","શીતવનો","રણપ્રદેશ","ખારા પાણીના જંગલો"],correctIndex:1,explanation:"લાલપાંડા ભારતના પૂર્વ હિમાલયના શીતવનોમાં (સિક્કિમ, અરુણાચલ પ્રદેશ) જોવા મળે છે."},{id:"ss_q05_03",questionText:"3) જોડકું ૧૮: કેવલા દેવ — ________",options:["ગુજરાત","મધ્યપ્રદેશ","ઉત્તરપ્રદેશ","રાજસ્થાન"],correctIndex:3,explanation:"કેવલાદેવ રાષ્ટ્રીય ઉદ્યાન (ભરતપુર) રાજસ્થાન રાજ્યમાં આવેલું પ્રસિદ્ધ પક્ષી અભયારણ્ય છે."},{id:"ss_q05_04",questionText:"4) જોડકું ૧૮: નળ સરોવર — ________",options:["ગુજરાત","મધ્યપ્રદેશ","ઉત્તરપ્રદેશ","રાજસ્થાન"],correctIndex:0,explanation:"નળ સરોવર પક્ષી અભયારણ્ય ગુજરાત રાજ્યમાં અમદાવાદ-સુરેન્દ્રનગર જિલ્લાની સરહદે આવેલું છે."},{id:"ss_q05_05",questionText:"5) જોડકું ૧૯: બિલાડી કુળનું પ્રાણી — ________",options:["ઘુડખર","દીપડો","એકશિંગી ગેંડો","લાલ પાંડા"],correctIndex:1,explanation:"દીપડો, વાઘ, સિંહ અને ચિત્તો બિલાડી કુળનાં પ્રાણીઓ છે."},{id:"ss_q05_06",questionText:"6) જોડકું ૧૯: અભયારણ્ય — ________",options:["ગીર રાષ્ટ્રીય ઉદ્યાન","કાઝીરંગા રાષ્ટ્રીય ઉદ્યાન","ચંદ્રપ્રભા","સુંદરવન રાષ્ટ્રીય ઉદ્યાન"],correctIndex:2,explanation:"ચંદ્રપ્રભા વન્યજીવ અભયારણ્ય ઉત્તર પ્રદેશમાં આવેલું પ્રસિદ્ધ અભયારણ્ય છે."},{id:"ss_q05_07",questionText:"7) જોડકું ૧૯: રાષ્ટ્રીય ઉદ્યાન — ________",options:["ચંદ્રપ્રભા અભયારણ્ય","એતુરાનગરમ અભયારણ્ય","નળ સરોવર અભયારણ્ય","કાઝીરંગા"],correctIndex:3,explanation:"કાઝીરંગા (અસમ) ભારતનું સુપ્રસિદ્ધ રાષ્ટ્રીય ઉદ્યાન છે."},{id:"ss_q05_08",questionText:"8) જોડકું ૧૯: જૈવ આરક્ષિત ક્ષેત્ર — ________",options:["કચ્છનું રણ","ચંદ્રપ્રભા અભયારણ્ય","નળ સરોવર અભયારણ્ય","વેળાવદર રાષ્ટ્રીય ઉદ્યાન"],correctIndex:0,explanation:"ગુજરાતના કચ્છના રણને ઈ.સ. 2008માં જૈવ આરક્ષિત ક્ષેત્ર (Biosphere Reserve) ઘોષિત કરવામાં આવ્યું છે."},{id:"ss_q05_09",questionText:"9) જોડકું ૨૦: બાયોગેસ પ્લાન્ટ — ________",options:["લાંબા","લુણેજ","માધોપુર","મેથાણ"],correctIndex:1,explanation:"આપેલા જોડકાં ૨૦માં બાયોગેસ પ્લાન્ટ માટે 'લુણેજ' (અથવા મેથાણ/રુદાતલ) સાચો વિકલ્પ આપવામાં આવ્યો છે (PDF ઉત્તર કી મુજબ: લુણેજ)."},{id:"ss_q05_10",questionText:"10) જોડકું ૨૦: સૌર ઉર્જા પ્લાન્ટ — ________",options:["લાંબા","લુણેજ","માધોપુર","મેથાણ"],correctIndex:2,explanation:"ગુજરાતમાં ભુજ પાસે માધોપુર ખાતે દરિયાનું ખારું પાણી મીઠું બનાવવાનો સૌર ઊર્જા પ્લાન્ટ સ્થાપવામાં આવ્યો છે."},{id:"ss_q05_11",questionText:"11) જોડકું ૨૦: વિન્ડ ફાર્મ — ________",options:["લાંબા","લુણેજ","માધોપુર","મેથાણ"],correctIndex:0,explanation:"જામનગર જિલ્લાના લાંબા ગામે અને કચ્છના માંડવીના દરિયાકિનારે વિન્ડ ફાર્મ આવેલાં છે."},{id:"ss_q05_12",questionText:"12) જોડકું ૨૧: કીમતી ધાતુમય ખનીજો — ________",options:["મેગ્નેશિયમ","પ્લેટિનમ","ક્રોમિયમ","લોખંડ"],correctIndex:1,explanation:"સોનું, ચાંદી અને પ્લેટિનમ એ કીમતી ધાતુમય ખનીજો છે."},{id:"ss_q05_13",questionText:"13) જોડકું ૨૧: હલકી ધાતુમય ખનીજો — ________",options:["મેગ્નેશિયમ","પ્લેટિનમ","ક્રોમિયમ","લોખંડ"],correctIndex:0,explanation:"મેગ્નેશિયમ, બોક્સાઇટ અને ટિટેનિયમ એ હલકી ધાતુમય ખનીજો છે."},{id:"ss_q05_14",questionText:"14) જોડકું ૨૧: સામાન્ય ઉપયોગમાં લેવાતાં ખનીજો — ________",options:["મેગ્નેશિયમ","પ્લેટિનમ","ક્રોમિયમ","લોખંડ"],correctIndex:3,explanation:"લોખંડ, તાંબુ, સીસું, જસત અને કલાઈ એ સામાન્ય ઉપયોગમાં લેવાતાં ખનીજો છે."}]},i={id:"social_q06",subjectId:"social_science",chapterNumber:"પ્રશ્ન 6",title:"સાહિત્ય અને વન્યજીવ (ખરા-ખોટા)",subtitle:"વિભાગ A • 31 ખરા-ખોટા પ્રશ્નો",questionTypeLabel:"ખરા-ખોટા",questions:[{id:"ss_q06_01",questionText:"1) અથર્વવેદમાં અનેક પ્રકારના કર્મકાંડો અને સંસ્કારોનું વર્ણન કરવામાં આવ્યું છે. (માર્ચ 2026)",options:["ખરું","ખોટું"],correctIndex:0,explanation:"સાચું વિધાન (ખરું): ભારતના ચાર વેદો પૈકી અથર્વવેદમાં અનેક પ્રકારના કર્મકાંડો અને સંસ્કારોનું વર્ણન કરવામાં આવ્યું છે."},{id:"ss_q06_02",questionText:"2) તત્વજ્ઞાનથી ભરપૂર એવા સાહિત્યને 'આરણ્યકો' કહે છે. (માર્ચ 2024)",options:["ખરું","ખોટું"],correctIndex:0,explanation:"સાચું વિધાન (ખરું): આર્યોએ જીવનનો અંતિમ સમય અરણ્યમાં ગાળીને આશ્રમમાં તત્વજ્ઞાનથી ભરપૂર જે સાહિત્યની રચના કરી તેને 'આરણ્યકો' કહે છે."},{id:"ss_q06_03",questionText:"3) બિહારના પટણા જિલ્લાના બડગાંવ નામના ગામ પાસે પ્રાચીન તક્ષશિલા વિદ્યાપીઠ આવેલી છે. (નમૂના પ્રશ્નપત્ર 2024-25)",options:["ખરું","ખોટું"],correctIndex:1,explanation:"ખોટું વિધાન: બિહારના પટણા જિલ્લાના બડગાંવ પાસે પ્રાચીન 'નાલંદા' વિદ્યાપીઠ આવેલી હતી, જ્યારે તક્ષશિલા હાલ પાકિસ્તાનના રાવલપિંડી પાસે આવેલી હતી."},{id:"ss_q06_04",questionText:"4) સોમદેવે કથાસરિતસાગર ગ્રંથની રચના કરી.",options:["ખરું","ખોટું"],correctIndex:0,explanation:"સાચું વિધાન (ખરું): કવિ સોમદેવે સંસ્કૃત સાહિત્યમાં પ્રખ્યાત ગ્રંથ 'કથાસરિતસાગર'ની રચના કરી હતી."},{id:"ss_q06_05",questionText:"5) ભારતનો પ્રથમ ઐતિહાસિક ગ્રંથ રાજતરંગિણી છે.",options:["ખરું","ખોટું"],correctIndex:0,explanation:"સાચું વિધાન (ખરું): કલ્હણ દ્વારા રચિત કાશ્મીરનો ઇતિહાસ દર્શાવતો 'રાજતરંગિણી' ભારતનો પ્રથમ ઐતિહાસિક ગ્રંથ ગણાય છે."},{id:"ss_q06_06",questionText:"6) કવિ પંપા, પોન્ના અને રન્નાને કન્નડ સાહિત્યના ત્રિમૂર્તિ તરીકે ઓળખવામાં આવે છે.",options:["ખરું","ખોટું"],correctIndex:0,explanation:"સાચું વિધાન (ખરું): કવિ પંપા, પોન્ના અને રન્ના કન્નડ સાહિત્યના 'રત્નત્રયી' (ત્રિમૂર્તિ) તરીકે ઓળખાય છે."},{id:"ss_q06_07",questionText:"7) અમીર ખુશરોના ગુરુ હઝરત નિઝામુદ્દીન ઔલિયા હતાં.",options:["ખરું","ખોટું"],correctIndex:0,explanation:"સાચું વિધાન (ખરું): મધ્યયુગના મહાન કવિ અમીર ખુશરો સુફી સંત હઝરત નિઝામુદ્દીન ઔલિયાના પરમ શિષ્ય હતા."},{id:"ss_q06_08",questionText:"8) કૃષ્ણદેવરાય દ્વારા આમુક્તમાલ્યદા નામના ગ્રંથની રચના કરવામાં આવી હતી.",options:["ખરું","ખોટું"],correctIndex:0,explanation:"સાચું વિધાન (ખરું): વિજયનગરના મહાન સમ્રાટ કૃષ્ણદેવરાયે તેલુગુ ભાષામાં 'આમુક્તમાલ્યદા' ગ્રંથની રચના કરી હતી."},{id:"ss_q06_09",questionText:"9) આયને અકબરી અને અકબરનામાની રચના ફૈઝીએ કરી હતી.",options:["ખરું","ખોટું"],correctIndex:1,explanation:"ખોટું વિધાન: 'આઈને અકબરી' અને 'અકબરનામા' જેવા ઐતિહાસિક ગ્રંથોની રચના ફૈઝીએ નહીં પરંતુ 'અબુલ ફઝલે' કરી હતી."},{id:"ss_q06_10",questionText:"10) મધ્યયુગની સૌથી મહત્વની ઘટના ઉર્દૂ ભાષાનો જન્મ ગણાય છે.",options:["ખરું","ખોટું"],correctIndex:0,explanation:"સાચું વિધાન (ખરું): મધ્યયુગ દરમિયાન વિવિધ ભાષાઓના સમન્વયથી ઉર્દૂ ભાષાનો જન્મ થયો તે સૌથી મહત્વની ઘટના ગણાય છે."},{id:"ss_q06_11",questionText:"11) મુહમ્મદ હુસેન આઝાદનો 'દરબારે અકબરી' જાણીતો ગ્રંથ છે.",options:["ખરું","ખોટું"],correctIndex:0,explanation:"સાચું વિધાન (ખરું): મુહમ્મદ હુસેન આઝાદ રચિત 'દરબારે અકબરી' ઉર્દૂ ગદ્ય સાહિત્યનો મહત્વનો અને જાણીતો ગ્રંથ છે."},{id:"ss_q06_12",questionText:"12) મહર્ષિ પાણિનિ સંસ્કૃત ભાષાના મહાન વ્યાકરણશાસ્ત્રી હતા.",options:["ખરું","ખોટું"],correctIndex:0,explanation:"સાચું વિધાન (ખરું): મહર્ષિ પાણિનિએ સંસ્કૃત વ્યાકરણનો વિશ્વપ્રસિદ્ધ ગ્રંથ 'અષ્ટાધ્યાયી' રચ્યો હતો."},{id:"ss_q06_13",questionText:"13) કૌટિલ્યનું અર્થશાસ્ત્ર વહીવટી વિજ્ઞાનની કૃતિ છે.",options:["ખરું","ખોટું"],correctIndex:0,explanation:"સાચું વિધાન (ખરું): કૌટિલ્ય (ચાણક્ય) દ્વારા રચિત 'અર્થશાસ્ત્ર' રાજ્યવ્યવસ્થા અને વહીવટી વિજ્ઞાનનો અજોડ ગ્રંથ છે."},{id:"ss_q06_14",questionText:"14) નાલંદા વિદ્યાપીઠના બૌદ્ધ આચાર્ય નાગાર્જુન હતા.",options:["ખરું","ખોટું"],correctIndex:0,explanation:"સાચું વિધાન (ખરું): પ્રખ્યાત રસાયણશાસ્ત્રી અને બૌદ્ધ આચાર્ય નાગાર્જુન નાલંદા વિદ્યાપીઠના આચાર્ય હતા."},{id:"ss_q06_15",questionText:"15) વલભી એક રાજધાની અને આંતરરાષ્ટ્રીય બંદર હતું.",options:["ખરું","ખોટું"],correctIndex:0,explanation:"સાચું વિધાન (ખરું): મૈત્રક વંશના સમયમાં વલભી (વલભીપુર) એક મહાન રાજધાની, આંતરરાષ્ટ્રીય બંદર અને વિદ્યાધામ હતું."},{id:"ss_q06_16",questionText:"16) અનામત જંગલમાં લાકડાં વીણવાં તથા પશુચરાણ માટે સ્થાનિક લોકોને પ્રવેશવાની છૂટ હોય છે. (માર્ચ 2025)",options:["ખરું","ખોટું"],correctIndex:1,explanation:"ખોટું વિધાન: અનામત જંગલોમાં લાકડાં કાપવા કે પશુ ચરાવવા પર સંપૂર્ણ પ્રતિબંધ હોય છે; આવી છૂટ 'સંરક્ષિત જંગલો'માં મળે છે."},{id:"ss_q06_17",questionText:"17) રાષ્ટ્રીય ઉદ્યાનની રચના આંતરરાષ્ટ્રીય માપદંડ પ્રમાણે કરવામાં આવે છે.",options:["ખરું","ખોટું"],correctIndex:1,explanation:"ખોટું વિધાન: આંતરરાષ્ટ્રીય માપદંડ પ્રમાણે 'જૈવ આરક્ષિત ક્ષેત્ર' (Biosphere Reserve) ની રચના કરવામાં આવે છે, રાષ્ટ્રીય ઉદ્યાનની નહીં."},{id:"ss_q06_18",questionText:"18) નિર્વનીકરણ એટલે જંગલોનું નષ્ટ થવું.",options:["ખરું","ખોટું"],correctIndex:0,explanation:"સાચું વિધાન (ખરું): જંગલોનો વિનાશ થવો કે જંગલ વિસ્તારો નષ્ટ થવા તેને 'નિર્વનીકરણ' કહેવાય છે."},{id:"ss_q06_19",questionText:"19) નિર્વનીકરણ એ માનવીની વિકાસ યાત્રાનું પરિણામ છે.",options:["ખરું","ખોટું"],correctIndex:0,explanation:"સાચું વિધાન (ખરું): શહેરીકરણ, ઔદ્યોગિકરણ અને ખેતી માટે જંગલો કપાતા નિર્વનીકરણ એ માનવીની વિકાસયાત્રાનું પરિણામ ગણાય છે."},{id:"ss_q06_20",questionText:"20) ભારતમાં વાઘ અને સિંહ તેમના કુદરતી આવાસોમાં વિચરે છે.",options:["ખરું","ખોટું"],correctIndex:0,explanation:"સાચું વિધાન (ખરું): ભારત વિશ્વનો એવો દેશ છે જ્યાં વાઘ અને સિંહ બંને તેમના કુદરતી આવાસોમાં વિચરે છે."},{id:"ss_q06_21",questionText:"21) ભારતના જંગલોમાંથી ચિત્તો નષ્ટ થઈ ચૂક્યો છે.",options:["ખરું","ખોટું"],correctIndex:0,explanation:"સાચું વિધાન (ખરું): પાઠ્યપુસ્તક મુજબ ભારતના જંગલોમાંથી ચિત્તો સંપૂર્ણપણે નષ્ટ થઈ ચૂક્યો છે."},{id:"ss_q06_22",questionText:"22) એક શિંગી ભારતીય ગેંડો માંસાહારી જીવ છે.",options:["ખરું","ખોટું"],correctIndex:1,explanation:"ખોટું વિધાન: એક શિંગી ભારતીય ગેંડો માંસાહારી નહીં પરંતુ 'તૃણાહારી' (શાકાહારી) જીવ છે."},{id:"ss_q06_23",questionText:"23) અભયારણ્યમાં માનવીય પ્રવૃત્તિઓ કરવા પર સંપૂર્ણ પ્રતિબંધ હોય છે.",options:["ખરું","ખોટું"],correctIndex:1,explanation:"ખોટું વિધાન: અભયારણ્યમાં ચોક્કસ મર્યાદામાં અને પૂર્વમંજૂરી બાદ માનવીય પ્રવૃત્તિઓની છૂટ હોય છે; સંપૂર્ણ પ્રતિબંધ જૈવ આરક્ષિત ક્ષેત્રમાં હોય છે."},{id:"ss_q06_24",questionText:"24) ભારતમાં 103 રાષ્ટ્રીય ઉદ્યાનો અને 531 અભયારણ્યો છે.",options:["ખરું","ખોટું"],correctIndex:0,explanation:"સાચું વિધાન (ખરું): પાઠ્યપુસ્તકના આંકડાઓ મુજબ ભારતમાં 103 રાષ્ટ્રીય ઉદ્યાનો અને 531 અભયારણ્યો આવેલા છે."},{id:"ss_q06_25",questionText:"25) ભારતમાં જૈવ આરક્ષિત ક્ષેત્રોની સંખ્યા 12 છે.",options:["ખરું","ખોટું"],correctIndex:1,explanation:"ખોટું વિધાન: ભારતમાં કુલ જૈવ આરક્ષિત ક્ષેત્રોની સંખ્યા 12 નહીં પરંતુ '18' છે."},{id:"ss_q06_26",questionText:"26) ભારતમાં પશુ-પક્ષીઓની કુલ 81,251 જેટલી પ્રજાતિઓ છે.",options:["ખરું","ખોટું"],correctIndex:0,explanation:"સાચું વિધાન (ખરું): ભારતમાં પશુ-પક્ષીઓની આશરે 81,251 જેટલી પ્રજાતિઓ જોવા મળે છે."},{id:"ss_q06_27",questionText:"27) ગંગેય ડોલ્ફિન ખારા પાણીની પ્રજાતિ છે.",options:["ખરું","ખોટું"],correctIndex:1,explanation:"ખોટું વિધાન: ગંગેય ડોલ્ફિન ખારા પાણીની નહીં પરંતુ 'મીઠા પાણીની' (નદીના પાણીની) પ્રજાતિ છે."},{id:"ss_q06_28",questionText:"28) વિશ્વમાં પશુ-પક્ષીઓની લગભગ પંદર લાખ પ્રજાતિ છે.",options:["ખરું","ખોટું"],correctIndex:0,explanation:"સાચું વિધાન (ખરું): સમગ્ર વિશ્વમાં પશુ-પક્ષીઓની અંદાજે પંદર લાખ જેટલી પ્રજાતિઓ નોંધાયેલી છે."},{id:"ss_q06_29",questionText:"29) વાઘ પરિયોજના 2002 માં શરૂ થઈ હતી.",options:["ખરું","ખોટું"],correctIndex:1,explanation:"ખોટું વિધાન: વાઘ પરિયોજના 2002માં નહીં પરંતુ ઈ.સ. 1971માં (પાઠ્યપુસ્તક મુજબ 1971) શરૂ કરવામાં આવી હતી."},{id:"ss_q06_30",questionText:"30) હાલ દેશમાં હાથીઓ માટે કુલ 26 જેટલાં સંરક્ષિત વિસ્તારો છે.",options:["ખરું","ખોટું"],correctIndex:0,explanation:"સાચું વિધાન (ખરું): હાથી પરિયોજના હેઠળ હાલ દેશમાં કુલ 26 જેટલાં સંરક્ષિત વિસ્તારો કાર્યરત છે."},{id:"ss_q06_31",questionText:"31) કચ્છના રણને 2008 માં જૈવ આરક્ષિત ક્ષેત્ર ઘોષિત કરાયું છે.",options:["ખરું","ખોટું"],correctIndex:0,explanation:"સાચું વિધાન (ખરું): ગુજરાતના કચ્છના રણની વિશિષ્ટ પરિસ્થિતિના સંરક્ષણ માટે તેને ઈ.સ. 2008માં જૈવ આરક્ષિત ક્ષેત્ર જાહેર કરાયું છે."}]},_={id:"social_q07",subjectId:"social_science",chapterNumber:"પ્રશ્ન 7",title:"ભારતનો વારસો અને સ્થાપત્ય (ખરા-ખોટા)",subtitle:"વિભાગ A • 25 ખરા-ખોટા પ્રશ્નો",questionTypeLabel:"ખરા-ખોટા",questions:[{id:"ss_q07_01",questionText:"1) લોથલ અમદાવાદ જિલ્લાના ધંધુકા તાલુકામાં આવેલું છે. (નમૂના પ્રશ્નપત્ર 2024-25)",options:["ખરું","ખોટું"],correctIndex:1,explanation:"ખોટું વિધાન: લોથલ અમદાવાદ જિલ્લાના ધંધુકા નહીં પરંતુ 'ધોળકા' તાલુકામાં ભોગાવો અને સાબરમતી નદી વચ્ચે આવેલું છે."},{id:"ss_q07_02",questionText:"2) ભારતીય સંસ્કૃતિ સતલજ અને રાવી નદીને કિનારે વિકસી હતી.",options:["ખરું","ખોટું"],correctIndex:1,explanation:"ખોટું વિધાન: ભારતીય સંસ્કૃતિ સતલજ અને રાવી નહીં પરંતુ 'સિંધુ અને રાવી' નદીના કિનારે પાંગરી અને વિકસી હતી."},{id:"ss_q07_03",questionText:"3) દ્રવિડો પાષાણયુગની સંસ્કૃતિના સીધા વારસદાર છે.",options:["ખરું","ખોટું"],correctIndex:0,explanation:"સાચું વિધાન (ખરું): દ્રવિડો મોહેં-જો-દડોની સિંધુ સંસ્કૃતિના સર્જકો અને પાષાણયુગની સંસ્કૃતિના સીધા વારસદાર ગણાય છે."},{id:"ss_q07_04",questionText:"4) હિમાલયમાં અમરનાથ અને કેદારનાથ શિખરો છે.",options:["ખરું","ખોટું"],correctIndex:1,explanation:"ખોટું વિધાન: અમરનાથ, બદ્રીનાથ અને કેદારનાથ હિમાલયનાં શિખરો નહીં પરંતુ પવિત્ર 'યાત્રાધામો' (તીર્થસ્થાનો) છે."},{id:"ss_q07_05",questionText:"5) આદિમાનવ ભારતમાં તેમજ પૂર્વ આફ્રિકામાં એક સાથે ઉત્પન્ન થયા.",options:["ખરું","ખોટું"],correctIndex:0,explanation:"સાચું વિધાન (ખરું): પાઠ્યપુસ્તક મુજબ આદિમાનવ પૂર્વ દક્ષિણ આફ્રિકામાં ઉત્પન્ન થયા અને ભારતમાં પણ પ્રાચીન સમયથી આદિમાનવના અસ્તિત્વના પુરાવા મળ્યા છે (PDF ઉત્તર કી: ખરું)."},{id:"ss_q07_06",questionText:"6) ભારતમાં શિલ્પ-સ્થાપત્યની કલા આશરે 5000 વર્ષ જેટલી પ્રાચીન છે.",options:["ખરું","ખોટું"],correctIndex:0,explanation:"સાચું વિધાન (ખરું): સિંધુ ખીણની સંસ્કૃતિના સમયથી ભારતમાં શિલ્પ-સ્થાપત્યની કલા આશરે 5000 વર્ષ જેટલી પ્રાચીન છે."},{id:"ss_q07_07",questionText:"7) ભારત વિસ્તારની દૃષ્ટિએ વિશ્વમાં સાતમા ક્રમે આવે છે.",options:["ખરું","ખોટું"],correctIndex:0,explanation:"સાચું વિધાન (ખરું): ભારત ક્ષેત્રફળની દ્રષ્ટિએ વિશ્વમાં 7મા અને વસ્તીની દ્રષ્ટિએ બીજા (તાજેતરમાં પ્રથમ) ક્રમે છે."},{id:"ss_q07_08",questionText:"8) ભારતની આર્ય સભ્યતાના નિર્માતાઓ આર્ય લોકો હતા.",options:["ખરું","ખોટું"],correctIndex:0,explanation:"સાચું વિધાન (ખરું): ભારતની પ્રાચીન આર્ય સભ્યતાના નિર્માતાઓ આર્ય (નોર્ડિક) લોકો હતા."},{id:"ss_q07_09",questionText:"9) વડ સાવિત્રી વ્રતમાં વડની પૂજા કરવામાં આવે છે.",options:["ખરું","ખોટું"],correctIndex:0,explanation:"સાચું વિધાન (ખરું): ભારતીય સંસ્કૃતિમાં પ્રકૃતિ પૂજાના ભાગરૂપે વડ સાવિત્રી વ્રતમાં વડના વૃક્ષની પૂજા કરાય છે."},{id:"ss_q07_10",questionText:"10) મીરા દાતારનો મેળો ધોળકામાં ભરાય છે.",options:["ખરું","ખોટું"],correctIndex:1,explanation:"ખોટું વિધાન: મીરા દાતારનો મેળો ધોળકામાં નહીં પરંતુ મહેસાણા જિલ્લાના 'ઉનાવા' (ઊંઝા પાસે) ખાતે ભરાય છે."},{id:"ss_q07_11",questionText:"11) શિલ્પ સ્થાપત્યની કળા આશરે 2000 વર્ષ જેટલી પ્રાચીન છે.",options:["ખરું","ખોટું"],correctIndex:1,explanation:"ખોટું વિધાન: ભારતની શિલ્પ-સ્થાપત્યની કલા 2000 વર્ષ નહીં પરંતુ આશરે '5000 વર્ષ' જેટલી પ્રાચીન છે."},{id:"ss_q07_12",questionText:"12) જૂનાગઢમાં ચાર ગુફા સમૂહો આવેલા છે. (માર્ચ 2024)",options:["ખરું","ખોટું"],correctIndex:1,explanation:"ખોટું વિધાન: જૂનાગઢમાં ચાર નહીં પરંતુ 'ત્રણ' ગુફા સમૂહો આવેલા છે — (1) બાવાપ્યારા, (2) ઉપરકોટ અને (3) ખાપરા-કોડિયા."},{id:"ss_q07_13",questionText:"13) સંસ્કૃત ભાષામાં સ્થાપત્ય માટે 'વાસ્તુ' શબ્દ વપરાય છે.",options:["ખરું","ખોટું"],correctIndex:0,explanation:"સાચું વિધાન (ખરું): સંસ્કૃત ભાષામાં સ્થાપત્ય (બાંધકામ) માટે 'વાસ્તુ' શબ્દ વપરાય છે."},{id:"ss_q07_14",questionText:"14) લોથલ રાજસ્થાનમાં આવેલું છે.",options:["ખરું","ખોટું"],correctIndex:1,explanation:"ખોટું વિધાન: લોથલ રાજસ્થાનમાં નહીં પરંતુ ગુજરાતના અમદાવાદ જિલ્લાના ધોળકા તાલુકામાં આવેલું છે."},{id:"ss_q07_15",questionText:"15) બૃહદેશ્વરનું મંદિર 200 ફૂટ ઊંચું છે.",options:["ખરું","ખોટું"],correctIndex:0,explanation:"સાચું વિધાન (ખરું): તાંજોર ખાતે આવેલા બૃહદેશ્વર (રાજરાજેશ્વર) મંદિરનું ગોપુરમ/શિખર જમીનથી લગભગ 200 ફૂટ ઊંચું છે."},{id:"ss_q07_16",questionText:"16) મોઢેરાના સૂર્યમંદિરનું નકશીકામ ઈરાની શૈલીમાં થયું છે.",options:["ખરું","ખોટું"],correctIndex:0,explanation:"સાચું વિધાન (ખરું): મોઢેરાના સૂર્યમંદિરનું બાહ્ય નકશીકામ ઈરાની શૈલીમાં કરવામાં આવ્યું છે."},{id:"ss_q07_17",questionText:"17) ચોલવંશની રાજધાની થંજાવુરમાં હતી. (ફેબ્રુઆરી-માર્ચ 2026)",options:["ખરું","ખોટું"],correctIndex:0,explanation:"સાચું વિધાન (ખરું): દક્ષિણ ભારતના ચોલવંશની રાજધાની તમિલનાડુના થંજાવુર (તાંજોર) ખાતે હતી."},{id:"ss_q07_18",questionText:"18) અજંતાની ગુફાઓ કર્ણાટક રાજ્યમાં આવેલી છે.",options:["ખરું","ખોટું"],correctIndex:1,explanation:"ખોટું વિધાન: અજંતાની ગુફાઓ કર્ણાટકમાં નહીં પરંતુ 'મહારાષ્ટ્ર' રાજ્યના ઔરંગાબાદ જિલ્લામાં આવેલી છે."},{id:"ss_q07_19",questionText:"19) કોણાર્કનું સૂર્યમંદિર ઓડિશા રાજ્યમાં આવેલું છે.",options:["ખરું","ખોટું"],correctIndex:0,explanation:"સાચું વિધાન (ખરું): કોણાર્કનું પ્રસિદ્ધ સૂર્યમંદિર ('કાળા પેગોડા') ઓડિશા રાજ્યના પુરી જિલ્લામાં આવેલું છે."},{id:"ss_q07_20",questionText:"20) આગરાનો લાલ કિલ્લો શાહજહાંએ બંધાવ્યો હતો.",options:["ખરું","ખોટું"],correctIndex:1,explanation:"ખોટું વિધાન: આગરાનો લાલ કિલ્લો શાહજહાંએ નહીં પરંતુ મુઘલ બાદશાહ 'અકબરે' ઈ.સ. 1565માં બંધાવ્યો હતો (દિલ્હીનો લાલ કિલ્લો શાહજહાંએ બંધાવ્યો હતો)."},{id:"ss_q07_21",questionText:"21) બૃહદેશ્વર મંદિરને રાજરાજેશ્વર મંદિર પણ કહે છે.",options:["ખરું","ખોટું"],correctIndex:0,explanation:"સાચું વિધાન (ખરું): ચોલ રાજા રાજરાજ પ્રથમે આ મંદિર બંધાવ્યું હોવાથી તેને 'રાજરાજેશ્વર મંદિર' પણ કહે છે."},{id:"ss_q07_22",questionText:"22) સ્થાનિક માછીમારો એલિફન્ટાને પાવાપુરી તરીકે ઓળખે છે.",options:["ખરું","ખોટું"],correctIndex:1,explanation:"ખોટું વિધાન: સ્થાનિક માછીમારો એલિફન્ટા ટાપુને પાવાપુરી નહીં પરંતુ 'ધારાપુરી' તરીકે ઓળખે છે."},{id:"ss_q07_23",questionText:"23) કૈલાસમંદિર તાંજોરમાં આવેલું છે.",options:["ખરું","ખોટું"],correctIndex:1,explanation:"ખોટું વિધાન: ભવ્ય કૈલાસ મંદિર તાંજોરમાં નહીં પરંતુ મહારાષ્ટ્રના 'ઇલોરા' (ગુફા નં. 16) માં આવેલું છે."},{id:"ss_q07_24",questionText:"24) હુમાયુના મકબરાનું નિર્માણ બાબરે કરાવ્યું હતું.",options:["ખરું","ખોટું"],correctIndex:1,explanation:"ખોટું વિધાન: હુમાયુના મકબરાનું નિર્માણ તેની પત્ની 'હમીદાબેગમ' (હાજી બેગમ) એ કરાવ્યું હતું."},{id:"ss_q07_25",questionText:"25) દેશની કુલ રાષ્ટ્રીય આવકને દેશની કુલ વસ્તી વડે ભાગવાથી 'માથાદીઠ આવક' પ્રાપ્ત થાય છે. (ફેબ્રુઆરી-માર્ચ 2025)",options:["ખરું","ખોટું"],correctIndex:0,explanation:"સાચું વિધાન (ખરું): માથાદીઠ આવક = દેશની કુલ રાષ્ટ્રીય આવક ÷ દેશની કુલ વસ્તી."}]},x={id:"social_q08",subjectId:"social_science",chapterNumber:"પ્રશ્ન 8",title:"પરિવહન, ગ્રાહક જાગૃતિ અને સમાજ (ખરા-ખોટા)",subtitle:"વિભાગ A • 20 ખરા-ખોટા પ્રશ્નો",questionTypeLabel:"ખરા-ખોટા",questions:[{id:"ss_q08_01",questionText:"1) હળવા, મધ્યમ ગતિના તથા ભારે વાહનોએ સામાન્ય રીતે સૌથી જમણી બાજુની લેનમાં જ વાહન ચલાવવું જોઈએ. (ફેબ્રુઆરી-માર્ચ 2026)",options:["ખરું","ખોટું"],correctIndex:1,explanation:"ખોટું વિધાન: હળવા, મધ્યમ ગતિના તથા ભારે વાહનોએ સામાન્ય રીતે સૌથી 'ડાબી' બાજુની લેનમાં જ વાહન ચલાવવું જોઈએ; જમણી લેન ઓવરટેકિંગ માટે હોય છે."},{id:"ss_q08_02",questionText:"2) મોટર સાઈકલ સવાર અને તેની પાછળ બેઠેલ વ્યક્તિએ હેલ્મેટ ફરજિયાત પહેરવું જોઈએ. (નમૂના પ્રશ્નપત્ર 2024-25)",options:["ખરું","ખોટું"],correctIndex:0,explanation:"સાચું વિધાન (ખરું): માર્ગ-સલામતીના નિયમ મુજબ મોટર સાઈકલ ચાલક અને પાછળ બેઠેલ બંને વ્યક્તિએ હેલ્મેટ ફરજિયાત પહેરવું જોઈએ."},{id:"ss_q08_03",questionText:"3) ભારતીય રેલવે દેશનું સૌથી મોટું રાષ્ટ્રીયકૃત સંસ્થાન છે.",options:["ખરું","ખોટું"],correctIndex:0,explanation:"સાચું વિધાન (ખરું): ભારતીય રેલવે દેશનું સૌથી મોટું જાહેર ક્ષેત્રનું રાષ્ટ્રીયકૃત સંસ્થાન છે."},{id:"ss_q08_04",questionText:"4) પોરબંદર છ માસ માટે ખુલ્લું રહેતું બંદર છે.",options:["ખરું","ખોટું"],correctIndex:1,explanation:"ખોટું વિધાન: પોરબંદર છ માસ નહીં પરંતુ 'બારેમાસ' ખુલ્લું રહેતું બંદર છે."},{id:"ss_q08_05",questionText:"5) ભારતમાં 28 જેટલાં આંતરરાષ્ટ્રીય હવાઈ મથકો છે.",options:["ખરું","ખોટું"],correctIndex:1,explanation:"ખોટું વિધાન: પાઠ્યપુસ્તક મુજબ ભારતમાં 28 નહીં પરંતુ 15 આંતરરાષ્ટ્રીય હવાઈ મથકો છે (PDF ઉત્તર કી: ખોટું)."},{id:"ss_q08_06",questionText:"6) દેશમાં આજે આકાશવાણીનાં 415 સ્ટેશનો આવેલાં છે.",options:["ખરું","ખોટું"],correctIndex:0,explanation:"સાચું વિધાન (ખરું): પાઠ્યપુસ્તકના આંકડા મુજબ દેશમાં આકાશવાણીનાં 415 જેટલાં સ્ટેશનો કાર્યરત છે."},{id:"ss_q08_07",questionText:"7) પંજાબ ગુજરાતમાંથી મીઠું આયાત કરે છે.",options:["ખરું","ખોટું"],correctIndex:0,explanation:"સાચું વિધાન (ખરું): ગુજરાત દેશનું સૌથી વધુ મીઠું ઉત્પન્ન કરતું રાજ્ય છે અને પંજાબ સહિતના રાજ્યો ગુજરાતમાંથી મીઠું આયાત કરે છે."},{id:"ss_q08_08",questionText:'8) સરકારે "આવશ્યક ચીજવસ્તુઓ" માટેનો ધારો 1977 માં અમલમાં મૂક્યો. (માર્ચ 2024)',options:["ખરું","ખોટું"],correctIndex:1,explanation:"ખોટું વિધાન: ભારત સરકારે આવશ્યક ચીજવસ્તુઓ માટેનો ધારો 1977 માં નહીં પરંતુ ઈ.સ. '1955' માં અમલમાં મૂક્યો હતો."},{id:"ss_q08_09",questionText:"9) અમેરિકાના રાલ્ફ નાડરે ગ્રાહક આંદોલનના જન્મદાતા કહેવાય છે.",options:["ખરું","ખોટું"],correctIndex:0,explanation:"સાચું વિધાન (ખરું): અમેરિકાના રાલ્ફ નાડરે ગ્રાહક અધિકારો માટે લડત ચલાવી હોવાથી તેમને ગ્રાહક આંદોલનના જન્મદાતા કહેવાય છે."},{id:"ss_q08_10",questionText:"10) હંમેશા ભાવ વધારો ફુગાવાજન્ય હોય છે.",options:["ખરું","ખોટું"],correctIndex:1,explanation:"ખોટું વિધાન: દરેક ભાવવધારો ફુગાવાજન્ય હોતો નથી; કેટલીકવાર કાચા માલની અછત કે માંગ-પુરવઠાના અસંતુલનથી પણ ભાવ વધે છે."},{id:"ss_q08_11",questionText:"11) રાજ્યના દરેક જિલ્લામાં જિલ્લા ફોરમની અદાલત હોય છે.",options:["ખરું","ખોટું"],correctIndex:0,explanation:"સાચું વિધાન (ખરું): ગ્રાહક સુરક્ષાના ત્રિ-સ્તરીય ન્યાયતંત્ર હેઠળ દરેક જિલ્લામાં જિલ્લા ગ્રાહક ફોરમ હોય છે."},{id:"ss_q08_12",questionText:"12) ભારતનો ISO સાથે સંપર્કની કામગીરી ભારતીય સંસ્થા CAS કરે છે.",options:["ખરું","ખોટું"],correctIndex:1,explanation:"ખોટું વિધાન: ભારતમાં ISO સાથે સંપર્કની કામગીરી CAS નહીં પરંતુ ભારતીય સંસ્થા 'BIS' (Bureau of Indian Standards) કરે છે."},{id:"ss_q08_13",questionText:"13) આજે દેશમાં 4.92 લાખ વાજબી ભાવની દુકાનો છે.",options:["ખરું","ખોટું"],correctIndex:0,explanation:"સાચું વિધાન (ખરું): પાઠ્યપુસ્તક મુજબ જાહેર વિતરણ પ્રણાલી હેઠળ દેશમાં અંદાજે 4.92 લાખ વાજબી ભાવની દુકાનો આવેલી છે."},{id:"ss_q08_14",questionText:"14) ભારતની 2011 માં કુલ વસતી 121 કરોડ હતી.",options:["ખરું","ખોટું"],correctIndex:0,explanation:"સાચું વિધાન (ખરું): ઈ.સ. 2011ની વસ્તી ગણતરી મુજબ ભારતની કુલ વસ્તી લગભગ 121 કરોડ હતી."},{id:"ss_q08_15",questionText:"15) ભારતમાં સરેરાશ 1.9 ટકાના દરે વસતી વધે છે.",options:["ખરું","ખોટું"],correctIndex:0,explanation:"સાચું વિધાન (ખરું): પાઠ્યપુસ્તકના આંકડા મુજબ ભારતમાં સરેરાશ 1.9 ટકાના દરે વસ્તીવધારો નોંધાયો છે."},{id:"ss_q08_16",questionText:"16) દેશમાં અંદાજે 571 ગ્રાહક જિલ્લા ફોરમો કાર્યરત છે.",options:["ખરું","ખોટું"],correctIndex:0,explanation:"સાચું વિધાન (ખરું): પાઠ્યપુસ્તક મુજબ દેશમાં અંદાજે 571 જેટલા ગ્રાહક જિલ્લા ફોરમો કાર્યરત છે."},{id:"ss_q08_17",questionText:"17) 2011 ના એક અંદાજ મુજબ ભારતમાં સૌથી વધુ વૃદ્ધોની વસ્તી અરુણાચલ પ્રદેશમાં છે. (ફેબ્રુઆરી-માર્ચ 2025)",options:["ખરું","ખોટું"],correctIndex:1,explanation:"ખોટું વિધાન: 2011 ના અંદાજ મુજબ સૌથી વધુ વૃદ્ધોની વસ્તી 'કેરળ'માં અને સૌથી ઓછી 'અરુણાચલ પ્રદેશ'માં હતી."},{id:"ss_q08_18",questionText:"18) ભ્રષ્ટાચાર સત્તાના દુરુપયોગથી જન્મે છે.",options:["ખરું","ખોટું"],correctIndex:0,explanation:"સાચું વિધાન (ખરું): જાહેર હોદ્દા અને સત્તાનો અંગત સ્વાર્થ માટે દુરુપયોગ કરવાથી ભ્રષ્ટાચાર જન્મે છે."},{id:"ss_q08_19",questionText:"19) સ્વતંત્રતાના હક્કને 'બંધારણનો આત્મા' કહે છે.",options:["ખરું","ખોટું"],correctIndex:1,explanation:"ખોટું વિધાન: સ્વતંત્રતાના હક્કને નહીં પરંતુ 'બંધારણીય ઇલાજોના હક્ક'ને ડૉ. બાબાસાહેબ આંબેડકરે 'બંધારણનો આત્મા' કહ્યો છે."},{id:"ss_q08_20",questionText:"20) માનવહકોનું ઘોષણાપત્ર સંયુક્ત રાષ્ટ્રોએ જાહેર કર્યું છે.",options:["ખરું","ખોટું"],correctIndex:0,explanation:"સાચું વિધાન (ખરું): સંયુક્ત રાષ્ટ્રો (UN) ની મહાસભાએ 10 ડિસેમ્બર 1948 ના રોજ માનવ અધિકારોનું વૈશ્વિક ઘોષણાપત્ર જાહેર કર્યું છે."}]},a={id:"social_q09",subjectId:"social_science",chapterNumber:"પ્રશ્ન 9",title:"માનવ વિકાસ અને મહિલા કલ્યાણ (ખરા-ખોટા)",subtitle:"વિભાગ A • 16 ખરા-ખોટા પ્રશ્નો",questionTypeLabel:"ખરા-ખોટા",questions:[{id:"ss_q09_01",questionText:"1) 'સબળા યોજના' અન્વયે દર વર્ષે કન્યાઓને વિનામૂલ્યે સાઈકલો આપવામાં આવે છે. (ફેબ્રુઆરી-માર્ચ 2026)",options:["ખરું","ખોટું"],correctIndex:1,explanation:"ખોટું વિધાન: વિનામૂલ્યે સાઈકલો 'સરસ્વતી સાધના યોજના' અન્વયે આપવામાં આવે છે, જ્યારે 'સબળા યોજના' કિશોરીઓના પોષણ અને કૌશલ્ય વિકાસ માટે છે."},{id:"ss_q09_02",questionText:"2) ગુજરાત સરકાર દ્વારા કિશોરીઓને પોષણયુક્ત આહાર તેમજ કૌશલ્યના વિકાસ માટે 'સબળા યોજના' અમલી બનાવી છે. (ફેબ્રુઆરી-માર્ચ 2025)",options:["ખરું","ખોટું"],correctIndex:0,explanation:"સાચું વિધાન (ખરું): 'સબળા યોજના' કિશોરીઓને પોષણયુક્ત આહાર અને કૌશલ્ય વિકાસ પૂરો પાડવા માટે અમલી છે."},{id:"ss_q09_03",questionText:"3) સરસ્વતી સાધના યોજના અન્વયે કન્યાઓને વિનામૂલ્યે સાયકલ આપવામાં આવે છે. (માર્ચ 2024)",options:["ખરું","ખોટું"],correctIndex:0,explanation:"સાચું વિધાન (ખરું): ગુજરાત સરકારની 'સરસ્વતી સાધના યોજના' હેઠળ ધોરણ 9માં પ્રવેશતી કન્યાઓને વિનામૂલ્યે સાયકલ અપાય છે."},{id:"ss_q09_04",questionText:"4) માનવ વિકાસ આંક વર્ષ 2015માં નેપાળ પ્રથમ ક્રમે છે. (નમૂના પ્રશ્નપત્ર 2024-25)",options:["ખરું","ખોટું"],correctIndex:1,explanation:"ખોટું વિધાન: માનવ વિકાસ અહેવાલ 2015 માં નેપાળ નહીં પરંતુ 'નોર્વે' (0.944) પ્રથમ ક્રમે હતું."},{id:"ss_q09_05",questionText:"5) માનવ વિકાસના ચાર આવશ્યક સ્તંભો છે: સમાનતા, સ્થિરતા, સ્વચ્છતા, સશક્તિકરણ.",options:["ખરું","ખોટું"],correctIndex:1,explanation:"ખોટું વિધાન: માનવ વિકાસના ચાર સ્તંભો સમાનતા, સ્થિરતા, 'ઉત્પાદકતા' અને સશક્તિકરણ છે (સ્વચ્છતા નહીં)."},{id:"ss_q09_06",questionText:"6) માનવ વિકાસ અહેવાલ 2015માં ભારતનો અપેક્ષિત આયુષ્ય આંક 73 વર્ષ છે.",options:["ખરું","ખોટું"],correctIndex:1,explanation:"ખોટું વિધાન: માનવ વિકાસ અહેવાલ 2015 મુજબ ભારતનો અપેક્ષિત આયુષ્ય આંક 73 વર્ષ નહીં પરંતુ '68 વર્ષ' હતો."},{id:"ss_q09_07",questionText:"7) માનવ વિકાસ અહેવાલ 2015માં ભારતના શાળાકીય સરેરાશ વર્ષો 11.7 વર્ષ છે.",options:["ખરું","ખોટું"],correctIndex:1,explanation:"ખોટું વિધાન: HDR 2015 મુજબ ભારતના અપેક્ષિત શાળાકીય વર્ષો 11.7 વર્ષ અને સરેરાશ શાળાકીય વર્ષો '5.4 વર્ષ' હતા."},{id:"ss_q09_08",questionText:"8) HDR 2015માં 0.555 થી 0.698 HDI ધરાવતા દેશોનો સમાવેશ ઉચ્ચ માનવ વિકાસની શ્રેણીમાં થાય છે.",options:["ખરું","ખોટું"],correctIndex:1,explanation:"ખોટું વિધાન: 0.555 થી 0.698 HDI ધરાવતા દેશોનો સમાવેશ 'મધ્યમ માનવ વિકાસ'ની શ્રેણીમાં થાય છે (ઉચ્ચ શ્રેણી માટે 0.700 થી 0.799 છે)."},{id:"ss_q09_09",questionText:"9) માનવ વિકાસને દેશના નિર્જીવ ભૌતિક સાધનોના નહીં પરંતુ સજીવ માનવ સંપદાના વિકાસ સાથે સીધો સંબંધ છે.",options:["ખરું","ખોટું"],correctIndex:0,explanation:"સાચું વિધાન (ખરું): માનવ વિકાસનો મુખ્ય કેન્દ્રબિંદુ માનવીનું કલ્યાણ અને સજીવ માનવ સંપદાનો વિકાસ છે."},{id:"ss_q09_10",questionText:"10) આરોગ્યક્ષેત્રે કરેલ ખર્ચ માત્ર જીવનની ગુણવત્તા વધારવા માટે છે એવું નથી પરંતુ માનવ સંસાધન વિકાસનું એક રોકાણ છે.",options:["ખરું","ખોટું"],correctIndex:0,explanation:"સાચું વિધાન (ખરું): સ્વસ્થ વ્યક્તિ વધુ ઉત્પાદક બને છે, તેથી આરોગ્ય પાછળનો ખર્ચ માનવ સંસાધનમાં રોકાણ ગણાય છે."},{id:"ss_q09_11",questionText:"11) સ્ત્રીઓ સમગ્ર વિકાસની પ્રક્રિયાનું કેન્દ્રબિંદુ છે.",options:["ખરું","ખોટું"],correctIndex:0,explanation:"સાચું વિધાન (ખરું): મહિલા સશક્તિકરણ વિના સમાજનો સર્વાંગી વિકાસ શક્ય નથી; સ્ત્રીઓ સમગ્ર વિકાસ પ્રક્રિયાનું કેન્દ્રબિંદુ છે."},{id:"ss_q09_12",questionText:"12) યુનાઇટેડ નેશન્સે 1985 થી 1995 ના દશકાને મહિલા દશકા તરીકે જાહેર કરેલ.",options:["ખરું","ખોટું"],correctIndex:1,explanation:"ખોટું વિધાન: યુનાઇટેડ નેશન્સે 1985 થી 1995 નહીં પરંતુ '1975 થી 1985' ના દશકાને મહિલા દશકા તરીકે જાહેર કર્યો હતો."},{id:"ss_q09_13",questionText:"13) ગુજરાતમાં 'સરસ્વતી સાધન સહાય યોજના' અન્વયે દર વર્ષે દોઢ લાખ કન્યાઓને વિના મૂલ્યે સાઇકલો આપવામાં આવે છે.",options:["ખરું","ખોટું"],correctIndex:1,explanation:"ખોટું વિધાન (PDF ઉત્તર કી: ખોટું): યોજનાનું સાચું નામ 'સરસ્વતી સાધના યોજના' છે (તથા દર વર્ષે શાળાપ્રવેશ પામતી પાત્ર કન્યાઓને સાયકલ અપાય છે)."},{id:"ss_q09_14",questionText:"14) અમર્ત્ય સેને માનવ વિકાસ આંકની વિભાવના કરી.",options:["ખરું","ખોટું"],correctIndex:0,explanation:"સાચું વિધાન (ખરું): ભારતીય મૂળના અર્થશાસ્ત્રી અમર્ત્ય સેન અને મહબૂબ-ઉલ-હકે માનવ વિકાસ આંક (HDI) ની વિભાવના વિકસાવી."},{id:"ss_q09_15",questionText:"15) પાકિસ્તાન નિમ્ન માનવ વિકાસ ધરાવતો દેશ છે.",options:["ખરું","ખોટું"],correctIndex:1,explanation:"ખોટું વિધાન (PDF ઉત્તર કી: ખોટું): સુધારેલા HDR વર્ગીકરણ મુજબ પાકિસ્તાન મધ્યમ શ્રેણીમાં ગણાય છે (નોંધ: HDR 2015 માં તે 0.538 સાથે નિમ્ન શ્રેણીમાં હતું, પરંતુ PDF ઉત્તર કી મુજબ આ વિધાન ખોટું અપાયેલ છે)."},{id:"ss_q09_16",questionText:"16) સંસદમાં મહિલા સાંસદોનું પ્રમાણ માત્ર 12.2% છે.",options:["ખરું","ખોટું"],correctIndex:0,explanation:"સાચું વિધાન (ખરું): પાઠ્યપુસ્તકના આંકડા મુજબ ભારતીય સંસદમાં મહિલા સાંસદોનું પ્રમાણ માત્ર 12.2% દર્શાવેલ છે."}]},c={id:"social_q10",subjectId:"social_science",chapterNumber:"પ્રશ્ન 10",title:"ભારતની સામાજિક સમસ્યાઓ અને બંધારણ (ખરા-ખોટા)",subtitle:"વિભાગ A • 15 ખરા-ખોટા પ્રશ્નો",questionTypeLabel:"ખરા-ખોટા",questions:[{id:"ss_q10_01",questionText:"1) બંધારણની કલમ 17 અન્વયે અસ્પૃશ્યતા નાબૂદ કરવામાં આવી છે. (ફેબ્રુઆરી-માર્ચ 2026)",options:["ખરું","ખોટું"],correctIndex:0,explanation:"સાચું વિધાન (ખરું): ભારતીય બંધારણના અનુચ્છેદ 17 મુજબ અસ્પૃશ્યતા સંપૂર્ણપણે નાબૂદ કરવામાં આવી છે."},{id:"ss_q10_02",questionText:"2) ગ્રામપંચાયત અને નગરપાલિકામાં પણ અનુસૂચિત જાતિ અને અનુસૂચિત જનજાતિ માટે કેટલીક બેઠકો અનામત રાખવામાં આવે છે. (ફેબ્રુઆરી-માર્ચ 2025)",options:["ખરું","ખોટું"],correctIndex:0,explanation:"સાચું વિધાન (ખરું): સ્થાનિક સ્વરાજ્યની સંસ્થાઓ (ગ્રામપંચાયત, નગરપાલિકા) માં SC અને ST માટે વસ્તીના ધોરણે બેઠકો અનામત રાખવામાં આવે છે."},{id:"ss_q10_03",questionText:"3) બંધારણની કલમ 17 અન્વયે અસ્પૃશ્યતા નાબૂદ કરવામાં આવી છે. (માર્ચ 2024)",options:["ખરું","ખોટું"],correctIndex:0,explanation:"સાચું વિધાન (ખરું): બંધારણની કલમ 17 હેઠળ અસ્પૃશ્યતાનું કોઈપણ સ્વરૂપમાં આચરણ કાયદેસર ગુનો છે."},{id:"ss_q10_04",questionText:"4) આતંકવાદ વૈશ્વિક સમસ્યા છે. (નમૂના પ્રશ્નપત્ર 2024-25)",options:["ખરું","ખોટું"],correctIndex:0,explanation:"સાચું વિધાન (ખરું): આતંકવાદ કોઈ એક દેશ પૂરતો સીમિત નથી, તે સમગ્ર વિશ્વને અસર કરતી વૈશ્વિક સમસ્યા છે."},{id:"ss_q10_05",questionText:"5) ભારત વિશ્વની સૌથી મોટી લોકશાહી ધરાવતો દેશ છે.",options:["ખરું","ખોટું"],correctIndex:0,explanation:"સાચું વિધાન (ખરું): વસ્તી અને મતદારોની સંખ્યાની દ્રષ્ટિએ ભારત વિશ્વનો સૌથી મોટો લોકશાહી દેશ છે."},{id:"ss_q10_06",questionText:"6) ભારત એક બિનસાંપ્રદાયિક અને ધર્મનિરપેક્ષ દેશ છે.",options:["ખરું","ખોટું"],correctIndex:0,explanation:"સાચું વિધાન (ખરું): ભારતીય બંધારણ મુજબ દેશનો કોઈ રાજકીય ધર્મ નથી; બધા ધર્મો સમાન છે."},{id:"ss_q10_07",questionText:"7) ભારતની સામાજિક સંરચના ધર્મ પર આધારિત છે.",options:["ખરું","ખોટું"],correctIndex:1,explanation:"ખોટું વિધાન: ભારતની પરંપરાગત સામાજિક સંરચના ધર્મ પર નહીં પરંતુ 'જ્ઞાતિ' પર આધારિત છે."},{id:"ss_q10_08",questionText:"8) ધાર્મિક સ્વતંત્રતાનો અધિકાર કોઈ પણ ધર્મનું પાલન કરવાની સ્વતંત્રતા આપે છે.",options:["ખરું","ખોટું"],correctIndex:0,explanation:"સાચું વિધાન (ખરું): બંધારણની કલમ 25 થી 28 મુજબ દરેક નાગરિકને પોતાની પસંદગીનો ધર્મ પાળવાની સ્વતંત્રતા છે."},{id:"ss_q10_09",questionText:"9) બળવાખોરી જે તે રાષ્ટ્રની સમસ્યા છે.",options:["ખરું","ખોટું"],correctIndex:0,explanation:"સાચું વિધાન (ખરું): બળવાખોરી સ્થાનિક અસંતોષમાંથી જન્મે છે અને તે જે તે રાષ્ટ્રની આંતરિક સમસ્યા છે."},{id:"ss_q10_10",questionText:"10) 15 મી ઓગસ્ટ 1947 ના રોજ ભારત સ્વતંત્ર થયું.",options:["ખરું","ખોટું"],correctIndex:0,explanation:"સાચું વિધાન (ખરું): ભારત 15 ઓગસ્ટ 1947 ના રોજ બ્રિટિશ શાસનમાંથી આઝાદ થયું હતું."},{id:"ss_q10_11",questionText:"11) બંધારણની કલમ 341 માં જણાવ્યા પ્રમાણેની અનુસૂચિમાં સમાવિષ્ટ જ્ઞાતિને અનુસૂચિત જાતિઓ તરીકે ઓળખવામાં આવે છે.",options:["ખરું","ખોટું"],correctIndex:0,explanation:"સાચું વિધાન (ખરું): બંધારણની કલમ 341 હેઠળ અનુસૂચિત જાતિઓ (SC) નો સમાવેશ કરવામાં આવ્યો છે."},{id:"ss_q10_12",questionText:"12) બંધારણની કલમ 342 પ્રમાણેની અનુસૂચિ પ્રમાણે સમાવિષ્ટ જાતિઓને અનુસૂચિત જનજાતિઓ તરીકે ઓળખવામાં આવે છે.",options:["ખરું","ખોટું"],correctIndex:0,explanation:"સાચું વિધાન (ખરું): બંધારણની કલમ 342 હેઠળ અનુસૂચિત જનજાતિઓ (ST) નો સમાવેશ કરવામાં આવ્યો છે."},{id:"ss_q10_13",questionText:"13) આતંકવાદ એ જે તે દેશની સમસ્યા છે.",options:["ખરું","ખોટું"],correctIndex:1,explanation:"ખોટું વિધાન: આતંકવાદ કોઈ એક દેશની નહીં પરંતુ 'વૈશ્વિક' સમસ્યા છે (જે તે દેશની આંતરિક સમસ્યા બળવાખોરી કહેવાય છે)."},{id:"ss_q10_14",questionText:"14) ભારતની સામાજિક સંરચના જ્ઞાતિ પર આધારિત છે.",options:["ખરું","ખોટું"],correctIndex:0,explanation:"સાચું વિધાન (ખરું): ભારતની સામાજિક સંરચના પરંપરાગત રીતે જ્ઞાતિ વ્યવસ્થા પર આધારિત છે."},{id:"ss_q10_15",questionText:"15) કે. એન. એફ. નાગાલેન્ડનું બળવાખોરી સંગઠન છે.",options:["ખરું","ખોટું"],correctIndex:1,explanation:"ખોટું વિધાન: K.N.F. (Kuki National Front) નાગાલેન્ડનું નહીં પરંતુ 'મણિપુર'નું બળવાખોરી સંગઠન છે (નાગાલેન્ડમાં N.S.C.N. છે)."}]},r={id:"social_q11",subjectId:"social_science",chapterNumber:"પ્રશ્ન 11",title:"ભારતનો સાહિત્યિક અને સાંસ્કૃતિક વારસો (ખાલી જગ્યા)",subtitle:"વિભાગ A • 17 ખાલી જગ્યા પ્રશ્નો",questionTypeLabel:"ખાલી જગ્યા",questions:[{id:"ss_q11_01",questionText:"1) વિશ્વધર્મ પરિષદ ............ શહેરમાં આયોજન કરવામાં આવ્યું હતું. — (ફેબ્રુઆરી-માર્ચ 2026)",options:["શિકાગો","ન્યૂયોર્ક","જીનિવા"],correctIndex:0,explanation:"સાચો જવાબ: શિકાગો. ઈ.સ. 1893માં અમેરિકાના શિકાગો શહેરમાં વિશ્વધર્મ પરિષદ યોજાઈ હતી, જેમાં સ્વામી વિવેકાનંદે ભારતીય સંસ્કૃતિનું ગૌરવ વધાર્યું હતું."},{id:"ss_q11_02",questionText:"2) ............ ચીની મુસાફરે નાલંદા વિદ્યાપીઠની મુલાકાત લીધી હતી.",options:["હ્યુઆન-શ્વાંગ","ફાહિયાન","ઇત્સિંગ"],correctIndex:0,explanation:"સાચો જવાબ: હ્યુઆન-શ્વાંગ. 7મી સદીમાં ચીની મુસાફર હ્યુઆન-શ્વાંગે નાલંદા વિદ્યાપીઠની મુલાકાત લઈને બૌદ્ધ ધર્મનો અભ્યાસ કર્યો હતો."},{id:"ss_q11_03",questionText:"3) ............ હિન્દી સાહિત્યનો પ્રારંભિક ગ્રંથ હતો.",options:["આલા","ઉદલ","પૃથ્વીરાજ રાસો"],correctIndex:2,explanation:"સાચો જવાબ: પૃથ્વીરાજ રાસો. ચંદબરદાઈ રચિત 'પૃથ્વીરાજ રાસો' હિન્દી સાહિત્યના વીરગાથા કાળનો પ્રારંભિક ગ્રંથ ગણાય છે."},{id:"ss_q11_04",questionText:"4) દ્રવિડ કુળની સૌથી પ્રાચીન ભાષા ............ છે.",options:["તેલુગુ","તમિલ","કન્નડ"],correctIndex:1,explanation:"સાચો જવાબ: તમિલ. દ્રવિડ કુળની ચાર ભાષાઓ (તમિલ, તેલુગુ, કન્નડ, મલયાલમ) પૈકી 'તમિલ' સૌથી પ્રાચીન ભાષા છે."},{id:"ss_q11_05",questionText:"5) ભારતનો સૌથી પ્રાચીનતમ ગ્રંથ ............ છે.",options:["સામવેદ","ઋગ્વેદ","અથર્વવેદ"],correctIndex:1,explanation:"સાચો જવાબ: ઋગ્વેદ. ચાર વેદોમાં 'ઋગ્વેદ' ભારતીય સાહિત્યનો સૌથી પ્રાચીનતમ ગ્રંથ છે."},{id:"ss_q11_06",questionText:"6) પ્રારંભિક બૌદ્ધ સાહિત્ય ............ ભાષામાં રચાયેલું હતું.",options:["સંસ્કૃત","તમિલ","પાલી"],correctIndex:2,explanation:"સાચો જવાબ: પાલી. પ્રારંભિક બૌદ્ધ સાહિત્ય 'ત્રિપિટક' પાલી ભાષામાં લખાયેલું હતું."},{id:"ss_q11_07",questionText:"7) વહીવટી વિજ્ઞાનની કૃતિ ............ ગણાય છે.",options:["ત્રિપિટક","અર્થશાસ્ત્ર","શાંતિપુરાણ"],correctIndex:1,explanation:"સાચો જવાબ: અર્થશાસ્ત્ર. કૌટિલ્ય (ચાણક્ય) દ્વારા રચિત 'અર્થશાસ્ત્ર' વહીવટી વિજ્ઞાનની ઉત્કૃષ્ટ કૃતિ ગણાય છે."},{id:"ss_q11_08",questionText:"8) હુમાયુનામાની રચના ............ કરી હતી.",options:["ગુલબદન બેગમ","હમીદા બેગમ","જહાંગીર"],correctIndex:0,explanation:"સાચો જવાબ: ગુલબદન બેગમ. હુમાયુની બહેન ગુલબદન બેગમે 'હુમાયુનામા' ની રચના કરી હતી."},{id:"ss_q11_09",questionText:"9) 'ગીતગોવિંદ' નામના સુંદર કાવ્યગ્રંથની રચના ............ કરી હતી.",options:["સોમદેવ","જયદેવ","ચંદબરદાઈ"],correctIndex:1,explanation:"સાચો જવાબ: જયદેવ. સંસ્કૃત સાહિત્યના મહાકવિ જયદેવે 'ગીતગોવિંદ' કાવ્યગ્રંથ રચ્યો હતો."},{id:"ss_q11_10",questionText:"10) ઋગ્વેદમાં ............ ઋચાઓનો સંગ્રહ છે.",options:["1028","1011","1021"],correctIndex:0,explanation:"સાચો જવાબ: 1028. ઋગ્વેદ 10 મંડળોમાં વહેંચાયેલો છે અને તેમાં કુલ 1028 ઋચાઓ (સૂક્તો) છે."},{id:"ss_q11_11",questionText:"11) ............ ને યજ્ઞનો વેદ કહેવાય છે.",options:["ઋગ્વેદ","યજુર્વેદ","અથર્વવેદ"],correctIndex:1,explanation:"સાચો જવાબ: યજુર્વેદ. યજ્ઞ વખતે બોલવામાં આવતા મંત્રો અને વિધિઓનું વર્ણન હોવાથી યજુર્વેદને યજ્ઞનો વેદ કહેવાય છે."},{id:"ss_q11_12",questionText:"12) મહાભારતમાં લગભગ ............ શ્લોકો છે.",options:["પચાસ હજાર","એક લાખ","વીસ હજાર"],correctIndex:1,explanation:"સાચો જવાબ: એક લાખ. મહર્ષિ વેદવ્યાસ રચિત મહાભારતમાં લગભગ એક લાખ શ્લોકો છે અને તે વિશ્વનો સૌથી મોટો કાવ્યગ્રંથ છે."},{id:"ss_q11_13",questionText:"13) ............ માં દાર્શનિક પ્રશ્નોનું વિવેચન કરવામાં આવ્યું છે.",options:["ઉપનિષદ","આરણ્યકો","વેદાંગ"],correctIndex:0,explanation:"સાચો જવાબ: ઉપનિષદ. ઉપનિષદોમાં બ્રહ્માંડનો આરંભ, જીવન, મૃત્યુ અને આત્મા-પરમાત્મા જેવા દાર્શનિક પ્રશ્નોનું વિવેચન છે."},{id:"ss_q11_14",questionText:"14) 'આમુક્તમાલ્યદા' ગ્રંથની રચના ............ કરી.",options:["કૃષ્ણદેવરાયે","તુલસીદાસે","નામદેવે"],correctIndex:0,explanation:"સાચો જવાબ: કૃષ્ણદેવરાયે. વિજયનગરના સમ્રાટ કૃષ્ણદેવરાયે તેલુગુ ભાષામાં 'આમુક્તમાલ્યદા' ગ્રંથની રચના કરી."},{id:"ss_q11_15",questionText:"15) વિદેશી પર્યટકો આવવાથી વિદેશી ............ ભારતને પ્રાપ્ત થાય છે. — (નમૂના પ્રશ્નપત્ર 2024-25)",options:["હૂંડિયામણ","નિકાસ","શ્રમબજાર"],correctIndex:0,explanation:"સાચો જવાબ: હૂંડિયામણ. પર્યટન ઉદ્યોગ દ્વારા વિદેશી પ્રવાસીઓ આવતા દેશને વિદેશી હૂંડિયામણ પ્રાપ્ત થાય છે."},{id:"ss_q11_16",questionText:"16) રાષ્ટ્રીય માનવ સંગ્રહાલય ............ શહેરમાં આવેલું છે. — (માર્ચ 2024)",options:["દિલ્લી","હૈદરાબાદ","ભોપાલ"],correctIndex:2,explanation:"સાચો જવાબ: ભોપાલ. રાષ્ટ્રીય માનવ સંગ્રહાલય મધ્યપ્રદેશના ભોપાલ શહેરમાં આવેલું છે."},{id:"ss_q11_17",questionText:"17) ............ નદી પર નાગાર્જુનસાગર બહુહેતુક યોજના આવેલી છે.",options:["સતલુજ","કાવેરી","કૃષ્ણા"],correctIndex:2,explanation:"સાચો જવાબ: કૃષ્ણા. નાગાર્જુનસાગર બહુહેતુક યોજના આંધ્રપ્રદેશ-તેલંગાણામાં કૃષ્ણા નદી પર આવેલી છે."}]},p={id:"social_q12",subjectId:"social_science",chapterNumber:"પ્રશ્ન 12",title:"વન, વન્યજીવ અને ખનીજ સંસાધન (ખાલી જગ્યા)",subtitle:"વિભાગ A • 15 ખાલી જગ્યા પ્રશ્નો",questionTypeLabel:"ખાલી જગ્યા",questions:[{id:"ss_q12_01",questionText:"1) ઈ.સ. ............ માં વન્યજીવોને લગતો કાયદો અમલમાં આવ્યો છે. — (માર્ચ 2026)",options:["1952","1972","1876"],correctIndex:1,explanation:"સાચો જવાબ: 1972. ભારતમાં વન્યજીવ સંરક્ષણ અધિનિયમ ઈ.સ. 1972 માં અમલમાં આવ્યો હતો."},{id:"ss_q12_02",questionText:"2) ............ માં ભારત સરકારે ભારતીય વન્યજીવો માટે બોર્ડની રચના કરી. — (માર્ચ 2024)",options:["ઈ.સ. 1952","ઈ.સ. 1976","ઈ.સ. 1986"],correctIndex:0,explanation:"સાચો જવાબ: ઈ.સ. 1952. ભારત સરકારે ઈ.સ. 1952 માં ભારતીય વન્યજીવો માટે બોર્ડ (IBWL) ની રચના કરી."},{id:"ss_q12_03",questionText:"3) ............ માં વન્યજીવોને લગતો કાયદો અમલમાં આવ્યો છે. — (નમૂના પ્રશ્નપત્ર 2024-25)",options:["ઈ.સ. 1940","ઈ.સ. 1972","ઈ.સ. 1952"],correctIndex:1,explanation:"સાચો જવાબ: ઈ.સ. 1972. વન્યજીવોના રક્ષણ માટે ઈ.સ. 1972 માં કાયદો અમલમાં આવ્યો."},{id:"ss_q12_04",questionText:"4) કુદરતી વનસ્પતિને ............ વનસ્પતિ કહે છે.",options:["અક્ષત","સાંસ્કૃતિક","પ્રાકૃતિક"],correctIndex:0,explanation:"સાચો જવાબ: અક્ષત. જે વનસ્પતિ માનવીની સહાય વિના કુદરતી રીતે ઊગે છે તેને 'અક્ષત વનસ્પતિ' (Virgin Vegetation) કહે છે."},{id:"ss_q12_05",questionText:"5) કુદરતનો સફાઈ કામદાર ............ છે.",options:["મોર","ગીધ","હેણોતરો"],correctIndex:1,explanation:"સાચો જવાબ: ગીધ. ગીધ મૃત પશુઓનું માંસ ખાઈને પર્યાવરણને સ્વચ્છ રાખતું હોવાથી તેને કુદરતનો સફાઈ કામદાર કહેવાય છે."},{id:"ss_q12_06",questionText:"6) ............ જંગલ વિસ્તારમાં વૃક્ષછેદન અને પશુ ચરાણ પર કોઈ પ્રતિબંધ નથી.",options:["અનામત","અવર્ગીકૃત","જાહેર"],correctIndex:1,explanation:"સાચો જવાબ: અવર્ગીકૃત. અવર્ગીકૃત જંગલો દુર્ગમ હોવાથી તેમનું વર્ગીકરણ થયું નથી અને ત્યાં વૃક્ષછેદન કે પશુચરાણ પર પ્રતિબંધ નથી."},{id:"ss_q12_07",questionText:"7) ગુજરાતની નર્મદા, તાપી, મહી અને સાબરમતી જેવી નદીઓમાં ............ પ્રાણી લુપ્ત થવાના આરે છે.",options:["જળ બિલાડી","મગર","ગંગેય ડોલ્ફિન"],correctIndex:0,explanation:"સાચો જવાબ: જળ બિલાડી. ગુજરાતની આ નદીઓમાં જોવા મળતી જળ બિલાડી લુપ્ત થવાના આરે છે."},{id:"ss_q12_08",questionText:"8) ............ જંગલો સીધા સરકારી તંત્રના નિયંત્રણમાં હોય છે.",options:["સંરક્ષિત","અવર્ગીકૃત","અનામત"],correctIndex:2,explanation:"સાચો જવાબ: અનામત. અનામત જંગલો સીધા સરકારી તંત્રના નિયંત્રણમાં હોય છે અને ત્યાં લાકડાં કાપવા કે પશુચરાણની મનાઈ હોય છે."},{id:"ss_q12_09",questionText:"9) ભારતના જંગલોમાંથી ............ નષ્ટ થઈ ચૂક્યો છે.",options:["વરુ","દીપડો","ચિત્તો"],correctIndex:2,explanation:"સાચો જવાબ: ચિત્તો. ભારતના જંગલોમાંથી ચિત્તો સંપૂર્ણપણે નષ્ટ થઈ ચૂક્યો છે."},{id:"ss_q12_10",questionText:"10) ભારતમાં ગીધની ............ પ્રજાતિઓ જોવા મળે છે.",options:["૬","૯","૧૨"],correctIndex:1,explanation:"સાચો જવાબ: ૯. ભારતમાં ગીધની કુલ ૯ પ્રજાતિઓ જોવા મળે છે."},{id:"ss_q12_11",questionText:"11) ગુજરાતમાં ............ અભયારણ્યો છે.",options:["૨૬","૪૫","૨૩"],correctIndex:2,explanation:"સાચો જવાબ: ૨૩. પાઠ્યપુસ્તક મુજબ ગુજરાતમાં ૨૩ અભયારણ્યો, ૪ રાષ્ટ્રીય ઉદ્યાનો અને ૧ જૈવ આરક્ષિત ક્ષેત્ર છે."},{id:"ss_q12_12",questionText:"12) ઊર્જાનો મુખ્ય સ્ત્રોત ............ છે. — (માર્ચ 2025)",options:["પૃથ્વી","સૂર્ય","મંગળ"],correctIndex:1,explanation:"સાચો જવાબ: સૂર્ય. પૃથ્વી પર ઊર્જાનો મુખ્ય અને અખૂટ સ્ત્રોત સૂર્ય છે."},{id:"ss_q12_13",questionText:"13) ગુજરાતમાં જામનગરના ............ ગામે વિન્ડફાર્મ કાર્યરત છે.",options:["લાંબા","ચોરભૂજ","મોરબી"],correctIndex:0,explanation:"સાચો જવાબ: લાંબા. ગુજરાતમાં દેવભૂમિ દ્વારકા (અગાઉ જામનગર) ના લાંબા ગામે અને કચ્છના માંડવી ખાતે વિન્ડફાર્મ કાર્યરત છે."},{id:"ss_q12_14",questionText:"14) તાંબાની ધાતુમાં કલાઈ ઉમેરવાથી ............ બને છે.",options:["જસત","કાંસુ","નિકલ"],correctIndex:1,explanation:"સાચો જવાબ: કાંસુ. તાંબામાં કલાઈ (ટિન) ઉમેરવાથી 'કાંસુ' અને જસત ઉમેરવાથી 'પિત્તળ' બને છે."},{id:"ss_q12_15",questionText:"15) ............ માંથી એલ્યુમિનિયમ મેળવવામાં આવે છે.",options:["પિત્તળ","તાંબા","બોક્સાઈટ"],correctIndex:2,explanation:"સાચો જવાબ: બોક્સાઈટ. એલ્યુમિનિયમની કાચી ધાતુ બોક્સાઈટ છે."}]},d={id:"social_q13",subjectId:"social_science",chapterNumber:"પ્રશ્ન 13",title:"ગરીબી, બેરોજગારી અને ગ્રાહક સુરક્ષા (ખાલી જગ્યા)",subtitle:"વિભાગ A • 18 ખાલી જગ્યા પ્રશ્નો",questionTypeLabel:"ખાલી જગ્યા",questions:[{id:"ss_q13_01",questionText:"1) ગરીબીરેખાનો ખ્યાલ સૌપ્રથમ WHO ના નિયામક ............ એ રજૂ કર્યો હતો. — (ફેબ્રુઆરી-માર્ચ 2025)",options:["એડમ સ્મિથ","બ્યોર્ડ ઓરે","અમર્ત્ય સેન"],correctIndex:1,explanation:"સાચો જવાબ: બ્યોર્ડ ઓરે. ગરીબીરેખાનો ખ્યાલ સૌપ્રથમ WHO ના નિયામક બ્યોર્ડ ઓરે રજૂ કર્યો હતો."},{id:"ss_q13_02",questionText:"2) વિશ્વની વસ્તીના ............ ટકા યુવાનો ભારતમાં છે.",options:["75","77","66"],correctIndex:2,explanation:"સાચો જવાબ: 66 (પાઠ્યપુસ્તક મુજબ: ભારતની કુલ વસ્તીના 66% યુવાનો છે; PDF ઉત્તર કી: 66)."},{id:"ss_q13_03",questionText:"3) આપણા અર્થતંત્ર સમક્ષનો સૌથી મોટો પડકાર ............ છે.",options:["ભ્રષ્ટાચાર","બેરોજગારી","કાળું નાણું"],correctIndex:1,explanation:"સાચો જવાબ: બેરોજગારી. ભારતીય અર્થતંત્ર સમક્ષના મુખ્ય પડકારોમાં બેરોજગારી સૌથી મોટો પડકાર છે."},{id:"ss_q13_04",questionText:"4) ભારતમાં સૌથી વધુ ગરીબી ધરાવતું રાજ્ય ............ છે.",options:["ગોવા","ઝારખંડ","છત્તીસગઢ"],correctIndex:2,explanation:"સાચો જવાબ: છત્તીસગઢ. આંકડાકીય માહિતી મુજબ સૌથી વધુ ગરીબીનું પ્રમાણ છત્તીસગઢ (36.93%) રાજ્યમાં છે."},{id:"ss_q13_05",questionText:"5) ભારતમાં એક અંદાજ મુજબ ઉચ્ચ શૈક્ષણિક લાયકાતવાળા ............ ટકા યુવાનો છે.",options:["૧૨","૧૭","૧૫"],correctIndex:2,explanation:"સાચો જવાબ: ૧૫. પાઠ્યપુસ્તક મુજબ વિશ્વની શ્રમશક્તિમાં ઉચ્ચ શૈક્ષણિક લાયકાત ધરાવતા ૧૫% યુવાનો ભારતમાં છે."},{id:"ss_q13_06",questionText:"6) વિશ્વના દેશો પોતાના શ્રમિકોનું આદાન-પ્રદાન કરે છે તેને ............ કહે છે.",options:["બ્રેઈન ડ્રેઈન","વિશ્વ શ્રમ બજાર","દેશાવરગમન"],correctIndex:1,explanation:"સાચો જવાબ: વિશ્વ શ્રમ બજાર. વિશ્વના દેશો વચ્ચે શ્રમિકો અને બુદ્ધિધનની આંતરરાષ્ટ્રીય હેરફેરને વિશ્વ શ્રમ બજાર કહે છે."},{id:"ss_q13_07",questionText:"7) ............ ની સમસ્યા આપણા આયોજનની સૌથી નબળી કડી છે.",options:["બેરોજગારી","નિરક્ષરતા","ગરીબી"],correctIndex:2,explanation:"સાચો જવાબ: ગરીબી (PDF ઉત્તર કી: ગરીબી). ગરીબી અને બેરોજગારી આર્થિક આયોજનના મુખ્ય પડકારો છે."},{id:"ss_q13_08",questionText:"8) અમેરિકન પ્રમુખ ............ એ અમેરિકાની સંસદમાં તા. 15-માર્ચ-1962 ના રોજ ગ્રાહકોને ચાર અધિકારો આપ્યા હતા. — (માર્ચ 2025)",options:["રાલ્ફ નાડર","જ્હોન ફ્રેન્કલિન કેનેડી","રોનાલ્ડ રેગન"],correctIndex:1,explanation:"સાચો જવાબ: જ્હોન ફ્રેન્કલિન કેનેડી. તેમણે 15 માર્ચ 1962 ના રોજ ગ્રાહકોને ચાર મૂળભૂત અધિકારો આપ્યા હતા."},{id:"ss_q13_09",questionText:"9) ભારતમાં દર વર્ષે 24 ડિસેમ્બરના દિવસને ............ તરીકે ઉજવવામાં આવે છે.",options:["રાષ્ટ્રીય ગ્રાહક અધિકાર દિન","વિશ્વ ગ્રાહક દિન","વિશ્વ ગ્રાહક અધિકાર દિન"],correctIndex:0,explanation:"સાચો જવાબ: રાષ્ટ્રીય ગ્રાહક અધિકાર દિન. 24 ડિસેમ્બર 1986 ના રોજ ભારતમાં ગ્રાહક સુરક્ષા ધારો અમલમાં આવ્યો હતો."},{id:"ss_q13_10",questionText:"10) કરવેરા નહીં ભરીને વિદેશી માલસામાન દેશમાં ઠલવાય તેને ............ કહે છે.",options:["નફાખોરી","સંગ્રહખોરી","દાણચોરી"],correctIndex:2,explanation:"સાચો જવાબ: દાણચોરી. આયાત જકાત/કરવેરા ભર્યા વિના ગેરકાયદેસર રીતે વિદેશી માલ દેશમાં લાવવો તેને દાણચોરી કહે છે."},{id:"ss_q13_11",questionText:"11) ............ નીતિ એટલે સરકારની જાહેર આવક-ખર્ચ અંગેની નીતિ, કરવેરા વિષયક અને જાહેર ઋણની નીતિ.",options:["ભાવ નિયમન","રાજકોષીય","નાણાકીય"],correctIndex:1,explanation:"સાચો જવાબ: રાજકોષીય. સરકારની આવક, ખર્ચ, કરવેરા અને જાહેર દેવા અંગેની નીતિને રાજકોષીય નીતિ કહે છે."},{id:"ss_q13_12",questionText:"12) વિશ્વમાં દર વર્ષે ............ નો દિવસ વિશ્વ ગ્રાહક અધિકાર દિન તરીકે ઉજવવામાં આવે છે.",options:["15 માર્ચ","1 જાન્યુઆરી","10 ડિસેમ્બર"],correctIndex:0,explanation:"સાચો જવાબ: 15 માર્ચ. સમગ્ર વિશ્વમાં 15 માર્ચ 'વિશ્વ ગ્રાહક અધિકાર દિવસ' તરીકે ઉજવાય છે."},{id:"ss_q13_13",questionText:"13) ભારતમાં ISO સાથે સંપર્કની કામગીરી ભારતીય સંસ્થા ............ કરે છે.",options:["DMI","BIS","CAC"],correctIndex:1,explanation:"સાચો જવાબ: BIS. ભારતમાં આંતરરાષ્ટ્રીય સંસ્થા ISO સાથે સંપર્ક અને સંકલનની કામગીરી BIS (Bureau of Indian Standards) કરે છે."},{id:"ss_q13_14",questionText:"14) કોડેક્ષ એલિમેન્ટેરિયસ કમિશન (CAC) નું મુખ્ય મથક ઇટલીની રાજધાની ............ માં છે.",options:["રોમ","પેરિસ","જીનિવા"],correctIndex:0,explanation:"સાચો જવાબ: રોમ. આંતરરાષ્ટ્રીય ખાદ્યપદાર્થોનું પ્રમાણન કરતી સંસ્થા CAC નું મુખ્ય મથક ઇટલીના રોમમાં છે."},{id:"ss_q13_15",questionText:"15) સરકારે ભાવ સપાટીને સ્થિર રાખવા માટે આવશ્યક ચીજવસ્તુઓ માટેનો ધારો ............ માં અમલમાં મૂક્યો છે.",options:["1955","1950","1960"],correctIndex:0,explanation:"સાચો જવાબ: 1955. આવશ્યક ચીજવસ્તુ ધારો ઈ.સ. 1955 માં અમલમાં મૂકવામાં આવ્યો હતો."},{id:"ss_q13_16",questionText:"16) ભારતમાં સરેરાશ ............ ટકાના દરે વસતી વધે છે.",options:["3.20","1.9","6.5"],correctIndex:1,explanation:"સાચો જવાબ: 1.9. પાઠ્યપુસ્તક મુજબ ભારતમાં સરેરાશ 1.9% ના દરે વસ્તી વધે છે."},{id:"ss_q13_17",questionText:"17) આજે દેશમાં અંદાજે ............ 'વાજબી ભાવની દુકાનો' આવેલી છે.",options:["5.40 લાખ","9.15 લાખ","4.92 લાખ"],correctIndex:2,explanation:"સાચો જવાબ: 4.92 લાખ. જાહેર વિતરણ પ્રણાલી હેઠળ દેશમાં આશરે 4.92 લાખ વાજબી ભાવની દુકાનો છે."},{id:"ss_q13_18",questionText:"18) ISO નું મુખ્ય મથક ............ માં છે.",options:["જીનિવા","ઇટાલી","સિંગાપુર"],correctIndex:0,explanation:"સાચો જવાબ: જીનિવા. International Organization for Standardization (ISO) નું મુખ્ય મથક સ્વિટ્ઝર્લેન્ડના જીનિવામાં છે."}]},q={id:"social_q14",subjectId:"social_science",chapterNumber:"પ્રશ્ન 14",title:"ભારત : જળ સંસાધન (ખાલી જગ્યા)",subtitle:"વિભાગ A • 16 ખાલી જગ્યા પ્રશ્નો",questionTypeLabel:"ખાલી જગ્યા",questions:[{id:"ss_q14_01",questionText:"1) ગુજરાતની કડાણા અને વણાકબોરી બહુહેતુક યોજના ............ નદી ઉપર બનાવવામાં આવેલ છે. (માર્ચ 2026)",options:["તાપી","સાબરમતી","મહીસાગર"],correctIndex:2,explanation:"સાચો જવાબ: મહીસાગર. કડાણા અને વણાકબોરી બહુહેતુક યોજનાઓ ગુજરાતની મહીસાગર નદી પર બનાવવામાં આવેલી છે."},{id:"ss_q14_02",questionText:"2) ............ જળનો સૌથી વધુ ઉપયોગ સિંચાઈ માટે થાય છે. (માર્ચ 2026)",options:["તળાવ","ભૂમિગત","નદી"],correctIndex:1,explanation:"સાચો જવાબ: ભૂમિગત. ભારતમાં ભૂમિગત જળનો સૌથી વધુ ઉપયોગ ખેતીની સિંચાઈ માટે થાય છે."},{id:"ss_q14_03",questionText:"3) કૃષ્ણરાજ સાગર બહુહેતુક યોજના ............ નદી પર આવેલી છે. — (માર્ચ 2025)",options:["કાવેરી","કૃષ્ણા","ગોદાવરી"],correctIndex:0,explanation:"સાચો જવાબ: કાવેરી. કૃષ્ણરાજ સાગર યોજના કર્ણાટકમાં કાવેરી નદી પર આવેલી છે."},{id:"ss_q14_04",questionText:"4) પૃષ્ઠીય જળનો મુખ્ય સ્ત્રોત ............ છે. — (માર્ચ 2024)",options:["તળાવો","નદીઓ","વૃષ્ટિ"],correctIndex:1,explanation:"સાચો જવાબ: નદીઓ. પૃથ્વીની સપાટી પર વહેતા પૃષ્ઠીય જળનો મુખ્ય સ્ત્રોત નદીઓ છે."},{id:"ss_q14_05",questionText:"5) ............ નદીમાંથી 'ગ્રાન્ડ એનિકટ' નામે જાણીતી નહેરનું નિર્માણ કરવામાં આવ્યું. — (માર્ચ 2024)",options:["કૃષ્ણા","કાવેરી","ગોદાવરી"],correctIndex:1,explanation:"સાચો જવાબ: કાવેરી. બીજી સદીમાં દક્ષિણ ભારતમાં કાવેરી નદીમાંથી 'ગ્રાન્ડ એનિકટ' નામની પ્રસિદ્ધ નહેર બનાવવામાં આવી હતી."},{id:"ss_q14_06",questionText:"6) પૃથ્વીના ............ ટકા ભાગમાં પાણી છે.",options:["71","81","78"],correctIndex:0,explanation:"સાચો જવાબ: 71. પૃથ્વીના કુલ વિસ્તારના લગભગ 71% ભાગમાં પાણી અને 29% ભાગમાં જમીન આવેલી છે."},{id:"ss_q14_07",questionText:"7) કાવેરી નદીમાંથી ............ નામે જાણીતી નહેરનું નિર્માણ બીજી સદીમાં થયું હતું. — (નમૂના પ્રશ્નપત્ર 2024-25)",options:["પૂર્વીય યમુના","ગ્રાન્ડ એનિકટ","ગોદાવરી"],correctIndex:1,explanation:"સાચો જવાબ: ગ્રાન્ડ એનિકટ. કાવેરી નદીના મુખત્રિકોણ પ્રદેશમાં બીજી સદીમાં 'ગ્રાન્ડ એનિકટ' (કલ્લનાઈ) નહેર બની હતી."},{id:"ss_q14_08",questionText:"8) પૃષ્ઠીય જળનો મુખ્ય સ્રોત ............ છે.",options:["સરોવરો","નદીઓ","વૃષ્ટિ"],correctIndex:1,explanation:"સાચો જવાબ: નદીઓ. પૃષ્ઠીય જળ મુખ્યત્વે નદીઓ, સરોવરો અને તળાવો રૂપે મળે છે જેમાં નદીઓ મુખ્ય સ્રોત છે."},{id:"ss_q14_09",questionText:"9) ભારતમાં ઉત્તરના મેદાની વિસ્તારમાં ............ % ભૂમિગત જળ મળે છે.",options:["32","52","42"],correctIndex:2,explanation:"સાચો જવાબ: 42. ભારતના ઉત્તરના વિશાળ મેદાની વિસ્તારમાં કુલ ભૂમિગત જળના લગભગ 42% જળ પ્રાપ્ત થાય છે."},{id:"ss_q14_10",questionText:"10) એક કિલો ઘઉંનું ઉત્પાદન કરવા માટે લગભગ ............ લિટર પાણીની આવશ્યકતા રહે છે.",options:["800","1000","1500"],correctIndex:2,explanation:"સાચો જવાબ: 1500. પાઠ્યપુસ્તક મુજબ 1 કિલો ઘઉં ઉત્પન્ન કરવા આશરે 1500 લિટર પાણીની જરૂર પડે છે."},{id:"ss_q14_11",questionText:"11) ............ ભારતમાં સિંચાઈના મુખ્ય માધ્યમો છે.",options:["કૂવા અને તળાવો","તળાવો અને ટ્યુબવેલ","કૂવા અને ટ્યુબવેલ"],correctIndex:2,explanation:"સાચો જવાબ: કૂવા અને ટ્યુબવેલ. ભારતમાં સિંચાઈના મુખ્ય માધ્યમો કૂવા અને ટ્યુબવેલ (ત્યારબાદ નહેરો) છે."},{id:"ss_q14_12",questionText:"12) પંજાબમાં સિંચાઈ ક્ષેત્રનું પ્રમાણ ............ % છે.",options:["58.4","60.8","90.8"],correctIndex:2,explanation:"સાચો જવાબ: 90.8. પંજાબ તેના સ્પષ્ટ વાવેતર ક્ષેત્રના 90.8% વિસ્તારમાં સિંચાઈ સુવિધા ધરાવે છે."},{id:"ss_q14_13",questionText:"13) હીરાકુડ યોજના ............ નદી પર આવેલી છે.",options:["દામોદર નદી","કોસી નદી","મહાનદી"],correctIndex:2,explanation:"સાચો જવાબ: મહાનદી. ઓડિશામાં હીરાકુડ બહુહેતુક યોજના મહાનદી પર બનાવવામાં આવેલી છે."},{id:"ss_q14_14",questionText:"14) ધરોઈ યોજના ............ નદી પર આવેલી છે.",options:["મહીસાગર","સાબરમતી","તાપી"],correctIndex:1,explanation:"સાચો જવાબ: સાબરમતી. મહેસાણા જિલ્લામાં આવેલી ધરોઈ યોજના સાબરમતી નદી પર બાંધવામાં આવી છે."},{id:"ss_q14_15",questionText:"15) હીરાકુંડ યોજના ............ પર આવેલી છે.",options:["ચંબલ નદી","મહાનદી","કૃષ્ણાનદી"],correctIndex:1,explanation:"સાચો જવાબ: મહાનદી. હીરાકુંડ બંધ ઓડિશાની મહાનદી પર બાંધવામાં આવેલો છે."},{id:"ss_q14_16",questionText:"16) ધરોઈ એ ............ નદી પરની યોજના છે.",options:["મહીસાગર","તાપી","સાબરમતી"],correctIndex:2,explanation:"સાચો જવાબ: સાબરમતી. ધરોઈ બંધ ઉત્તર ગુજરાતમાં સાબરમતી નદી પર સ્થિત છે."}]},l={id:"social_q15",subjectId:"social_science",chapterNumber:"પ્રશ્ન 15",title:"પરિવહન અને માર્ગ-સલામતી (ખાલી જગ્યા)",subtitle:"વિભાગ A • 8 ખાલી જગ્યા પ્રશ્નો",questionTypeLabel:"ખાલી જગ્યા",questions:[{id:"ss_q15_01",questionText:"1) દિબ્રુગઢથી ............ ને જોડતો રેલમાર્ગ ભારતનો સૌથી લાંબો રેલમાર્ગ છે. — (ફેબ્રુઆરી-માર્ચ 2026)",options:["બેંગ્લોર","ચેન્નઈ","કન્યાકુમારી"],correctIndex:2,explanation:"સાચો જવાબ: કન્યાકુમારી. આસામના દિબ્રુગઢથી તમિલનાડુના કન્યાકુમારી સુધીનો વિવેક એક્સપ્રેસ માર્ગ ભારતનો સૌથી લાંબો રેલમાર્ગ છે."},{id:"ss_q15_02",questionText:"2) હળવાં, મધ્યમ ગતિનાં તથા ભારે વાહનોને સામાન્ય રીતે ............ બાજુની લેનમાં જ વાહન ચલાવવું જોઈએ. — (ફેબ્રુઆરી-માર્ચ 2025)",options:["સૌથી ડાબી","સૌથી જમણી","મધ્યની"],correctIndex:0,explanation:"સાચો જવાબ: સૌથી ડાબી. ટ્રાફિક નિયમ મુજબ સામાન્ય રીતે વાહનોએ સૌથી ડાબી બાજુની લેનમાં ચલાવવું જોઈએ."},{id:"ss_q15_03",questionText:"3) એક્સપ્રેસ હાઈવેને ............ માર્ગ પણ કહેવાય છે. — (માર્ચ 2024)",options:["દ્રુતગતિ","સરહદી","રાષ્ટ્રીય"],correctIndex:0,explanation:"સાચો જવાબ: દ્રુતગતિ. ઝડપી પરિવહન માટે બનેલા એક્સપ્રેસ હાઈવેને 'દ્રુતગતિ માર્ગ' કહેવાય છે."},{id:"ss_q15_04",questionText:"4) ............ ની રેલવેએ દુર્ગમ પર્વતીય વિસ્તારોમાં સુરંગો ખોદી માર્ગ બનાવી શ્રેષ્ઠ ઈજનેરી કૌશલ્યનું દૃષ્ટાંત પૂરું પાડ્યું છે. — (નમૂના પ્રશ્નપત્ર 2024-25)",options:["કોંકણ","ટ્રામ્બે","વિવેક"],correctIndex:0,explanation:"સાચો જવાબ: કોંકણ. કોંકણ રેલવેએ પશ્ચિમ ઘાટના દુર્ગમ પર્વતીય વિસ્તારોમાં અનેક સુરંગો અને પુલો બનાવી શ્રેષ્ઠ ઈજનેરી કૌશલ્ય દર્શાવ્યું છે."},{id:"ss_q15_05",questionText:"5) ............ લોકો સારા પર્વતારોહકો છે.",options:["કઠિયારા","ભોટિયા","ગુરખા"],correctIndex:1,explanation:"સાચો જવાબ: ભોટિયા. હિમાલયના ઊંચા પર્વતીય વિસ્તારોમાં વસતા ભોટિયા લોકો કુશળ અને સારા પર્વતારોહકો હોય છે."},{id:"ss_q15_06",questionText:"6) ગુજરાતનો દરિયાકિનારો ............ કિલોમીટર લાંબો છે.",options:["૧૨૦૦","૧૫૦૦","૧૬૦૦"],correctIndex:2,explanation:"સાચો જવાબ: ૧૬૦૦. ગુજરાત ભારતમાં સૌથી લાંબો આશરે ૧૬૦૦ કિમીનો દરિયાકિનારો ધરાવે છે."},{id:"ss_q15_07",questionText:"7) ............ ઓટોમેટિક લોક ગેટ ધરાવતું એકમાત્ર બંદર છે.",options:["કંડલા","ભાવનગર","વેરાવળ"],correctIndex:1,explanation:"સાચો જવાબ: ભાવનગર. ગુજરાતનું ભાવનગર બંદર ઓટોમેટિક લોક ગેટ ધરાવતું એકમાત્ર બંદર છે."},{id:"ss_q15_08",questionText:"8) ભારતમાં આશરે ............ જેટલા રજ્જુમાર્ગો (રોપ-વે) આવેલા છે.",options:["૧૫૦","૧૦૦","૭૦"],correctIndex:1,explanation:"સાચો જવાબ: ૧૦૦. પાઠ્યપુસ્તક મુજબ ભારતમાં પર્વતીય વિસ્તારોમાં અંદાજે ૧૦૦ જેટલા રોપ-વે (રજ્જુમાર્ગો) આવેલા છે."}]},u={id:"social_q16",subjectId:"social_science",chapterNumber:"પ્રશ્ન 16",title:"આપણા વારસાનું જતન અને સંગ્રહાલયો (વિકલ્પો)",subtitle:"વિભાગ A • 15 બહુવિકલ્પ પ્રશ્નો",questionTypeLabel:"વિકલ્પો (M.C.Q.)",questions:[{id:"ss_q16_01",questionText:"1) રાષ્ટ્રીય માનવ સંગ્રહાલય ભારતના કયા શહેરમાં આવેલું છે? — (ફેબ્રુઆરી-માર્ચ 2026)",options:["(A) કોલકાતા","(B) મુંબઈ","(C) હૈદરાબાદ","(D) ભોપાલ"],correctIndex:3,explanation:"સાચો વિકલ્પ (D) ભોપાલ: ઇન્દિરા ગાંધી રાષ્ટ્રીય માનવ સંગ્રહાલય મધ્યપ્રદેશના ભોપાલ શહેરમાં આવેલું છે."},{id:"ss_q16_02",questionText:`2) સાચો ક્રમ પસંદ કરી જોડકાં જોડો : — (માર્ચ 2024)
(1) રાષ્ટ્રીય સંગ્રહાલય — (A) અમદાવાદ
(2) સાલારગંજ — (B) વડોદરા
(3) વડોદરા મ્યુઝિયમ — (C) હૈદરાબાદ
(4) લાલભાઈ દલપતભાઈ સંગ્રહાલય — (D) નવી દિલ્હી`,options:["(A) (1-C), (2-D), (3-A), (4-B)","(B) (1-D), (2-C), (3-B), (4-A)","(C) (1-A), (2-B), (3-C), (4-D)","(D) (1-D), (2-A), (3-B), (4-C)"],correctIndex:1,explanation:"સાચો વિકલ્પ (B): રાષ્ટ્રીય સંગ્રહાલય -> નવી દિલ્હી (D), સાલારગંજ -> હૈદરાબાદ (C), વડોદરા મ્યુઝિયમ -> વડોદરા (B), લાલભાઈ દલપતભાઈ સંગ્રહાલય -> અમદાવાદ (A)."},{id:"ss_q16_03",questionText:`3) સાચો ક્રમ પસંદ કરી જોડકાં જોડો : — (નમૂના પ્રશ્નપત્ર 2024-25)
(1) હેમચંદ્રાચાર્ય ગ્રંથાલય — (A) મુંબઈ
(2) ભારતીય સંગ્રહાલય — (B) ભોપાલ
(3) છત્રપતિ શિવાજી મહારાજ સંગ્રહાલય — (C) પાટણ
(4) રાષ્ટ્રીય માનવ સંગ્રહાલય — (D) કોલકાતા`,options:["(A) (1-C), (2-D), (3-A), (4-B)","(B) (1-A), (2-B), (3-D), (4-C)","(C) (1-A), (2-C), (3-B), (4-D)","(D) (1-B), (2-D), (3-C), (4-A)"],correctIndex:0,explanation:"સાચો વિકલ્પ (A): હેમચંદ્રાચાર્ય ગ્રંથાલય -> પાટણ (C), ભારતીય સંગ્રહાલય -> કોલકાતા (D), છત્રપતિ શિવાજી મહારાજ સંગ્રહાલય -> મુંબઈ (A), રાષ્ટ્રીય માનવ સંગ્રહાલય -> ભોપાલ (B)."},{id:"ss_q16_04",questionText:"4) વિદેશી પર્યટકો આવવાથી ભારતને શું પ્રાપ્ત થાય છે? — (નમૂના પ્રશ્નપત્ર 2024-25)",options:["(A) વિદેશી હૂંડિયામણ","(B) વિદેશી નિકાસ","(C) શ્રમબજાર","(D) આયાત વેરો"],correctIndex:0,explanation:"સાચો વિકલ્પ (A) વિદેશી હૂંડિયામણ: વિદેશી પ્રવાસીઓ ભારતમાં આવતા દેશને કિંમતી વિદેશી હૂંડિયામણ પ્રાપ્ત થાય છે."},{id:"ss_q16_05",questionText:"5) વારસો એ દેશની ............ છે.",options:["(A) ચેતના","(B) ગૌરવ","(C) ઓળખ","(D) મૂડી"],correctIndex:2,explanation:"સાચો વિકલ્પ (C) ઓળખ: વારસો એ દેશની આગવી ઓળખ (અરીસો) છે."},{id:"ss_q16_06",questionText:"6) ભારતમાં વિવિધ લોકો કઈ ભાવનાથી પોતાનું જીવન જીવે છે?",options:["(A) પરંપરા","(B) ઉત્સવો","(C) સહઅસ્તિત્વ","(D) સ્પર્ધા"],correctIndex:2,explanation:"સાચો વિકલ્પ (C) સહઅસ્તિત્વ: ભારતમાં વિવિધ જાતિ-ધર્મના લોકો સદ્ભાવના, સહિષ્ણુતા અને સહઅસ્તિત્વની ભાવનાથી જીવે છે."},{id:"ss_q16_07",questionText:"7) પર્યટન ઉદ્યોગથી રાજ્યને કયો લાભ થાય છે?",options:["(A) રાજકીય","(B) સાંસ્કૃતિક","(C) આર્થિક","(D) સામાજિક"],correctIndex:2,explanation:"સાચો વિકલ્પ (C) આર્થિક: પર્યટન ઉદ્યોગથી રોજગારી, વિદેશી હૂંડિયામણ અને રાજ્યની આવક વધે છે, જે આર્થિક લાભ છે."},{id:"ss_q16_08",questionText:"8) ગુજરાત પ્રવાસન નિગમ દ્વારા આયોજિત ચિત્રસ્પર્ધામાં અસંગત/ખોટી જોડીવાળું કયું ચિત્ર નાપસંદ કરવામાં આવ્યું?",options:["(A) કીર્તિતોરણ - વડનગર","(B) ભવનાથનો મેળો - જૂનાગઢ","(C) દામોદર કુંડ - તુલસીશ્યામ","(D) સૂર્યમંદિર - મોઢેરા"],correctIndex:2,explanation:"સાચો વિકલ્પ (C) દામોદર કુંડ - તુલસીશ્યામ: દામોદર કુંડ તુલસીશ્યામમાં નહીં પરંતુ જૂનાગઢ (ગિરનાર તળેટી) માં આવેલો છે."},{id:"ss_q16_09",questionText:"9) ભારતીય સંગ્રહાલય કયા શહેરમાં આવેલું છે?",options:["(A) કોલકાતા","(B) મુંબઈ","(C) ભોપાલ","(D) નવી દિલ્હી"],correctIndex:0,explanation:"સાચો વિકલ્પ (A) કોલકાતા: ભારતીય સંગ્રહાલય (Indian Museum) પશ્ચિમ બંગાળના કોલકાતા શહેરમાં આવેલું છે."},{id:"ss_q16_10",questionText:"10) સાલારગંજ સંગ્રહાલય કયા શહેરમાં આવેલું છે?",options:["(A) ચેન્નઈ","(B) હૈદરાબાદ","(C) બેંગલુરુ","(D) પટણા"],correctIndex:1,explanation:"સાચો વિકલ્પ (B) હૈદરાબાદ: વિશ્વપ્રસિદ્ધ સાલારગંજ સંગ્રહાલય તેલંગાણાના હૈદરાબાદ શહેરમાં આવેલું છે."},{id:"ss_q16_11",questionText:"11) શ્રી હેમચંદ્રાચાર્ય ગ્રંથાલય ગુજરાતના કયા શહેરમાં આવેલું છે?",options:["(A) વડનગર","(B) સિદ્ધપુર","(C) પાટણ","(D) અમદાવાદ"],correctIndex:2,explanation:"સાચો વિકલ્પ (C) પાટણ: શ્રી હેમચંદ્રાચાર્ય ગ્રંથાલય ગુજરાતના પાટણ શહેરમાં આવેલું છે."},{id:"ss_q16_12",questionText:"12) એલ. ડી. ઇન્સ્ટિટ્યૂટ ઑફ ઇન્ડોલોજી સંગ્રહાલય ક્યાં આવેલું છે?",options:["(A) વડોદરા","(B) અમદાવાદ","(C) સુરત","(D) રાજકોટ"],correctIndex:1,explanation:"સાચો વિકલ્પ (B) અમદાવાદ: લાલભાઈ દલપતભાઈ (L.D.) ઇન્સ્ટિટ્યૂટ ઑફ ઇન્ડોલોજી સંગ્રહાલય અમદાવાદમાં આવેલું છે."},{id:"ss_q16_13",questionText:"13) વડોદરામાં આવેલું જાણીતું સંગ્રહાલય કયું છે?",options:["(A) પ્રિન્સ ઑફ વેલ્સ મ્યુઝિયમ","(B) મહારાજા સયાજીરાવ મ્યુઝિયમ (પિક્ચર ગેલેરી)","(C) સાલારગંજ સંગ્રહાલય","(D) રાષ્ટ્રીય માનવ સંગ્રહાલય"],correctIndex:1,explanation:"સાચો વિકલ્પ (B): વડોદરામાં મહારાજા સયાજીરાવ (બરોડા) મ્યુઝિયમ અને પિક્ચર ગેલેરી આવેલા છે."},{id:"ss_q16_14",questionText:"14) છત્રપતિ શિવાજી મહારાજ વાસ્તુ સંગ્રહાલય (પ્રિન્સ ઑફ વેલ્સ મ્યુઝિયમ) કયા શહેરમાં આવેલું છે?",options:["(A) પુણે","(B) નાગપુર","(C) મુંબઈ","(D) ઔરંગાબાદ"],correctIndex:2,explanation:"સાચો વિકલ્પ (C) મુંબઈ: છત્રપતિ શિવાજી મહારાજ વાસ્તુ સંગ્રહાલય મહારાષ્ટ્રના મુંબઈ શહેરમાં આવેલું છે."},{id:"ss_q16_15",questionText:"15) 'મુંબઈ પ્રાકૃતિક ઇતિહાસ સમિતિ' (BNHS) ની સ્થાપના ક્યારે થઈ હતી?",options:["(A) ઈ.સ. 1883 માં","(B) ઈ.સ. 1983 માં","(C) ઈ.સ. 1952 માં","(D) ઈ.સ. 1972 માં"],correctIndex:0,explanation:"સાચો વિકલ્પ (A) ઈ.સ. 1883 માં: પર્યાવરણ અને વન્યજીવ સંરક્ષણ માટે કાર્યરત સૌથી જૂની સંસ્થા BNHS ની સ્થાપના ઈ.સ. 1883 માં થઈ હતી."}]},I={id:"social_q17",subjectId:"social_science",chapterNumber:"પ્રશ્ન 17",title:"વન્યજીવ, ઉદ્યોગો અને ગ્રાહક સુરક્ષા (વિકલ્પો)",subtitle:"વિભાગ A • 22 બહુવિકલ્પ પ્રશ્નો",questionTypeLabel:"વિકલ્પો (M.C.Q.)",questions:[{id:"ss_q17_01",questionText:"1) નીચેનામાંથી કયું જૈવ આરક્ષિત ક્ષેત્ર છે? (માર્ચ 2025)",options:["(A) પેરિયાર","(B) દચિગામ","(C) કોર્બેટ","(D) પચમઢી"],correctIndex:3,explanation:"સાચો વિકલ્પ (D) પચમઢી: પચમઢી (મધ્યપ્રદેશ) જૈવ આરક્ષિત ક્ષેત્ર છે, જ્યારે પેરિયાર અભયારણ્ય અને દચિગામ તથા કોર્બેટ રાષ્ટ્રીય ઉદ્યાનો છે."},{id:"ss_q17_02",questionText:"2) ગુજરાતના જંગલોમાંથી લુપ્ત થયેલો વન્યજીવ કયો છે?",options:["(A) ઘુડખર","(B) રીંછ","(C) વાઘ","(D) દીપડો"],correctIndex:2,explanation:"સાચો વિકલ્પ (C) વાઘ: પાઠ્યપુસ્તક મુજબ ગુજરાતના જંગલોમાંથી 'વાઘ' લુપ્ત થયેલ વન્યજીવ છે."},{id:"ss_q17_03",questionText:"3) સ્થાનિક સ્વરાજ્યની સંસ્થાઓનું નિયંત્રણ હોય તેવા જંગલો કયા નામે ઓળખાય છે?",options:["(A) ગ્રામ્યવનો","(B) અભયારણ્યો","(C) સામુદાયિક જંગલો","(D) ઝૂમ જંગલો"],correctIndex:2,explanation:"સાચો વિકલ્પ (C) સામુદાયિક જંગલો: ગ્રામપંચાયત, નગરપાલિકા કે જિલ્લા પંચાયત જેવી સ્થાનિક સ્વરાજ્યની સંસ્થાઓના નિયંત્રણ હેઠળના જંગલોને સામુદાયિક જંગલો કહે છે."},{id:"ss_q17_04",questionText:"4) વિશ્વમાં પશુ-પક્ષીઓની કુલ લગભગ કેટલી પ્રજાતિઓ છે?",options:["(A) બાર લાખ","(B) એકવીસ લાખ","(C) સાત લાખ","(D) પંદર લાખ"],correctIndex:3,explanation:"સાચો વિકલ્પ (D) પંદર લાખ: સમગ્ર વિશ્વમાં પશુ-પક્ષીઓની લગભગ પંદર લાખ જેટલી પ્રજાતિઓ છે, જેમાંથી 81,251 ભારતમાં છે."},{id:"ss_q17_05",questionText:"5) નિર્વનીકરણને લીધે વાતાવરણમાં કયા વાયુની માત્રા વધે છે?",options:["(A) નાઇટ્રોજન","(B) ઓક્સિજન","(C) કાર્બન ડાયોક્સાઇડ","(D) એકપણ નહીં"],correctIndex:2,explanation:"સાચો વિકલ્પ (C) કાર્બન ડાયોક્સાઇડ: જંગલોનો નાશ થતા પ્રકાશસંશ્લેષણ ઘટે છે અને વાતાવરણમાં કાર્બન ડાયોક્સાઇડનું પ્રમાણ વધે છે."},{id:"ss_q17_06",questionText:"6) કયા જંગલો સીધા સરકારી તંત્રના નિયંત્રણમાં હોય છે?",options:["(A) અનામત","(B) અવર્ગીકૃત","(C) સામુદાયિક","(D) સંરક્ષિત"],correctIndex:0,explanation:"સાચો વિકલ્પ (A) અનામત: અનામત જંગલો (Reserved Forests) સીધા સરકારી તંત્રના નિયંત્રણમાં હોય છે."},{id:"ss_q17_07",questionText:"7) નીચેનામાંથી કયો રેશમનો પ્રકાર નથી? — (ફેબ્રુઆરી-માર્ચ 2025)",options:["(A) ઈરી","(B) ટસર","(C) શેતૂર","(D) ઝીંગા"],correctIndex:3,explanation:"સાચો વિકલ્પ (D) ઝીંગા: ભારતમાં શેતૂર, ઈરી, ટસર અને મૂગા એમ 4 પ્રકારનું રેશમ મળે છે; ઝીંગા એ મત્સ્ય પ્રજાતિ છે."},{id:"ss_q17_08",questionText:"8) ભારતનું કયું શહેર 'સિલિકોન વેલી' તરીકે જાણીતું બન્યું છે?",options:["(A) દિલ્હી","(B) બેંગાલુરુ","(C) જયપુર","(D) નાગપુર"],correctIndex:1,explanation:"સાચો વિકલ્પ (B) બેંગાલુરુ: ઇલેક્ટ્રોનિક્સ અને સોફ્ટવેર ઉદ્યોગનું મુખ્ય કેન્દ્ર હોવાથી બેંગાલુરુને ભારતની 'સિલિકોન વેલી' કહે છે."},{id:"ss_q17_09",questionText:"9) ગુજરાતમાં મિની સ્ટીલ પ્લાન્ટ ક્યાં પ્રસ્થાપિત થયો છે?",options:["(A) કંડલા","(B) ઓખા","(C) દ્વારકા","(D) હજીરા"],correctIndex:3,explanation:"સાચો વિકલ્પ (D) હજીરા: ગુજરાતમાં સુરત નજીક 'હજીરા' ખાતે મિની સ્ટીલ પ્લાન્ટ પ્રસ્થાપિત થયો છે."},{id:"ss_q17_10",questionText:"10) શણની નિકાસમાં વિશ્વમાં ભારત કયા સ્થાને છે?",options:["(A) પ્રથમ","(B) બીજા","(C) ત્રીજા","(D) ચોથા"],correctIndex:1,explanation:"સાચો વિકલ્પ (B) બીજા: શણની ચીજવસ્તુઓના ઉત્પાદનમાં ભારત પ્રથમ, જ્યારે નિકાસમાં બાંગ્લાદેશ પછી બીજા સ્થાને છે."},{id:"ss_q17_11",questionText:"11) ભારતમાં રેશમના પ્રકારો કેટલા છે?",options:["(A) એક","(B) બે","(C) ત્રણ","(D) ચાર"],correctIndex:3,explanation:"સાચો વિકલ્પ (D) ચાર: ભારતમાં શેતૂર, ઈરી, ટસર અને મૂગા એમ રેશમના ચાર પ્રકારોનું ઉત્પાદન થાય છે."},{id:"ss_q17_12",questionText:"12) જમશેદપુરનું લોખંડ-પોલાદનું કારખાનું કયા રાજ્યમાં આવેલું છે?",options:["(A) છત્તીસગઢ","(B) પશ્ચિમ બંગાળ","(C) ઝારખંડ","(D) બિહાર"],correctIndex:2,explanation:"સાચો વિકલ્પ (C) ઝારખંડ: જમશેદપુર (ટાટાનગર) નું લોખંડ-પોલાદનું કારખાનું ઝારખંડ રાજ્યમાં આવેલું છે."},{id:"ss_q17_13",questionText:"13) ભારતની મોટા ભાગની શણની મિલો કઈ નદીના કિનારે આવેલી છે?",options:["(A) હુગલી","(B) દામોદર","(C) સુવર્ણરેખા","(D) નર્મદા"],correctIndex:0,explanation:"સાચો વિકલ્પ (A) હુગલી: ભારતની લગભગ 80% શણની મિલો પશ્ચિમ બંગાળમાં હુગલી નદીના કિનારે આવેલી છે."},{id:"ss_q17_14",questionText:"14) ભારતમાં સૌથી વધારે રોજગારી પૂરી પાડતો ઉદ્યોગ કયો છે?",options:["(A) સિમેન્ટ ઉદ્યોગ","(B) સુતરાઉ કાપડ ઉદ્યોગ","(C) રેશમી કાપડ ઉદ્યોગ","(D) શણ ઉદ્યોગ"],correctIndex:1,explanation:"સાચો વિકલ્પ (B) સુતરાઉ કાપડ ઉદ્યોગ: ભારતમાં આશરે 3.5 કરોડ લોકોને રોજગારી પૂરી પાડતો સુતરાઉ કાપડ ઉદ્યોગ અગ્રસ્થાને છે."},{id:"ss_q17_15",questionText:"15) ગુજરાત સરકારે ગ્રાહક સુરક્ષાના નિયમો - 1988 ક્યારે અમલમાં મૂક્યા? — (માર્ચ 2025)",options:["(A) 21, જાન્યુઆરી - 1988","(B) 18, ફેબ્રુઆરી - 1988","(C) 15, માર્ચ - 1988","(D) 26, જાન્યુઆરી - 1988"],correctIndex:1,explanation:"સાચો વિકલ્પ (B) 18, ફેબ્રુઆરી - 1988: ગુજરાત સરકારે ગુજરાત ગ્રાહક સુરક્ષા નિયમો-1988, 18 ફેબ્રુઆરી 1988 ના રોજ અમલમાં મૂક્યા."},{id:"ss_q17_16",questionText:"16) ભારતની મધ્યસ્થ બેંક કઈ છે?",options:["(A) યુનિયન બેન્ક ઓફ ઇન્ડિયા","(B) બેન્ક ઓફ ઇન્ડિયા","(C) રિઝર્વ બેન્ક ઓફ ઇન્ડિયા","(D) ઓરિએન્ટલ બેન્ક ઓફ કોમર્સ"],correctIndex:2,explanation:"સાચો વિકલ્પ (C) રિઝર્વ બેન્ક ઓફ ઇન્ડિયા (RBI): તે ભારતની સર્વોચ્ચ મધ્યસ્થ બેંક છે."},{id:"ss_q17_17",questionText:"17) નાણાંનો પુરવઠો ચીજવસ્તુઓના પુરવઠા કરતાં વધી જાય ત્યારે શું સ્થિતિ થાય છે?",options:["(A) ભાવો સ્થિર થાય છે","(B) ભાવ વધી જાય છે","(C) ભાવ ઘટી જાય છે","(D) ઉત્પાદન સ્થિર બને છે"],correctIndex:1,explanation:"સાચો વિકલ્પ (B) ભાવ વધી જાય છે: નાણાંનો પુરવઠો વધતા લોકોની ખરીદશક્તિ અને માંગ વધે છે, પરિણામે ભાવવધારો (ફુગાવો) થાય છે."},{id:"ss_q17_18",questionText:"18) સરકારે ભાવસપાટીને અંકુશિત રાખવા માટે કયો ધારો અમલમાં મૂક્યો છે?",options:["(A) ગ્રાહક સુરક્ષા ધારો","(B) આવશ્યક ચીજવસ્તુ ધારો","(C) આવશ્યક સેવા ધારો","(D) અંકુશ ધારો"],correctIndex:1,explanation:"સાચો વિકલ્પ (B) આવશ્યક ચીજવસ્તુ ધારો: ભાવસપાટી સ્થિર રાખવા અને સંગ્રહખોરી રોકવા આવશ્યક ચીજવસ્તુ ધારો - 1955 અમલમાં મૂકાયો છે."},{id:"ss_q17_19",questionText:"19) ગ્રાહકે હંમેશા કેવા માર્કાવાળી ચીજવસ્તુઓ ખરીદવાનો આગ્રહ રાખવો જોઈએ?",options:["(A) ISD","(B) PSI","(C) STD","(D) ISI"],correctIndex:3,explanation:"સાચો વિકલ્પ (D) ISI: ગુણવત્તા અને સુરક્ષાની ખાતરી માટે ગ્રાહકે હંમેશા ISI માર્કાવાળી ચીજવસ્તુઓ ખરીદવી જોઈએ."},{id:"ss_q17_20",questionText:"20) રોહિણીબહેને અથાણાં બનાવવાની ફેક્ટરી (ગૃહ ઉદ્યોગ) શરૂ કરી, ઉત્પાદનની યોગ્ય ગુણવત્તા માટે તેઓએ કયો માર્કો મેળવવો જોઈએ?",options:["(A) ISI","(B) એગમાર્ક (FPO)","(C) DMI","(D) ISO"],correctIndex:1,explanation:"સાચો વિકલ્પ (B) એગમાર્ક (FPO): ફળો, શાકભાજી, જામ, અથાણાં જેવા કૃષિ-ખાદ્ય ઉત્પાદનો માટે એગમાર્ક / FPO માર્કો મેળવાય છે."},{id:"ss_q17_21",questionText:"21) કેન્દ્ર સરકારે ગ્રાહક સંબંધી કાયદા-નિયમો માટે કઈ સંસ્થા સ્થાપી છે?",options:["(A) રાષ્ટ્રીય તકરાર નિવારણ તંત્ર","(B) રાષ્ટ્રીય ઉપભોક્તા આયોગ","(C) રાષ્ટ્રીય ગ્રાહક કમિશન","(D) ગ્રાહક સુરક્ષા આયોગ"],correctIndex:1,explanation:"સાચો વિકલ્પ (B) રાષ્ટ્રીય ઉપભોક્તા આયોગ: કેન્દ્ર સરકારે ગ્રાહક સંબંધી કાયદા-નિયમોના અમલ માટે રાષ્ટ્રીય ઉપભોક્તા આયોગની સ્થાપના કરી છે."},{id:"ss_q17_22",questionText:"22) ગ્રાહક શિક્ષણ અને જાગૃતિ માટે કયું સામાયિક બહાર પાડવામાં આવે છે?",options:["(A) ઇનસાઇટ","(B) ગ્રાહક જાગૃતિ મંચ","(C) ગ્રાહક શિક્ષણ","(D) કન્ઝ્યુમર એક્ટ"],correctIndex:0,explanation:"સાચો વિકલ્પ (A) ઇનસાઇટ: CERC (અમદાવાદ) અને ગ્રાહક મંડળો દ્વારા ગ્રાહક જાગૃતિ માટે 'ઇનસાઇટ' નામનું સામાયિક બહાર પાડવામાં આવે છે."}]},T={id:"social_q18",subjectId:"social_science",chapterNumber:"પ્રશ્ન 18",title:"ભારત : જળ સંસાધન (વિકલ્પો)",subtitle:"વિભાગ A • 18 બહુવિકલ્પ પ્રશ્નો",questionTypeLabel:"વિકલ્પો (M.C.Q.)",questions:[{id:"ss_q18_01",questionText:"1) વર્ગખંડમાં 'ખેત તલાવડી' વિશે વિદ્યાર્થીઓની ચર્ચા દરમિયાન રજૂ થયેલું કયું વિધાન યોગ્ય છે? — (ફેબ્રુઆરી-માર્ચ 2026)",options:["(A) પરમ : તે વધુ વૃક્ષો વાવો આંદોલનનું મહત્ત્વનું અંગ છે.","(B) રાવી : તે ઉદ્યોગ માટે પાણીની પ્રાપ્તિનું મહત્ત્વનું સંસાધન છે.","(C) અનય : તે જમીનનું ધોવાણ વધારવાની આધુનિક તકનીક છે.","(D) મયંક : તે વૃષ્ટિ જળ સંચયની એક પદ્ધતિ છે."],correctIndex:3,explanation:"સાચો વિકલ્પ (D) મયંક: ખેત તલાવડી એ ખેતરના ઢોળાવવાળા ભાગમાં વરસાદી પાણી (વૃષ્ટિ જળ) સંચય કરવાની પદ્ધતિ છે."},{id:"ss_q18_02",questionText:"2) પૃથ્વીના કેટલા ટકા ભાગમાં પાણી છે? — (માર્ચ 2026)",options:["(A) 51%","(B) 61%","(C) 71%","(D) 81%"],correctIndex:2,explanation:"સાચો વિકલ્પ (C) 71%: પૃથ્વીની સપાટીના લગભગ 71% ભાગમાં પાણી આવેલું છે."},{id:"ss_q18_03",questionText:"3) નીચેની બહુહેતુક યોજનાઓને તેમના સ્થાનના આધારે દક્ષિણ દિશાથી ઉત્તર દિશા તરફ ગોઠવતાં કયો વિકલ્પ સાચો જણાય છે? — (માર્ચ 2024)",options:["(A) ભાખરા નાંગલ, નાગાર્જુન સાગર, ચંબલ, નર્મદા","(B) ચંબલ, ભાખરા નાંગલ, નર્મદા, નાગાર્જુન સાગર","(C) નર્મદા, ચંબલ, નાગાર્જુન સાગર, ભાખરા નાંગલ","(D) નાગાર્જુન સાગર, નર્મદા, ચંબલ, ભાખરા નાંગલ"],correctIndex:3,explanation:"સાચો વિકલ્પ (D): દક્ષિણથી ઉત્તર ક્રમ — નાગાર્જુન સાગર (આંધ્ર/તેલંગાણા) -> નર્મદા (ગુજરાત/મ.પ્ર.) -> ચંબલ (રાજસ્થાન/મ.પ્ર.) -> ભાખરા નાંગલ (પંજાબ/હિમાચલ)."},{id:"ss_q18_04",questionText:"4) ભારતમાં લગભગ કેટલા ટકા જળ સિંચાઈ માટે ઉપયોગી છે? — (માર્ચ 2024)",options:["(A) 84%","(B) 83%","(C) 52%","(D) 8%"],correctIndex:0,explanation:"સાચો વિકલ્પ (A) 84%: ભારતમાં ઉપલબ્ધ જળના લગભગ 84% જળ સિંચાઈ માટે ઉપયોગી બને છે."},{id:"ss_q18_05",questionText:"5) વર્ગખંડમાં 'ખેત તલાવડી' વિશે વિદ્યાર્થીઓની ચર્ચા દરમિયાન રજૂ થયેલું કયું વિધાન યોગ્ય છે? — (નમૂના પ્રશ્નપત્ર 2024-25)",options:["(A) જય : તે પીવા યોગ્ય પાણીની પ્રાપ્તિનું મહત્ત્વનું સંસાધન છે.","(B) યશ : તે વધુ વૃક્ષો વાવો આંદોલનનું મહત્ત્વનું અંગ છે.","(C) યુગ : તે જમીનનું ધોવાણ અટકાવવાની આધુનિક તકનિક છે.","(D) દક્ષ : તે વૃષ્ટિ જળસંચયની એક પદ્ધતિ છે."],correctIndex:3,explanation:"સાચો વિકલ્પ (D) દક્ષ: ખેત તલાવડી વૃષ્ટિ જળસંચય (Rainwater Harvesting) ની એક અસરકારક પદ્ધતિ છે."},{id:"ss_q18_06",questionText:"6) પૃષ્ઠીય જળનો મુખ્ય સ્રોત કયો છે? — (નમૂના પ્રશ્નપત્ર 2024-25)",options:["(A) વૃષ્ટિ","(B) તળાવો","(C) નદીઓ","(D) સરોવર"],correctIndex:2,explanation:"સાચો વિકલ્પ (C) નદીઓ: પૃષ્ઠીય જળનો મુખ્ય સ્રોત નદીઓ છે."},{id:"ss_q18_07",questionText:"7) પૃથ્વી પર જળ સંસાધનનો મુખ્ય સ્રોત કયો છે?",options:["(A) મહાસાગર","(B) નદી","(C) સરોવર","(D) વૃષ્ટિ"],correctIndex:3,explanation:"સાચો વિકલ્પ (D) વૃષ્ટિ: પૃથ્વી પર મીઠા જળ સંસાધનનો મૂળ અને મુખ્ય સ્રોત વૃષ્ટિ (વરસાદ) છે."},{id:"ss_q18_08",questionText:"8) ભારતમાં સ્વાતંત્ર્ય બાદ સિંચાઈ ક્ષેત્ર વધીને કેટલું થયું છે?",options:["(A) દોઢ ગણું","(B) અઢી ગણું","(C) ત્રણ ગણું","(D) ચાર ગણું"],correctIndex:3,explanation:"સાચો વિકલ્પ (D) ચાર ગણું: ભારતમાં આઝાદી પછી બહુહેતુક યોજનાઓને લીધે સિંચાઈ ક્ષેત્ર વધીને લગભગ ચાર ગણું થયું છે."},{id:"ss_q18_09",questionText:"9) ભારતનું કયું રાજ્ય તેના સ્પષ્ટ વાવેતર ક્ષેત્રના સંદર્ભમાં સૌથી વધુ સિંચાઈ ક્ષેત્ર ધરાવે છે?",options:["(A) પંજાબ","(B) ઉત્તર પ્રદેશ","(C) બિહાર","(D) મહારાષ્ટ્ર"],correctIndex:0,explanation:"સાચો વિકલ્પ (A) પંજાબ: પંજાબ તેના સ્પષ્ટ વાવેતર ક્ષેત્રના 90.8% વિસ્તાર સાથે દેશમાં પ્રથમ સ્થાને છે."},{id:"ss_q18_10",questionText:"10) ઓડિશાની કઈ નદી મુખત્રિકોણ પ્રદેશ ધરાવે છે?",options:["(A) કૃષ્ણા","(B) મહાનદી","(C) કાવેરી","(D) મહીનદી"],correctIndex:1,explanation:"સાચો વિકલ્પ (B) મહાનદી: ઓડિશામાં વહેતી મહાનદી બંગાળની ખાડીને મળતાં પહેલાં વિશાળ મુખત્રિકોણ પ્રદેશ બનાવે છે."},{id:"ss_q18_11",questionText:"11) નીચેની બહુહેતુક યોજનાઓને તેમના સ્થાનના આધારે ઉત્તર દિશાથી દક્ષિણ દિશા તરફ ગોઠવતાં કયો વિકલ્પ સાચો જણાય છે?",options:["(A) ચંબલ ખીણ, ભાખરા-નાંગલ, નર્મદા ખીણ, નાગાર્જુન સાગર","(B) ભાખરા-નાંગલ, નાગાર્જુન સાગર, નર્મદા ખીણ, ચંબલ ખીણ","(C) નાગાર્જુન સાગર, નર્મદા ખીણ, ચંબલ ખીણ, ભાખરા-નાંગલ","(D) ભાખરા-નાંગલ, ચંબલ ખીણ, નર્મદા ખીણ, નાગાર્જુન સાગર"],correctIndex:3,explanation:"સાચો વિકલ્પ (D): ઉત્તરથી દક્ષિણ ક્રમ — ભાખરા-નાંગલ (પંજાબ/હિમાચલ) -> ચંબલ ખીણ (મ.પ્ર./રાજ.) -> નર્મદા ખીણ (મ.પ્ર./ગુજરાત) -> નાગાર્જુન સાગર (આંધ્ર/તેલંગાણા)."},{id:"ss_q18_12",questionText:`12) નીચેની બહુહેતુક યોજનાઓને તેના લાભાન્વિત રાજ્યની સાથે જોડી યોગ્ય ક્રમ પસંદ કરો :
(1) ભાખરા-નાંગલ — (a) બિહાર
(2) કોસી — (b) પંજાબ
(3) નાગાર્જુન સાગર — (c) ગુજરાત
(4) નર્મદા — (d) આંધ્રપ્રદેશ`,options:["(A) (1-b) (2-a) (3-c) (4-d)","(B) (1-b) (2-a) (3-d) (4-c)","(C) (1-d) (2-c) (3-b) (4-a)","(D) (1-c) (2-d) (3-a) (4-b)"],correctIndex:1,explanation:"સાચો વિકલ્પ (B): ભાખરા-નાંગલ -> પંજાબ (b), કોસી -> બિહાર (a), નાગાર્જુન સાગર -> આંધ્રપ્રદેશ (d), નર્મદા -> ગુજરાત (c)."},{id:"ss_q18_13",questionText:"13) નીચેના પૈકી કયું વિધાન સાચું નથી?",options:["(A) ભારતમાં નહેરોની સરખામણીએ કૂવા અને ટ્યૂબવેલ વડે થતી સિંચાઈનું પ્રમાણ વધારે છે.","(B) હિમાલયમાંથી નીકળતી નદીઓ મોસમી નદીઓ કહેવાય છે.","(C) જમીનની સપાટી પરથી શોષાઈને ભૂમિ નીચે જમા થતા જળને ભૂમિગત જળ કહે છે.","(D) પંજાબ અને હરિયાણા સિંચાઈક્ષેત્રે અગ્રેસર રાજ્યો છે."],correctIndex:1,explanation:"સાચો વિકલ્પ (B): હિમાલયમાંથી નીકળતી નદીઓ બરફ પીગળવાથી બારેમાસ વહેતી 'બારમાસી' (કાયમી) નદીઓ છે, મોસમી નહીં; તેથી વિધાન (B) ખોટું છે."},{id:"ss_q18_14",questionText:"14) જળસ્રોતોના પ્રકારોને ઓળખો :",options:["(A) વૃષ્ટીય જળ, પૃષ્ઠીય જળ, ભૂમિગત જળ","(B) તળાવો, નહેરો, કૂવા અને ટ્યૂબવેલ","(C) સિંચાઈ, પેયજળ, મલિન જળ","(D) વૃષ્ટિજળ સંચયન, જળપ્લાવિત ક્ષેત્ર, જળ સંરક્ષણ"],correctIndex:0,explanation:"સાચો વિકલ્પ (A): ભારતના મુખ્ય ત્રણ જળસ્રોતો વૃષ્ટીય જળ, પૃષ્ઠીય જળ અને ભૂમિગત જળ છે."},{id:"ss_q18_15",questionText:"15) નીચેનામાંથી એક જોડકું સાચું નથી તે શોધો :",options:["(A) કોસી નદી – કોસી યોજના","(B) મહાનદી – હીરાકુંડ યોજના","(C) તાપી નદી – ઉકાઈ, કાકરાપાર","(D) કડાણા, વણાકબોરી – કૃષ્ણરાજ સાગર"],correctIndex:3,explanation:"સાચો વિકલ્પ (D): કડાણા અને વણાકબોરી મહીસાગર નદીની યોજનાઓ છે, જ્યારે કૃષ્ણરાજ સાગર કાવેરી નદીની યોજના છે."},{id:"ss_q18_16",questionText:`16) નીચે દર્શાવેલ જોડકાંને લક્ષ્યમાં લઈ આપેલા વિકલ્પોમાંથી સાચો વિકલ્પ પસંદ કરો :
(1) ભાખરા-નાંગલ — (a) મધ્યપ્રદેશ, ગુજરાત, રાજસ્થાન અને મહારાષ્ટ્ર
(2) નર્મદા ખીણ — (b) કર્ણાટક, તમિલનાડુ
(3) તુંગભદ્રા — (c) આંધ્રપ્રદેશ, તેલંગણા
(4) નાગાર્જુન સાગર — (d) પંજાબ, હરિયાણા, રાજસ્થાન
(e) કર્ણાટક, આંધ્રપ્રદેશ`,options:["(A) (1-b) (2-a) (3-d) (4-e)","(B) (1-d) (2-c) (3-b) (4-e)","(C) (1-c) (2-e) (3-b) (4-d)","(D) (1-d) (2-a) (3-e) (4-c)"],correctIndex:3,explanation:"સાચો વિકલ્પ (D): ભાખરા-નાંગલ -> પંજાબ, હરિયાણા, રાજસ્થાન (d); નર્મદા ખીણ -> મધ્યપ્રદેશ, ગુજરાત, રાજસ્થાન, મહારાષ્ટ્ર (a); તુંગભદ્રા -> કર્ણાટક, આંધ્રપ્રદેશ (e); નાગાર્જુન સાગર -> આંધ્રપ્રદેશ, તેલંગણા (c)."},{id:"ss_q18_17",questionText:`17) દેશના કેટલાક ભાગોમાં પાણીની ગુણવત્તા ઘટી રહી છે, તેનાથી જળજન્ય અનેક રોગો પેદા થાય છે – તો નીચે દર્શાવેલ વિસ્તારોમાંથી કયા હોઈ શકે?
(1) પશ્ચિમી રાજસ્થાનનાં શુષ્ક ક્ષેત્રો
(2) અસમ અને દાર્જિલિંગ
(3) હિમાચલ પ્રદેશ અને અરુણાચલ પ્રદેશ
(4) દ્વીપકલ્પીય ઉચ્ચપ્રદેશના આંતરિક ભાગો`,options:["(A) 2 અને 3","(B) 1 અને 4","(C) 3 અને 1","(D) 2, 3 અને 4"],correctIndex:1,explanation:"સાચો વિકલ્પ (B) 1 અને 4: પશ્ચિમી રાજસ્થાનનાં શુષ્ક ક્ષેત્રો અને દ્વીપકલ્પીય ઉચ્ચપ્રદેશના આંતરિક ભાગોમાં જળની અછત અને ગુણવત્તા ઘટવાથી જળજન્ય રોગોની સમસ્યા જોવા મળે છે."},{id:"ss_q18_18",questionText:"18) 'સ્ટેચ્યૂ ઑફ યુનિટી' સ્મારકની પાસેથી કઈ નદી વહે છે?",options:["(A) નર્મદા","(B) તાપી","(C) મહી","(D) દમણગંગા"],correctIndex:0,explanation:"સાચો વિકલ્પ (A) નર્મદા: એકતા નગર (કેવડિયા) ખાતે આવેલા 'સ્ટેચ્યૂ ઑફ યુનિટી' સ્મારકની પાસેથી નર્મદા નદી વહે છે."}]},C={id:"social_q19",subjectId:"social_science",chapterNumber:"પ્રશ્ન 19",title:"આર્થિક વિકાસ અને અર્થતંત્ર (વિકલ્પો)",subtitle:"વિભાગ A • 15 બહુવિકલ્પ પ્રશ્નો",questionTypeLabel:"વિકલ્પો (M.C.Q.)",questions:[{id:"ss_q19_01",questionText:"1) આર્થિક રીતે ભારત કેવો દેશ છે? — (ફેબ્રુઆરી-માર્ચ 2026)",options:["(A) પછાત","(B) વિકસિત","(C) વિકાસશીલ","(D) ગરીબ"],correctIndex:2,explanation:"સાચો વિકલ્પ (C) વિકાસશીલ: ભારત ઝડપથી આર્થિક પ્રગતિ કરી રહેલો વિકાસશીલ દેશ છે."},{id:"ss_q19_02",questionText:"2) પશુપાલન વ્યવસાયનો સમાવેશ અર્થતંત્રના કયા વિભાગમાં કરવામાં આવે છે? — (માર્ચ 2024)",options:["(A) પ્રાથમિક","(B) માધ્યમિક","(C) સેવા ક્ષેત્ર","(D) ત્રણેયમાંથી એક પણ નહીં"],correctIndex:0,explanation:"સાચો વિકલ્પ (A) પ્રાથમિક: ખેતી, પશુપાલન, મત્સ્ય ઉદ્યોગ અને વનોનો સમાવેશ અર્થતંત્રના પ્રાથમિક ક્ષેત્રમાં થાય છે."},{id:"ss_q19_03",questionText:"3) સેવા ક્ષેત્રમાં કઈ સેવાનો સમાવેશ થાય છે? (માર્ચ 2024)",options:["(A) વન સંવર્ધન","(B) શિક્ષણ","(C) ખનન","(D) ડેરી ઉદ્યોગ"],correctIndex:1,explanation:"સાચો વિકલ્પ (B) શિક્ષણ: શિક્ષણ, આરોગ્ય, બેંકિંગ, વીમો અને પરિવહન જેવી સેવાઓનો સમાવેશ સેવા ક્ષેત્રમાં થાય છે."},{id:"ss_q19_04",questionText:"4) વિશ્વ બેંકના 2004 ના અહેવાલ મુજબ કેટલા ડૉલરથી ઓછી માથાદીઠ આવક ધરાવતા દેશોને વિકાસશીલ દેશ કહેવાય? — (નમૂના પ્રશ્નપત્ર 2024-25)",options:["(A) 450 $","(B) 735 $","(C) 250 $","(D) 500 $"],correctIndex:1,explanation:"સાચો વિકલ્પ (B) 735 $: વિશ્વ બેંકના 2004 ના અહેવાલ મુજબ 735 ડૉલરથી ઓછી માથાદીઠ આવક ધરાવતા દેશો વિકાસશીલ કહેવાય છે."},{id:"ss_q19_05",questionText:"5) વિકાસશીલ દેશોની મુખ્ય આર્થિક પ્રવૃત્તિ કઈ હોય છે?",options:["(A) ઉદ્યોગ","(B) સેવા","(C) ખેતી","(D) વેપાર"],correctIndex:2,explanation:"સાચો વિકલ્પ (C) ખેતી: વિકાસશીલ અર્થતંત્રોમાં મોટાભાગની વસ્તી રોજગારી અને આવક માટે ખેતી પર નિર્ભર હોય છે."},{id:"ss_q19_06",questionText:"6) ઉત્પાદનનું કુદરતી સાધન કયું છે?",options:["(A) શ્રમ","(B) મૂડી","(C) જમીન","(D) નિયોજન"],correctIndex:2,explanation:"સાચો વિકલ્પ (C) જમીન: જમીન એ ઉત્પાદનનું કુદરતી સાધન છે (જ્યારે શ્રમ અને નિયોજન માનવીય તથા મૂડી માનવસર્જિત સાધન છે)."},{id:"ss_q19_07",questionText:"7) ઉત્પાદનનું માનવસર્જિત સાધન કયું છે?",options:["(A) જમીન","(B) શ્રમ","(C) નિયોજક","(D) મૂડી"],correctIndex:3,explanation:"સાચો વિકલ્પ (D) મૂડી: યંત્રો, ઓજારો, મકાન વગેરે જેવા ઉત્પાદનમાં મદદરૂપ સાધનો 'મૂડી' કહેવાય છે અને તે માનવસર્જિત છે."},{id:"ss_q19_08",questionText:"8) કારખાનામાં કામ કરતો મજૂર એ ઉત્પાદનનું કયું સાધન કહેવાય?",options:["(A) મૂડી","(B) શ્રમ","(C) નિયોજક","(D) જમીન"],correctIndex:1,explanation:"સાચો વિકલ્પ (B) શ્રમ: ભૌતિક વળતરની અપેક્ષાએ કરવામાં આવતું કોઈપણ શારીરિક કે માનસિક કાર્ય 'શ્રમ' કહેવાય છે."},{id:"ss_q19_09",questionText:"9) ઉત્પાદનના સાધનોની ફાળવણીની બજાર પદ્ધતિને અન્ય કયા નામે ઓળખવામાં આવે છે?",options:["(A) સામ્યવાદી પદ્ધતિ","(B) સમાજવાદી પદ્ધતિ","(C) મૂડીવાદી પદ્ધતિ","(D) મિશ્ર અર્થતંત્ર"],correctIndex:2,explanation:"સાચો વિકલ્પ (C) મૂડીવાદી પદ્ધતિ: બજાર પદ્ધતિમાં ઉત્પાદનના સાધનોની માલિકી ખાનગી હોય છે તેથી તેને મૂડીવાદી પદ્ધતિ પણ કહે છે."},{id:"ss_q19_10",questionText:"10) બજાર પદ્ધતિમાં આર્થિક નિર્ણયોના કેન્દ્રસ્થાને શું હોય છે?",options:["(A) સમાજકલ્યાણ","(B) નફો","(C) સેવા","(D) ભાવ નિયંત્રણ"],correctIndex:1,explanation:"સાચો વિકલ્પ (B) નફો: બજાર (મૂડીવાદી) પદ્ધતિમાં તમામ આર્થિક નિર્ણયોના કેન્દ્રસ્થાને નફો હોય છે."},{id:"ss_q19_11",questionText:"11) કઈ આર્થિક પદ્ધતિમાં ઉત્પાદનના તમામ સાધનોની માલિકી રાજ્યની હોય છે?",options:["(A) સમાજવાદી પદ્ધતિ","(B) બજાર પદ્ધતિ","(C) મૂડીવાદી પદ્ધતિ","(D) લોકશાહી પદ્ધતિ"],correctIndex:0,explanation:"સાચો વિકલ્પ (A) સમાજવાદી પદ્ધતિ: સમાજવાદી પદ્ધતિમાં ઉત્પાદનના તમામ સાધનોની માલિકી રાજ્યની (સરકારની) હોય છે."},{id:"ss_q19_12",questionText:"12) ભારતમાં કઈ આર્થિક પદ્ધતિ અમલમાં છે?",options:["(A) સમાજવાદી પદ્ધતિ","(B) મૂડીવાદી પદ્ધતિ","(C) મુક્ત બજાર પદ્ધતિ","(D) મિશ્ર અર્થતંત્ર"],correctIndex:3,explanation:"સાચો વિકલ્પ (D) મિશ્ર અર્થતંત્ર: ભારતમાં જાહેર અને ખાનગી ક્ષેત્રના સહ-અસ્તિત્વવાળું મિશ્ર અર્થતંત્ર અમલમાં છે."},{id:"ss_q19_13",questionText:"13) કઈ આર્થિક પદ્ધતિને મુક્ત અર્થતંત્ર તરીકે પણ ઓળખવામાં આવે છે?",options:["(A) બજાર પદ્ધતિ","(B) સમાજવાદી પદ્ધતિ","(C) મિશ્ર અર્થતંત્ર","(D) પરંપરાગત પદ્ધતિ"],correctIndex:0,explanation:"સાચો વિકલ્પ (A) બજાર પદ્ધતિ: સરકારના હસ્તક્ષેપ વગર બજાર પરિબળોથી ચાલતી હોવાથી બજાર પદ્ધતિને મુક્ત અર્થતંત્ર કહે છે."},{id:"ss_q19_14",questionText:"14) ઉત્પાદનના ત્રણેય સાધનોનું યોગ્ય સંયોજન કરનારને શું કહે છે?",options:["(A) શ્રમિક","(B) જમીનદાર","(C) નિયોજક","(D) મૂડીપતિ"],correctIndex:2,explanation:"સાચો વિકલ્પ (C) નિયોજક: જમીન, મૂડી અને શ્રમ એ ત્રણેય સાધનોનું નફાના હેતુથી કુશળતાપૂર્વક સંયોજન કરનારને નિયોજક કહે છે."},{id:"ss_q19_15",questionText:"15) અર્થતંત્રના માધ્યમિક ક્ષેત્રમાં નીચેનામાંથી કોનો સમાવેશ થાય છે?",options:["(A) ખેતી","(B) મત્સ્ય ઉદ્યોગ","(C) નાના-મોટા ઉદ્યોગો","(D) બેંકિંગ વ્યવહાર"],correctIndex:2,explanation:"સાચો વિકલ્પ (C) નાના-મોટા ઉદ્યોગો: ઉત્પાદન અને બાંધકામને લગતા નાના-મોટા ઉદ્યોગોનો સમાવેશ માધ્યમિક ક્ષેત્રમાં થાય છે."}]},A={id:"social_q20",subjectId:"social_science",chapterNumber:"પ્રશ્ન 20",title:"પરિવહન, સંદેશાવ્યવહાર અને વ્યાપાર (વિકલ્પો)",subtitle:"વિભાગ A • 15 બહુવિકલ્પ પ્રશ્નો",questionTypeLabel:"વિકલ્પો (M.C.Q.)",questions:[{id:"ss_q20_01",questionText:"1) રાષ્ટ્રીય ધોરીમાર્ગ નંબર 44 ક્યાંથી ક્યાં સુધીનો છે? — (ફેબ્રુઆરી-માર્ચ 2026)",options:["(A) દિલ્હીથી અમૃતસર","(B) વારાણસીથી કન્યાકુમારી","(C) શ્રીનગરથી કન્યાકુમારી","(D) અમદાવાદથી વડોદરા"],correctIndex:2,explanation:"સાચો વિકલ્પ (C) શ્રીનગરથી કન્યાકુમારી: NH-44 જમ્મુ-કાશ્મીરના શ્રીનગરથી તમિલનાડુના કન્યાકુમારી સુધીનો ભારતનો સૌથી લાંબો ધોરીમાર્ગ છે."},{id:"ss_q20_02",questionText:"2) ભારતનો સૌથી લાંબો રાષ્ટ્રીય ધોરીમાર્ગ કયો છે? — (ફેબ્રુઆરી-માર્ચ 2025)",options:["(A) રાષ્ટ્રીય ધોરીમાર્ગ નંબર 7","(B) રાષ્ટ્રીય ધોરીમાર્ગ નંબર 44","(C) રાષ્ટ્રીય ધોરીમાર્ગ નંબર 27","(D) રાષ્ટ્રીય ધોરીમાર્ગ નંબર 48"],correctIndex:1,explanation:"સાચો વિકલ્પ (B) રાષ્ટ્રીય ધોરીમાર્ગ નંબર 44: શ્રીનગરથી કન્યાકુમારીને જોડતો NH-44 ભારતનો સૌથી લાંબો રાષ્ટ્રીય ધોરીમાર્ગ છે."},{id:"ss_q20_03",questionText:"3) નીચેનામાંથી કયું બંદર ગુજરાતમાં આવેલું નથી? — (માર્ચ 2025)",options:["(A) કંડલા","(B) પોરબંદર","(C) મુંબઈ","(D) ભાવનગર"],correctIndex:2,explanation:"સાચો વિકલ્પ (C) મુંબઈ: મુંબઈ બંદર મહારાષ્ટ્રમાં આવેલું છે, જ્યારે કંડલા, પોરબંદર અને ભાવનગર ગુજરાતનાં બંદરો છે."},{id:"ss_q20_04",questionText:"4) ભારતમાં સૌપ્રથમ રેલવેની શરૂઆત ક્યારે થઈ હતી? — (નમૂના પ્રશ્નપત્ર 2024-25)",options:["(A) ઈ.સ. 1853 માં","(B) ઈ.સ. 1857 માં","(C) ઈ.સ. 1947 માં","(D) ઈ.સ. 1905 માં"],correctIndex:0,explanation:"સાચો વિકલ્પ (A) ઈ.સ. 1853 માં: ભારતમાં પ્રથમ રેલવેની શરૂઆત 16 એપ્રિલ 1853 ના રોજ મુંબઈ અને થાણે વચ્ચે થઈ હતી."},{id:"ss_q20_05",questionText:"5) ભારતમાં સૌથી લાંબો રેલમાર્ગ કયો છે?",options:["(A) મુંબઈથી દિલ્હી","(B) દિબ્રુગઢથી કન્યાકુમારી","(C) જમ્મુથી કન્યાકુમારી","(D) અમદાવાદથી ચેન્નઈ"],correctIndex:1,explanation:"સાચો વિકલ્પ (B) દિબ્રુગઢથી કન્યાકુમારી: આસામના દિબ્રુગઢથી કન્યાકુમારીને જોડતો માર્ગ ભારતનો સૌથી લાંબો રેલમાર્ગ છે."},{id:"ss_q20_06",questionText:"6) દિબ્રુગઢથી કન્યાકુમારી વચ્ચે દોડતી ભારતની સૌથી લાંબી ટ્રેન કઈ છે?",options:["(A) રાજધાની એક્સપ્રેસ","(B) વંદે ભારત એક્સપ્રેસ","(C) વિવેક એક્સપ્રેસ","(D) દુરંતો એક્સપ્રેસ"],correctIndex:2,explanation:"સાચો વિકલ્પ (C) વિવેક એક્સપ્રેસ: તે દિબ્રુગઢથી કન્યાકુમારી વચ્ચે દોડતી ભારતની સૌથી લાંબી અંતરની ટ્રેન છે."},{id:"ss_q20_07",questionText:"7) ભારતમાં પ્રથમ રેલવે કયા બે શહેરો વચ્ચે શરૂ થઈ હતી?",options:["(A) મુંબઈ અને થાણે","(B) અમદાવાદ અને સુરત","(C) કોલકાતા અને હાવડા","(D) દિલ્હી અને આગરા"],correctIndex:0,explanation:"સાચો વિકલ્પ (A) મુંબઈ અને થાણે: ઈ.સ. 1853 માં ભારતની પ્રથમ રેલવે મુંબઈથી થાણે વચ્ચે શરૂ થઈ હતી."},{id:"ss_q20_08",questionText:"8) સ્વર્ણિમ ચતુર્ભુજ યોજના કયા પ્રકારના માર્ગો સાથે સંકળાયેલી છે?",options:["(A) રેલમાર્ગ","(B) જળમાર્ગ","(C) રાષ્ટ્રીય ધોરીમાર્ગ","(D) હવાઈ માર્ગ"],correctIndex:2,explanation:"સાચો વિકલ્પ (C) રાષ્ટ્રીય ધોરીમાર્ગ: દિલ્હી, મુંબઈ, ચેન્નઈ અને કોલકાતાને જોડતી સ્વર્ણિમ ચતુર્ભુજ યોજના રાષ્ટ્રીય ધોરીમાર્ગો સાથે સંકળાયેલી છે."},{id:"ss_q20_09",questionText:"9) ઓટોમેટિક લોક ગેટ ધરાવતું ગુજરાતનું એકમાત્ર બંદર કયું છે?",options:["(A) કંડલા","(B) ભાવનગર","(C) બેડી","(D) માંડવી"],correctIndex:1,explanation:"સાચો વિકલ્પ (B) ભાવનગર: ભાવનગર બંદર ઓટોમેટિક લોક ગેટની સુવિધા ધરાવતું ગુજરાતનું એકમાત્ર બંદર છે."},{id:"ss_q20_10",questionText:"10) પર્વતીય વિસ્તારોમાં માલસામાનની હેરફેર માટે કયા પરિવહન માધ્યમનો ઉપયોગ થાય છે?",options:["(A) રજ્જુમાર્ગ (રોપ-વે)","(B) જળમાર્ગ","(C) પાઇપલાઇન","(D) રેલમાર્ગ"],correctIndex:0,explanation:"સાચો વિકલ્પ (A) રજ્જુમાર્ગ (રોપ-વે): દુર્ગમ પર્વતીય વિસ્તારોમાં મુસાફરો અને માલસામાનની હેરફેર માટે રોપ-વેનો ઉપયોગ થાય છે."},{id:"ss_q20_11",questionText:"11) ગુજરાતમાં સૌથી લાંબો રોપ-વે કયા પર્વત પર આવેલો છે?",options:["(A) પાવાગઢ","(B) ગિરનાર","(C) અંબાજી","(D) સાપુતારા"],correctIndex:1,explanation:"સાચો વિકલ્પ (B) ગિરનાર: જૂનાગઢમાં આવેલો ગિરનાર રોપ-વે ગુજરાત અને એશિયાનો સૌથી લાંબો મંદિર રોપ-વે છે."},{id:"ss_q20_12",questionText:"12) ભારતમાં ઉપગ્રહ છોડવા માટે કઈ સંસ્થા કાર્યરત છે?",options:["(A) DRDO","(B) ISRO","(C) BHEL","(D) HAL"],correctIndex:1,explanation:"સાચો વિકલ્પ (B) ISRO: ભારતીય અવકાશ સંશોધન સંસ્થા (ISRO) ઉપગ્રહ નિર્માણ અને પ્રક્ષેપણનું કાર્ય કરે છે."},{id:"ss_q20_13",questionText:"13) ભારતમાં રાષ્ટ્રીય જળમાર્ગ નંબર 1 કઈ નદી પર આવેલો છે?",options:["(A) બ્રહ્મપુત્રા","(B) ગંગા","(C) ગોદાવરી","(D) નર્મદા"],correctIndex:1,explanation:"સાચો વિકલ્પ (B) ગંગા: રાષ્ટ્રીય જળમાર્ગ નં. 1 હલ્દિયાથી અલ્હાબાદ વચ્ચે ગંગા નદી પર આવેલો છે."},{id:"ss_q20_14",questionText:"14) પ્રવાહી અને વાયુ પદાર્થોના પરિવહન માટે સૌથી અનુકૂળ માધ્યમ કયું છે?",options:["(A) સડકમાર્ગ","(B) રેલમાર્ગ","(C) પાઇપલાઇન","(D) હવાઈ માર્ગ"],correctIndex:2,explanation:"સાચો વિકલ્પ (C) પાઇપલાઇન: ખનીજતેલ, કુદરતી વાયુ અને પાણી જેવા પ્રવાહી કે વાયુ પદાર્થોના પરિવહન માટે પાઇપલાઇન શ્રેષ્ઠ માધ્યમ છે."},{id:"ss_q20_15",questionText:"15) કંડલા બંદરને કયા મુક્ત વ્યાપાર ક્ષેત્ર તરીકે જાહેર કરવામાં આવ્યું છે?",options:["(A) મુક્ત વ્યાપાર ક્ષેત્ર","(B) આંતરરાષ્ટ્રીય એરપોર્ટ","(C) સંરક્ષણ મથક","(D) પર્યટન ધામ"],correctIndex:0,explanation:"સાચો વિકલ્પ (A) મુક્ત વ્યાપાર ક્ષેત્ર: કચ્છનું કંડલા (દીનદયાળ) બંદર ભારતનું પ્રથમ મુક્ત વ્યાપાર ક્ષેત્ર (Free Trade Zone) જાહેર કરાયેલું બંદર છે."}]},B={id:"social_q21",subjectId:"social_science",chapterNumber:"પ્રશ્ન 21",title:"ભારતનો વારસો (એક વાક્યના પ્રશ્નો)",subtitle:"વિભાગ A • 18 પ્રશ્નો (સંપૂર્ણ જવાબ સહિત)",questionTypeLabel:"એક વાક્યમાં જવાબ",questions:[{id:"ss_q21_01",questionText:"1) કઈ પ્રજા 'કિરાત' તરીકે ઓળખાતી હતી? — (માર્ચ 2026)",options:["મોંગોલોઇડ પ્રજા","દ્રવિડ પ્રજા","નેગ્રિટો પ્રજા","ઓસ્ટ્રેલોઇડ પ્રજા"],correctIndex:0,explanation:"જવાબ: મોંગોલોઇડ પ્રજા પીળા વર્ણની હોવાથી 'કિરાત' તરીકે ઓળખાતી હતી."},{id:"ss_q21_02",questionText:"2) ગુજરાતમાં પતંગોત્સવ અને તાના-રીરી મહોત્સવ ક્યાં ઊજવાય છે? — (માર્ચ 2025)",options:["અમદાવાદ અને વડનગર","સુરત અને પાટણ","વડોદરા અને મોઢેરા","રાજકોટ અને વિજાપુર"],correctIndex:0,explanation:"જવાબ: ગુજરાતમાં પતંગોત્સવ અમદાવાદમાં અને તાના-રીરી મહોત્સવ વડનગરમાં ઊજવાય છે."},{id:"ss_q21_03",questionText:"3) ભારતની રાષ્ટ્રમુદ્રામાં કયાં કયાં પ્રાણીઓ દર્શાવેલાં છે? — (માર્ચ 2025)",options:["ચાર સિંહો, ઘોડો, હાથી અને બળદ","ચાર સિંહો, વાઘ, ગેંડો અને હરણ","ત્રણ સિંહો, ઘોડો, ઊંટ અને મોર","ચાર સિંહો, ચિત્તો, હાથી અને અશ્વ"],correctIndex:0,explanation:"જવાબ: ભારતની રાષ્ટ્રમુદ્રામાં ચાર સિંહો, ઘોડો, હાથી અને બળદ દર્શાવેલાં છે."},{id:"ss_q21_04",questionText:"4) કઈ નદીઓ ભારતીય સંસ્કૃતિના ઘડતરમાં મહત્વનો ભાગ ભજવે છે? — (માર્ચ 2024)",options:["સિંધુ અને રાવી નદીઓ","નર્મદા અને તાપી નદીઓ","ગોદાવરી અને કૃષ્ણા નદીઓ","મહી અને સાબરમતી નદીઓ"],correctIndex:0,explanation:"જવાબ: સિંધુ અને રાવી નદીઓએ ભારતીય સંસ્કૃતિના ઘડતરમાં મહત્વનો ભાગ ભજવ્યો છે."},{id:"ss_q21_05",questionText:"5) નેગ્રિટો (હબસી) પ્રજા ભારતમાં ક્યાંથી આવી હતી? — (નમૂના પ્રશ્નપત્ર 2024-25)",options:["આફ્રિકામાંથી બલુચિસ્તાનના રસ્તે","મધ્ય એશિયામાંથી ખૈબર ઘાટ માર્ગે","ઉત્તર-પશ્ચિમ ચીનમાંથી તિબેટ થઈ","અગ્નિ એશિયામાંથી દરિયાઈ માર્ગે"],correctIndex:0,explanation:"જવાબ: નેગ્રિટો (હબસી) પ્રજા આફ્રિકામાંથી બલુચિસ્તાનના રસ્તે થઈ ભારતમાં આવી હતી."},{id:"ss_q21_06",questionText:"6) સંસ્કૃતિ એટલે શું?",options:["માનવમનનું ખેડાણ અને જીવન જીવવાની રીત","માત્ર ધાર્મિક ઉત્સવોની ઉજવણી","પ્રાચીન ઇમારતોનું બાંધકામ","ફક્ત કુદરતી પર્વતો અને નદીઓ"],correctIndex:0,explanation:"જવાબ: સંસ્કૃતિ એટલે માનવમનનું ખેડાણ અને માનવસમાજની ટેવો, મૂલ્યો, આચાર-વિચાર તથા રહેણીકરણીની સર્વોચ્ચ સ્થિતિ (જીવન જીવવાની રીત)."},{id:"ss_q21_07",questionText:"7) પ્રાકૃતિક વારસો એટલે શું?",options:["પ્રકૃતિ, પર્યાવરણ અને માનવજીવન વચ્ચેના નજીકના સંબંધોનું પરિણામ","માનવીએ પોતાની બુદ્ધિથી બનાવેલા સ્મારકો","રાજાઓએ બંધાવેલા કિલ્લાઓ અને મહેલો","પ્રાચીન ગ્રંથો અને સાહિત્યનો સંગ્રહ"],correctIndex:0,explanation:"જવાબ: પ્રકૃતિ, પર્યાવરણ અને માનવજીવન વચ્ચેના અત્યંત નજીકના સંબંધોનું પરિણામ એટલે પ્રાકૃતિક વારસો."},{id:"ss_q21_08",questionText:"8) સાંસ્કૃતિક વારસો એટલે શું?",options:["માનવીએ બુદ્ધિશક્તિ, આવડત અને કૌશલ્ય દ્વારા જે સર્જ્યું તે (માનવસર્જિત વારસો)","કુદરત તરફથી મળેલા પર્વતો, વનો અને નદીઓ","પૃથ્વીના પેટાળમાં રહેલા ખનીજો","માત્ર વન્ય પ્રાણીઓ અને પક્ષીઓ"],correctIndex:0,explanation:"જવાબ: માનવીએ પોતાની બુદ્ધિશક્તિ, આવડત, કલા અને કૌશલ્ય દ્વારા જે કંઈ મેળવ્યું કે સર્જ્યું તેને સાંસ્કૃતિક વારસો (માનવસર્જિત વારસો) કહેવાય."},{id:"ss_q21_09",questionText:"9) ભારતીય સંસ્કૃતિ કઈ બે નદીઓના કિનારે પાંગરી અને વિકસી હતી?",options:["સિંધુ અને રાવી","ગંગા અને બ્રહ્મપુત્રા","કાવેરી અને મહાનદી","તાપી અને પૂર્ણા"],correctIndex:0,explanation:"જવાબ: ભારતીય સંસ્કૃતિ સિંધુ અને રાવી નદીના કિનારે પાંગરી અને વિકસી હતી."},{id:"ss_q21_10",questionText:"10) નદીઓને લોકમાતાનું સ્થાન શા માટે આપવામાં આવ્યું છે?",options:["પીવાનું પાણી, સિંચાઈ અને રોજિંદી જરૂરિયાતો પૂરી પાડી જીવન સમૃદ્ધ બનાવ્યું હોવાથી","નદીઓમાં મોટા જહાજો ચાલતા હોવાથી","નદીઓ માત્ર પર્વતોમાંથી નીકળતી હોવાથી","નદીઓમાં ખનીજો મળતા હોવાથી"],correctIndex:0,explanation:"જવાબ: નદીઓએ માનવજીવનને સમૃદ્ધ બનાવ્યું છે, પીવાનું પાણી, સિંચાઈ અને રોજિંદી જરૂરિયાતો પૂરી પાડી હોવાથી તેમને લોકમાતાનું બિરુદ આપવામાં આવ્યું છે."},{id:"ss_q21_11",questionText:"11) ગુજરાતમાં જૈન અને બૌદ્ધ ગુફાઓ ક્યાં ક્યાં આવેલી છે?",options:["વડનગર, તારંગા, ખંભાલીડા, જૂનાગઢ, શામળાજી, કોટેશ્વર, તળાજા, ઢાંક અને ઝઘડિયા","માત્ર પાવાગઢ અને સાપુતારા ખાતે","ફક્ત કચ્છના ભુજ અને માંડવી ખાતે","સુરત અને ભરૂચના દરિયાકિનારે"],correctIndex:0,explanation:"જવાબ: ગુજરાતમાં વડનગર, તારંગા, ખંભાલીડા, જૂનાગઢ, શામળાજી, કોટેશ્વર, તળાજા, ઢાંક અને ઝઘડિયા ખાતે જૈન અને બૌદ્ધ ગુફાઓ આવેલી છે."},{id:"ss_q21_12",questionText:"12) ઓસ્ટ્રેલોઇડ (નિષાદ) પ્રજાની શારીરિક વિશેષતાઓ જણાવો.",options:["શ્યામ રંગ, લાંબું-પહોળું માથું, ચપટું નાક અને ટૂંકું કદ","પીળો વર્ણ, બદામ આકારની આંખો અને ઉપસેલા ગાલ","ગૌર વર્ણ, ઊંચું કદ અને વાંકડિયા વાળ","ધોળો વર્ણ અને ગોળ માથું"],correctIndex:0,explanation:"જવાબ: શ્યામ રંગ, લાંબું અને પહોળું માથું, ચપટું નાક અને ટૂંકું કદ એ ઓસ્ટ્રેલોઇડ (નિષાદ) પ્રજાની શારીરિક વિશેષતાઓ હતી."},{id:"ss_q21_13",questionText:"13) આર્યો અન્ય કયા નામે ઓળખાતા હતા?",options:["નોર્ડિક","કિરાત","નિષાદ","હબસી"],correctIndex:0,explanation:"જવાબ: ભારતની આર્ય સભ્યતાના નિર્માતા આર્યો 'નોર્ડિક' તરીકે પણ ઓળખાતા હતા."},{id:"ss_q21_14",questionText:"14) દ્રવિડ ભાષાકુળની સૌથી પ્રાચીન ભાષા કઈ છે?",options:["તમિલ","તેલુગુ","કન્નડ","મલયાલમ"],correctIndex:0,explanation:"જવાબ: તમિલ એ દ્રવિડ ભાષાકુળની સૌથી પ્રાચીન ભાષા છે."},{id:"ss_q21_15",questionText:"15) માતૃમૂલક કુટુંબપ્રથા કઈ પ્રજામાં પ્રચલિત હતી?",options:["દ્રવિડ પ્રજામાં","આર્ય પ્રજામાં","મોંગોલોઇડ પ્રજામાં","નેગ્રિટો પ્રજામાં"],correctIndex:0,explanation:"જવાબ: માતૃમૂલક કુટુંબપ્રથા મૂળ દ્રવિડ પ્રજામાં પ્રચલિત હતી."},{id:"ss_q21_16",questionText:"16) ભારતીય બંધારણની કઈ કલમમાં નાગરિકની મૂળભૂત ફરજો દર્શાવેલી છે?",options:["કલમ 51 (ક)","કલમ 17","કલમ 341","કલમ 370"],correctIndex:0,explanation:"જવાબ: ભારતીય બંધારણની કલમ 51 (ક) માં નાગરિકની મૂળભૂત ફરજો દર્શાવેલી છે."},{id:"ss_q21_17",questionText:"17) બંધારણની કલમ 51 (ક) ના કયા પેટા નિયમોમાં ભારતના ભવ્ય સાંસ્કૃતિક વારસાના જતનની ફરજો સમાવિષ્ટ છે?",options:["(છ), (જ) અને (ટ) — એટલે કે (6), (7) અને (9)","(ક), (ખ) અને (ગ) — એટલે કે (1), (2) અને (3)","(ઘ) અને (ચ) — એટલે કે (4) અને (5)","માત્ર (ઢ) — એટલે કે (11)"],correctIndex:0,explanation:"જવાબ: બંધારણની કલમ 51 (ક) ના (છ), (જ) અને (ટ) એટલે કે (6), (7) અને (9) માં વારસાના જતનની ફરજો દર્શાવેલી છે."},{id:"ss_q21_18",questionText:"18) ગુજરાતમાં રણ મહોત્સવ ક્યાં યોજાય છે?",options:["કચ્છના ધોરડો ખાતે","જામનગર ખાતે","ભાવનગર ખાતે","વડનગર ખાતે"],correctIndex:0,explanation:"જવાબ: ગુજરાતમાં રણ મહોત્સવ કચ્છના ધોરડો ખાતે યોજાય છે."}]},D={id:"social_q22",subjectId:"social_science",chapterNumber:"પ્રશ્ન 22",title:"ભારતનો સાંસ્કૃતિક વારસો : શિલ્પ અને સ્થાપત્ય",subtitle:"વિભાગ A • 25 એક વાક્યના પ્રશ્નો (જવાબ સહિત)",questionTypeLabel:"એક વાક્યમાં જવાબ",questions:[{id:"ss_q22_01",questionText:"1) સ્તૂપ એટલે શું? — (માર્ચ 2026)",options:["ભગવાન બુદ્ધના અવશેષોને દાબડામાં મૂકી તેના પર રચાતો અર્ધગોળાકાર ઘુમ્મટ આકારનું સ્થાપત્ય","જૈન સાધુઓના નિવાસ માટેની ઊંચી ઇમારત","રાજાઓના વિજયની યાદમાં બનેલો લોહસ્તંભ","નદી કિનારે બનાવેલો પગથિયાંવાળો કૂવો"],correctIndex:0,explanation:"જવાબ: ભગવાન બુદ્ધના વાળ, દાંત, અસ્થિ કે રાખ જેવા શારીરિક અવશેષોને દાબડામાં મૂકી તેના પર રચાતા અર્ધગોળાકાર ઘુમ્મટ આકારના ઈંટો કે પથ્થરના સ્થાપત્યને સ્તૂપ કહે છે."},{id:"ss_q22_02",questionText:"2) ગુજરાતમાં ત્રણ દરવાજા ક્યાં આવેલા છે? — (માર્ચ 2024)",options:["અમદાવાદમાં ભદ્રના કિલ્લાની સામે","પાટણમાં સહસ્ત્રલિંગ તળાવ પાસે","વડોદરામાં લક્ષ્મી વિલાસ પેલેસ પાસે","જૂનાગઢમાં ઉપરકોટ કિલ્લા પાસે"],correctIndex:0,explanation:"જવાબ: ગુજરાતમાં ત્રણ દરવાજા અમદાવાદમાં ભદ્રના કિલ્લાની સામે આવેલા છે."},{id:"ss_q22_03",questionText:"3) મોહેં-જો-દડોનો અર્થ શું થાય છે? — (નમૂના પ્રશ્નપત્ર 2024-25)",options:["મરેલાંનો ટેકરો","જીવંત નગર","પવિત્ર ધામ","સમૃદ્ધ બંદર"],correctIndex:0,explanation:"જવાબ: સિંધી ભાષામાં મોહેં-જો-દડોનો અર્થ 'મરેલાંનો ટેકરો' એવો થાય છે."},{id:"ss_q22_04",questionText:"4) શિલ્પકલા એટલે શું?",options:["શિલ્પી પોતાના મનના ભાવો છીણી અને હથોડી વડે પથ્થર, લાકડું કે ધાતુ પર કંડારે તે કલા","કાપડ પર દોરા વડે થતું ભરતકામ","ઇમારતો અને પુલોનું બાંધકામ કરવાનું શાસ્ત્ર","કાગળ પર રંગો વડે ચિત્રો દોરવાની કલા"],correctIndex:0,explanation:"જવાબ: શિલ્પી પોતાના મનના ભાવો છીણી અને હથોડી વડે પથ્થર, લાકડું કે ધાતુ પર કંડારે તેને શિલ્પકલા કહે છે."},{id:"ss_q22_05",questionText:"5) સ્થાપત્યનો સામાન્ય અર્થ શું થાય છે?",options:["બાંધકામ ('વાસ્તુ')","ચિત્રકામ","કોતરકામ","વણાટકામ"],correctIndex:0,explanation:"જવાબ: સ્થાપત્યનો સામાન્ય અર્થ 'બાંધકામ' એવો થાય છે અને સંસ્કૃત ભાષામાં સ્થાપત્ય માટે 'વાસ્તુ' શબ્દ વપરાય છે."},{id:"ss_q22_06",questionText:"6) હડપ્પા નગરની શોધ કોણે અને ક્યારે કરી હતી?",options:["દયારામ સહાનીએ ઈ.સ. 1921 માં","રખાલદાસ બેનર્જીએ ઈ.સ. 1922 માં","એસ. આર. રાવે ઈ.સ. 1954 માં","આર. એસ. બિષ્ટે ઈ.સ. 1990 માં"],correctIndex:0,explanation:"જવાબ: ઈ.સ. 1921 માં સર જ્હોન માર્શલ અને કર્નલ મેકેના માર્ગદર્શન હેઠળ દયારામ સહાનીએ હડપ્પા નગરની શોધ કરી હતી."},{id:"ss_q22_07",questionText:"7) હડપ્પીય સંસ્કૃતિનું (સિંધુખીણની સભ્યતાનું) હેડક્વાર્ટર (મુખ્ય મથક) કયું નગર ગણાતું હતું?",options:["હડપ્પા","લોથલ","ધોળાવીરા","કાલીબંગાન"],correctIndex:0,explanation:"જવાબ: હડપ્પા નગર સિંધુખીણની સંસ્કૃતિનું મુખ્ય વહીવટી કેન્દ્ર કે હેડક્વાર્ટર ગણાતું હતું."},{id:"ss_q22_08",questionText:"8) સિંધુખીણની સંસ્કૃતિના કયા નગરમાંથી વિશાળ જાહેર સ્નાનાગાર અને અન્નભંડારો મળી આવ્યા છે?",options:["મોહેં-જો-દડો","લોથલ","રંગપુર","ધોળાવીરા"],correctIndex:0,explanation:"જવાબ: મોહેં-જો-દડો નગરમાંથી વિશાળ જાહેર સ્નાનાગાર અને અન્નભંડારો મળી આવ્યા છે."},{id:"ss_q22_09",questionText:"9) લોથલ ક્યાં આવેલું છે અને તે પ્રાચીન સમયમાં શું હતું?",options:["અમદાવાદ જિલ્લાના ધોળકા તાલુકામાં ભોગાવો-સાબરમતી નદી વચ્ચે; ધમધમતું બંદર અને ઔદ્યોગિક નગર","કચ્છના ભચાઉ તાલુકામાં; ત્રિસ્તરીય કિલ્લો","રાજકોટના ગોંડલ તાલુકામાં; ખેતીવાડી કેન્દ્ર","સુરેન્દ્રનગરના લીંબડી તાલુકામાં; માટીકામ કેન્દ્ર"],correctIndex:0,explanation:"જવાબ: લોથલ અમદાવાદ જિલ્લાના ધોળકા તાલુકામાં ભોગાવો અને સાબરમતી નદી વચ્ચે આવેલું છે, જે પ્રાચીન સમયનું ધમધમતું બંદર અને ઔદ્યોગિક નગર હતું."},{id:"ss_q22_10",questionText:"10) લોથલમાંથી વહાણો લાંગરવા માટે શું મળી આવ્યું છે?",options:["મોટો ધક્કો (ડૉકયાર્ડ) અને વખારો","મોહેં-જો-દડો જેવું જાહેર સ્નાનાગાર","દસ અક્ષરોનું સાઈનબોર્ડ","ભવ્ય રાજમહેલ"],correctIndex:0,explanation:"જવાબ: લોથલમાંથી વહાણ લાંગરવા માટેનો મોટો ધક્કો (ડૉકયાર્ડ) અને વખારો મળી આવ્યા છે."},{id:"ss_q22_11",questionText:"11) ધોળાવીરા નગર ક્યાં આવેલું છે અને તેની વિશેષતા શું છે?",options:["કચ્છના ભચાઉ તાલુકાના ખદીરબેટમાં; ત્રિસ્તરીય નગરરચના અને વરસાદી પાણીના સંગ્રહની પદ્ધતિ","અમદાવાદના ધોળકા તાલુકામાં; વહાણ લાંગરવાનો ધક્કો","મહેસાણા જિલ્લામાં; સૂર્યમંદિર","જૂનાગઢ જિલ્લામાં; અશોકનો શિલાલેખ"],correctIndex:0,explanation:"જવાબ: ધોળાવીરા કચ્છના ભચાઉ તાલુકાના ખદીરબેટમાં આવેલું છે, જે તેની ત્રિસ્તરીય નગરરચના અને ઉત્તમ વરસાદી પાણીના સંગ્રહની પદ્ધતિ માટે જાણીતું છે."},{id:"ss_q22_12",questionText:"12) સ્તૂપના અંડાકાર ભાગની ટોચ પર આવેલી રેલિંગ (વાડ) ને શું કહે છે?",options:["હર્મિકા","મેધિ","તોરણ","પ્રદક્ષિણાપથ"],correctIndex:0,explanation:"જવાબ: સ્તૂપના અંડાકાર ભાગની ટોચ પર આવેલી વાડ જેવી રચનાને 'હર્મિકા' કહે છે."},{id:"ss_q22_13",questionText:"13) સ્તૂપની ચારે બાજુ રચેલા પ્રદક્ષિણા કરવાના રસ્તાને શું કહે છે?",options:["મેધિ અને પ્રદક્ષિણાપથ","હર્મિકા અને તોરણ","ગોપુરમ્ અને ગર્ભગૃહ","સ્તંભ અને વિહાર"],correctIndex:0,explanation:"જવાબ: સ્તૂપની ચારે બાજુ ઊંચા રચેલા ગોળાકાર રસ્તાને 'મેધિ' અને ભૂમિ પરની પ્રદક્ષિણા માટેના માર્ગને 'પ્રદક્ષિણાપથ' કહે છે."},{id:"ss_q22_14",questionText:"14) સ્તૂપની આગળ ઊભા કરેલા સુશોભિત કલાત્મક પ્રવેશદ્વારને શું કહેવામાં આવે છે?",options:["તોરણ","હર્મિકા","મેધિ","ગુંબજ"],correctIndex:0,explanation:"જવાબ: સ્તૂપના કલાત્મક પ્રવેશદ્વારને 'તોરણ' કહેવામાં આવે છે."},{id:"ss_q22_15",questionText:"15) મૌર્યયુગના સ્થાપત્યમાં કયા સમ્રાટના સ્તૂપો અને શિલાલેખો વિશ્વવિખ્યાત છે?",options:["સમ્રાટ અશોક","ચંદ્રગુપ્ત મૌર્ય","બિંદુસાર","સમુદ્રગુપ્ત"],correctIndex:0,explanation:"જવાબ: મૌર્યયુગમાં સમ્રાટ અશોકના શિલાલેખો, સ્તંભલેખો અને સાંચીનો સ્તૂપ વિશ્વવિખ્યાત છે."},{id:"ss_q22_16",questionText:"16) ભારતની રાષ્ટ્રમુદ્રા કયા શિલ્પમાંથી સ્વીકારવામાં આવી છે?",options:["સારનાથના સ્તંભ પરના ચાર સિંહોના શિલ્પમાંથી","સાંચીના સ્તૂપના તોરણમાંથી","જૂનાગઢના અશોક શિલાલેખમાંથી","એલિફન્ટાની ત્રિમૂર્તિ શિલ્પમાંથી"],correctIndex:0,explanation:"જવાબ: સમ્રાટ અશોકના સારનાથના સ્તંભ પરના ચાર પરસ્પર પીઠ જોડીને ઊભેલા સિંહોના શિલ્પમાંથી ભારતની રાષ્ટ્રમુદ્રા સ્વીકારવામાં આવી છે."},{id:"ss_q22_17",questionText:"17) ગુજરાતમાં સમ્રાટ અશોકનો શિલાલેખ ક્યાં આવેલો છે?",options:["જૂનાગઢમાં ગિરનાર પર્વત તરફ જતાં દામોદર કુંડ નજીક","પાવાગઢ પર્વતની તળેટીમાં","વડનગરના કીર્તિતોરણ પાસે","મોઢેરાના સૂર્યકુંડ પાસે"],correctIndex:0,explanation:"જવાબ: ગુજરાતમાં જૂનાગઢમાં ગિરનાર પર્વત તરફ જતાં દામોદર કુંડ નજીક સમ્રાટ અશોકનો શિલાલેખ આવેલો છે."},{id:"ss_q22_18",questionText:"18) ગુજરાતમાં કઈ કઈ ગુફાઓ આવેલી છે?",options:["જૂનાગઢ (ખાપરા-કોડિયા, બાવાપ્યારા, ઉપરકોટ), ખંભાલીડા, તળાજા, સાણા, ઢાંક અને ઝીંઝુરીઝરની ગુફાઓ","અજંતા, ઇલોરા અને એલિફન્ટાની ગુફાઓ","ઉદયગિરિ અને ખંડગિરિની ગુફાઓ","ભીમબેટકા અને બાઘની ગુફાઓ"],correctIndex:0,explanation:"જવાબ: જૂનાગઢની ગુફાઓ (ખાપરા-કોડિયા, બાવાપ્યારા, ઉપરકોટ), ખંભાલીડા ગુફાઓ, તળાજા ગુફાઓ, સાણા ગુફાઓ, ઢાંક ગુફાઓ અને ઝીંઝુરીઝરની ગુફાઓ ગુજરાતમાં આવેલી છે."},{id:"ss_q22_19",questionText:"19) મોઢેરાના સૂર્યમંદિરનું નિર્માણ કોના શાસનકાળમાં થયું હતું?",options:["સોલંકી વંશના રાજા ભીમદેવ પ્રથમના શાસનકાળમાં (ઈ.સ. 1026)","સિદ્ધરાજ જયસિંહના શાસનકાળમાં","કુમારપાળના શાસનકાળમાં","મૂળરાજ સોલંકીના શાસનકાળમાં"],correctIndex:0,explanation:"જવાબ: મોઢેરાના સૂર્યમંદિરનું નિર્માણ સોલંકી વંશના રાજા ભીમદેવ પ્રથમના શાસનકાળમાં (ઈ.સ. 1026 માં) થયું હતું."},{id:"ss_q22_20",questionText:"20) મોઢેરાના સૂર્યમંદિરની બાહ્ય નકશી કઈ શૈલીમાં થયેલી છે?",options:["ઈરાની શૈલીમાં","દ્રવિડ શૈલીમાં","ગાંધાર શૈલીમાં","વૈસર શૈલીમાં"],correctIndex:0,explanation:"જવાબ: મોઢેરાના સૂર્યમંદિરનું બાહ્ય નકશીકામ ઈરાની શૈલીમાં થયેલું છે."},{id:"ss_q22_21",questionText:"21) દક્ષિણ ભારતમાં ચોલ વંશ દરમિયાન કયું ભવ્ય મંદિર બંધાયું હતું?",options:["તાંજોર (થંજાવુર) ખાતે બૃહદેશ્વર મંદિર (રાજરાજ પ્રથમ દ્વારા)","પુરી ખાતે જગન્નાથ મંદિર","મધ્યપ્રદેશમાં ખજૂરાહો મંદિર","ગુજરાતમાં રુદ્રમહાલય"],correctIndex:0,explanation:"જવાબ: તામિલનાડુના તાંજોર (થંજાવુર) ખાતે રાજરાજ પ્રથમ દ્વારા નિર્મિત બૃહદેશ્વર મંદિર બંધાયું હતું."},{id:"ss_q22_22",questionText:"22) દક્ષિણ ભારતના મંદિરોના ભવ્ય કલાત્મક પ્રવેશદ્વારને શું કહે છે?",options:["ગોપુરમ્","તોરણ","શિખર","મંડપ"],correctIndex:0,explanation:"જવાબ: દક્ષિણ ભારતના મંદિરોના ભવ્ય અને ઊંચા પ્રવેશદ્વારને 'ગોપુરમ્' કહે છે."},{id:"ss_q22_23",questionText:"23) અમદાવાદમાં આવેલી કઈ મસ્જિદ તેના બારીક પથ્થરના જાળીકામ માટે વિશ્વભરમાં પ્રસિદ્ધ છે?",options:["સીદી સૈયદની મસ્જિદ (સીદી સૈયદની જાળી)","જામા મસ્જિદ","રાણી સિપ્રીની મસ્જિદ","ઝુમ્મા મસ્જિદ"],correctIndex:0,explanation:"જવાબ: સીદી સૈયદની મસ્જિદ (સીદી સૈયદની જાળી) તેના અત્યંત બારીક વનસ્પતિક અને ભૌમિતિક નકશીકામ માટે વિશ્વભરમાં પ્રસિદ્ધ છે."},{id:"ss_q22_24",questionText:"24) અમદાવાદમાં એકબીજાને અડક્યા વગર પણ કંપન અનુભવતા કયા મીનારા આવેલા છે?",options:["ઝૂલતા મીનારા (રાજપુર-ગોમતીપુર, સીદી બશીરની મસ્જિદ)","કુતુબમિનાર","ચાંદ મીનાર","ચાર મિનાર"],correctIndex:0,explanation:"જવાબ: અમદાવાદમાં રાજપુર-ગોમતીપુરમાં આવેલા ઝૂલતા મીનારા (સીદી બશીરની મસ્જિદ) જાણીતા છે."},{id:"ss_q22_25",questionText:"25) રાણકી વાવ ગુજરાતના કયા શહેરમાં આવેલી છે અને તેનું નિર્માણ કોણે કરાવ્યું હતું?",options:["પાટણમાં; રાણી ઉદયમતીએ","અમદાવાદમાં; રાણી રૂપમતીએ","વડનગરમાં; મીનળદેવીએ","સિદ્ધપુરમાં; સિદ્ધરાજ જયસિંહે"],correctIndex:0,explanation:"જવાબ: રાણકી વાવ પાટણમાં આવેલી છે અને તેનું નિર્માણ રાણી ઉદયમતીએ પોતાના પતિ ભીમદેવ પ્રથમના મૃત્યુ પછી પ્રજાકલ્યાણ માટે કરાવ્યું હતું."}]},b={id:"social_q23_24",subjectId:"social_science",chapterNumber:"પ્રશ્ન 23-24",title:"ભારતનો સાહિત્યિક વારસો અને વિદ્યાપીઠો",subtitle:"વિભાગ A • 30 એક વાક્યના પ્રશ્નો (જવાબ સહિત)",questionTypeLabel:"એક વાક્યમાં જવાબ",questions:[{id:"ss_q24_01",questionText:"1) કઈ વિદ્યાપીઠમાં રસાયણવિદ્યાના પ્રયોગો માટે અલગ રસાયણશાળા અને ભઠ્ઠીઓ હતી? — (માર્ચ 2026)",options:["નાલંદા વિદ્યાપીઠ","તક્ષશિલા વિદ્યાપીઠ","વલ્લભી વિદ્યાપીઠ","વિક્રમશિલા વિદ્યાપીઠ"],correctIndex:0,explanation:"જવાબ: નાલંદા વિદ્યાપીઠમાં રસાયણવિદ્યાના અભ્યાસ અને સંશોધન માટે અલગ રસાયણશાળા અને ભઠ્ઠીઓ હતી."},{id:"ss_q24_02",questionText:"2) ભારતનો કયો વેદ સંગીતની ગંગોત્રી ગણાય છે? — (માર્ચ 2026)",options:["સામવેદ","ઋગ્વેદ","યજુર્વેદ","અથર્વવેદ"],correctIndex:0,explanation:"જવાબ: સામવેદ સંગીતની ગંગોત્રી ગણાય છે."},{id:"ss_q24_03",questionText:"3) ભારતનો પ્રાચીનતમ ગ્રંથ કયો છે? — (માર્ચ 2025)",options:["ઋગ્વેદ","સામવેદ","યજુર્વેદ","અથર્વવેદ"],correctIndex:0,explanation:"જવાબ: ઋગ્વેદ એ ભારતનો સૌથી પ્રાચીનતમ ગ્રંથ છે."},{id:"ss_q24_04",questionText:"4) પ્રારંભિક બૌદ્ધ સાહિત્ય કઈ ભાષામાં લખાયેલું છે? — (માર્ચ 2025)",options:["પાલી","સંસ્કૃત","પ્રાકૃત","તમિલ"],correctIndex:0,explanation:"જવાબ: પ્રારંભિક બૌદ્ધ સાહિત્ય પાલી ભાષામાં લખાયેલું છે."},{id:"ss_q24_05",questionText:"5) મહર્ષિ પાણિનિનો સંસ્કૃત ભાષાનો વ્યાકરણ ગ્રંથ કયો છે? (માર્ચ 2024)",options:["અષ્ટાધ્યાયી","મહાભાષ્ય","તોલકાપ્પિયમ્","અર્થશાસ્ત્ર"],correctIndex:0,explanation:"જવાબ: મહર્ષિ પાણિનિનો સંસ્કૃત ભાષાનો વ્યાકરણ ગ્રંથ 'અષ્ટાધ્યાયી' છે."},{id:"ss_q24_06",questionText:"6) મુઘલ બાદશાહ બાબરની આત્મકથાનું નામ શું છે? — (માર્ચ 2024)",options:["તુઝુક-એ-બાબરી (બાબરનામા)","અકબરનામા","હુમાયુનામા","તુઝુક-એ-જહાંગીરી"],correctIndex:0,explanation:"જવાબ: મુઘલ બાદશાહ બાબરની આત્મકથાનું નામ 'તુઝુક-એ-બાબરી' (બાબરનામા) છે."},{id:"ss_q24_07",questionText:"7) સંગીતની ગંગોત્રી તરીકે કયો વેદ ઓળખાય છે? — (નમૂના પ્રશ્નપત્ર 2024-25)",options:["સામવેદ","ઋગ્વેદ","યજુર્વેદ","અથર્વવેદ"],correctIndex:0,explanation:"જવાબ: સામવેદ સંગીતની ગંગોત્રી તરીકે ઓળખાય છે."},{id:"ss_q24_08",questionText:"8) બૌદ્ધ ધર્મના પવિત્ર ગ્રંથો કયા નામે ઓળખાય છે? — (નમૂના પ્રશ્નપત્ર 2024-25)",options:["ત્રિપિટક","આગમો","ઉપનિષદો","વેદાંગો"],correctIndex:0,explanation:"જવાબ: બૌદ્ધ ધર્મના પવિત્ર ગ્રંથો 'ત્રિપિટક' (સુત્ત પિટક, વિનય પિટક અને અભિધમ્મ પિટક) નામે ઓળખાય છે."},{id:"ss_q24_09",questionText:"9) વેદ કેટલા છે અને કયા કયા?",options:["ચાર — ઋગ્વેદ, યજુર્વેદ, સામવેદ અને અથર્વવેદ","ત્રણ — ઋગ્વેદ, યજુર્વેદ અને સામવેદ","પાંચ — ઋગ્વેદ, યજુર્વેદ, સામવેદ, અથર્વવેદ અને આયુર્વેદ","બે — ઋગ્વેદ અને સામવેદ"],correctIndex:0,explanation:"જવાબ: વેદ ચાર છે: (1) ઋગ્વેદ, (2) યજુર્વેદ, (3) સામવેદ અને (4) અથર્વવેદ."},{id:"ss_q24_10",questionText:"10) ઋગ્વેદમાં કેટલી ઋચાઓ અને કેટલા ભાગ છે?",options:["1028 ઋચાઓ અને 10 મંડળો (ભાગો)","1008 ઋચાઓ અને 8 મંડળો","1080 ઋચાઓ અને 12 મંડળો","1021 ઋચાઓ અને 10 મંડળો"],correctIndex:0,explanation:"જવાબ: ઋગ્વેદમાં કુલ 1028 ઋચાઓ (સૂક્તો) છે અને તે 10 મંડળો (ભાગો) માં વહેંચાયેલો છે."},{id:"ss_q24_11",questionText:"11) યજ્ઞ વખતે બોલવામાં આવતા મંત્રો અને વિધિઓ કયા વેદમાં દર્શાવેલા છે?",options:["યજુર્વેદ","ઋગ્વેદ","સામવેદ","અથર્વવેદ"],correctIndex:0,explanation:"જવાબ: યજ્ઞ વખતે બોલવામાં આવતા મંત્રો અને ક્રિયાઓ યજુર્વેદમાં દર્શાવેલા છે."},{id:"ss_q24_12",questionText:"12) અનેક પ્રકારના કર્મકાંડો અને સંસ્કારોનું વર્ણન કયા વેદમાં કરવામાં આવ્યું છે?",options:["અથર્વવેદ","ઋગ્વેદ","યજુર્વેદ","સામવેદ"],correctIndex:0,explanation:"જવાબ: અનેક પ્રકારના કર્મકાંડો, વિધિઓ અને સંસ્કારોનું વર્ણન અથર્વવેદમાં કરવામાં આવ્યું છે."},{id:"ss_q24_13",questionText:"13) સંસ્કૃત ભાષાને કઈ ભાષા તરીકે ઓળખવામાં આવે છે?",options:["આર્યભાષા, ઋષિઓની ભાષા અને વિદ્વાનોની ભાષા","માત્ર લોકબોલી","દ્રવિડ કુળની ભાષા","ફક્ત મધ્યયુગીન રાજભાષા"],correctIndex:0,explanation:"જવાબ: સંસ્કૃત ભાષાને આર્યભાષા, ઋષિઓની ભાષા, જ્ઞાન-વિજ્ઞાન અને વિદ્વાનોની ભાષા તરીકે ઓળખવામાં આવે છે."},{id:"ss_q24_14",questionText:"14) ભારતના બે પ્રાચીન મુખ્ય મહાકાવ્યો કયાં છે?",options:["રામાયણ અને મહાભારત","શિલપ્પદિકારમ્ અને મણિમેખલાઈ","રઘુવંશ અને કુમારસંભવ","મેઘદૂત અને અભિજ્ઞાનશાકુંતલમ્"],correctIndex:0,explanation:"જવાબ: રામાયણ અને મહાભારત એ ભારતના બે મુખ્ય પ્રાચીન મહાકાવ્યો છે."},{id:"ss_q24_15",questionText:"15) મહાભારતની રચના કોણે કરી હતી અને તેમાં આશરે કેટલા શ્લોકો છે?",options:["મહર્ષિ વેદવ્યાસે; લગભગ 1 લાખ શ્લોકો","મહર્ષિ વાલ્મીકિએ; 24 હજાર શ્લોકો","મહાકવિ કાલિદાસે; 50 હજાર શ્લોકો","પંડિત કલ્હણે; 75 હજાર શ્લોકો"],correctIndex:0,explanation:"જવાબ: મહાભારતની રચના મહર્ષિ વેદવ્યાસે કરી હતી અને તેમાં લગભગ 1 લાખ શ્લોકો છે."},{id:"ss_q24_16",questionText:"16) શ્રીમદ્ ભગવદ્ ગીતા કયા મહાકાવ્યનો એક ભાગ છે અને તેમાં કયા ત્રણ માર્ગોનું વિવેચન છે?",options:["મહાભારતના ભીષ્મપર્વનો ભાગ; જ્ઞાન, કર્મ અને ભક્તિ માર્ગ","રામાયણના અયોધ્યાકાંડનો ભાગ; સત્ય, અહિંસા અને તપ","ઋગ્વેદના પ્રથમ મંડળનો ભાગ; યજ્ઞ, દાન અને યોગ","ઉપનિષદનો ભાગ; અર્થ, કામ અને ધર્મ"],correctIndex:0,explanation:"જવાબ: શ્રીમદ્ ભગવદ્ ગીતા મહાભારતના ભીષ્મપર્વનો ભાગ છે અને તેમાં મોક્ષપ્રાપ્તિના જ્ઞાન, કર્મ અને ભક્તિ માર્ગનું વિવેચન છે."},{id:"ss_q24_17",questionText:"17) દ્રવિડ કુળની ચાર પ્રાચીન ભાષાઓ કઈ કઈ છે?",options:["તમિલ, તેલુગુ, કન્નડ અને મલયાલમ","હિન્દી, ગુજરાતી, મરાઠી અને બંગાળી","સંસ્કૃત, પાલી, પ્રાકૃત અને ઉર્દૂ","પંજાબી, ઉડિયા, અસમિયા અને કશ્મીરી"],correctIndex:0,explanation:"જવાબ: તમિલ, તેલુગુ, કન્નડ અને મલયાલમ એ દ્રવિડ કુળની ચાર ભાષાઓ છે, જેમાં તમિલ સૌથી પ્રાચીન છે."},{id:"ss_q24_18",questionText:"18) તમિલ સાહિત્યના પ્રાચીન ત્રણ ગ્રંથો કે સંગ્રહો કયા છે?",options:["એથુથોકોઈ, તોલકાપ્પિયમ્ અને પથ્થુપાત્તુ","ત્રિપિટક, જાતકકથા અને મિલિંદપન્હો","બ્રહ્મસૂત્ર, મીમાંસા અને સાંખ્ય","મેઘદૂત, ઋતુસંહાર અને માલવિકાગ્નિમિત્રમ્"],correctIndex:0,explanation:"જવાબ: એથુથોકોઈ (આઠ કાવ્યોનો સંગ્રહ), તોલકાપ્પિયમ્ (વ્યાકરણ ગ્રંથ) અને પથ્થુપાત્તુ (દસ ગીતો)."},{id:"ss_q24_19",questionText:"19) તમિલ સાહિત્યના બે પ્રખ્યાત મહાકાવ્યો કયાં છે?",options:["શિલપ્પદિકારમ્ અને મણિમેખલાઈ","રામાયણ અને મહાભારત","કિરાતાર્જુનીયમ્ અને શિશુપાલવધ","પૃથ્વીરાજ રાસો અને પદ્માવત"],correctIndex:0,explanation:"જવાબ: શિલપ્પદિકારમ્ અને મણિમેખલાઈ તમિલ સાહિત્યના પ્રખ્યાત મહાકાવ્યો છે."},{id:"ss_q24_20",questionText:"20) કૌટિલ્ય (ચાણક્ય) એ રાજનીતિ અને અર્થતંત્ર પર કયો વિશ્વવિખ્યાત ગ્રંથ રચ્યો?",options:["અર્થશાસ્ત્ર","નીતિશાસ્ત્ર","રાજતરંગિણી","મનુસ્મૃતિ"],correctIndex:0,explanation:"જવાબ: કૌટિલ્યએ વહીવટી વિજ્ઞાન અને રાજનીતિ પર 'અર્થશાસ્ત્ર' ગ્રંથ રચ્યો હતો."},{id:"ss_q24_21",questionText:"21) હિન્દી સાહિત્યનો વીરગાથા કાળનો પ્રારંભિક પ્રખ્યાત ગ્રંથ કયો છે અને તેના રચયિતા કોણ છે?",options:["'પૃથ્વીરાજ રાસો'; ચંદબરદાઈ","'રામચરિતમાનસ'; તુલસીદાસ","'બીજક'; કબીર","'પદ્માવત'; મલિક મુહમ્મદ જાયસી"],correctIndex:0,explanation:"જવાબ: હિન્દી સાહિત્યનો પ્રારંભિક ગ્રંથ 'પૃથ્વીરાજ રાસો' છે, જેના રચયિતા ચંદબરદાઈ છે."},{id:"ss_q24_22",questionText:"22) સંસ્કૃત સાહિત્યમાં 'ગીતગોવિંદ' કાવ્યગ્રંથની રચના કોણે કરી હતી?",options:["મહાકવિ જયદેવે","સોમદેવે","ભારવિએ","માઘે"],correctIndex:0,explanation:"જવાબ: મહાકવિ જયદેવે 'ગીતગોવિંદ' કાવ્યગ્રંથની રચના કરી હતી."},{id:"ss_q24_23",questionText:"23) કલ્હણ રચિત 'રાજતરંગિણી' ગ્રંથમાં કયા પ્રદેશનો પ્રાચીન ઇતિહાસ આલેખાયો છે?",options:["કાશ્મીરનો","બંગાળનો","ગુજરાતનો","મગધનો"],correctIndex:0,explanation:"જવાબ: 'રાજતરંગિણી' ગ્રંથમાં કાશ્મીરનો ક્રમિક અને પ્રમાણભૂત પ્રાચીન ઇતિહાસ આલેખાયો છે."},{id:"ss_q24_24",questionText:"24) વિજયનગરના મહાન સમ્રાટ કૃષ્ણદેવરાયે તેલુગુ ભાષામાં કયા ગ્રંથની રચના કરી હતી?",options:["આમુક્તમાલ્યદા","મનુચરિતમ્","કવિરાજમાર્ગ","ગીતગોવિંદ"],correctIndex:0,explanation:"જવાબ: સમ્રાટ કૃષ્ણદેવરાયે તેલુગુ ભાષામાં 'આમુક્તમાલ્યદા' ગ્રંથની રચના કરી હતી."},{id:"ss_q24_25",questionText:"25) અમીર ખુશરો કયા સુફી સંતના પરમ શિષ્ય હતા અને તેઓ કયા નામે જાણીતા બન્યા હતા?",options:["હઝરત નિઝામુદ્દીન ઓલિયાના; 'તૂતી-એ-હિન્દ' (ભારતના પોપટ)","સલીમ ચિશ્તીના; 'મુગલ રત્ન'","ખ્વાજા મોઈનુદ્દીન ચિશ્તીના; 'ગરીબ નવાઝ'","બખ્તિયાર કાકીના; 'દરબારે અકબરી'"],correctIndex:0,explanation:"જવાબ: અમીર ખુશરો હઝરત નિઝામુદ્દીન ઓલિયાના શિષ્ય હતા અને પોતાની અદ્ભુત પ્રતિભાને લીધે 'તૂતી-એ-હિન્દ' (ભારતના પોપટ) તરીકે જાણીતા બન્યા હતા."},{id:"ss_q24_26",questionText:"26) અબુલ ફઝલે કયા ઐતિહાસિક ગ્રંથોની રચના કરી હતી?",options:["'આઈને અકબરી' અને 'અકબરનામા'","'હુમાયુનામા' અને 'બાબરનામા'","'મુન્તખબ-ઉલ-તવારીખ'","'પાદશાહનામા' અને 'શાહજહાંનામા'"],correctIndex:0,explanation:"જવાબ: અબુલ ફઝલે 'આઈને અકબરી' અને 'અકબરનામા' ગ્રંથોની રચના કરી હતી."},{id:"ss_q24_27",questionText:"27) તક્ષશિલા વિદ્યાપીઠ હાલ ક્યાં આવેલી છે અને તે કઈ વિદ્યા માટે પ્રસિદ્ધ હતી?",options:["પાકિસ્તાનમાં રાવલપિંડી પાસે; ધનુરવિદ્યા તથા 64 વિદ્યાઓના શિક્ષણ માટે","બિહારના પટણા પાસે; રસાયણશાસ્ત્ર માટે","ગુજરાતના ભાવનગર પાસે; હીનયાન પંથ માટે","ઉત્તર પ્રદેશના કાશીમાં; વેદાંગ શિક્ષણ માટે"],correctIndex:0,explanation:"જવાબ: તક્ષશિલા વિદ્યાપીઠ હાલ પાકિસ્તાનમાં આવેલા રાવલપિંડી પાસે આવેલી છે અને તે ધનુરવિદ્યા તથા 64 વિદ્યાઓના શિક્ષણ માટે વિશ્વવિખ્યાત હતી."},{id:"ss_q24_28",questionText:"28) નાલંદા વિદ્યાપીઠ કયા રાજ્યમાં આવેલી હતી અને તેનો ભવ્ય પુસ્તકાલય વિસ્તાર કયા નામે ઓળખાતો હતો?",options:["બિહાર રાજ્યમાં (પટણાના બડગાંવ પાસે); 'ધર્મગંજ'","ગુજરાત રાજ્યમાં; 'મૈત્રક ગંજ'","બંગાળ રાજ્યમાં; 'વિક્રમગંજ'","મધ્યપ્રદેશ રાજ્યમાં; 'બૌદ્ધગંજ'"],correctIndex:0,explanation:"જવાબ: નાલંદા વિદ્યાપીઠ બિહારના પટણા જિલ્લાના બડગાંવ પાસે આવેલી હતી અને તેનો પુસ્તકાલય વિસ્તાર 'ધર્મગંજ' તરીકે ઓળખાતો હતો."},{id:"ss_q24_29",questionText:"29) ગુજરાતની કઈ પ્રાચીન વિદ્યાપીઠ બૌદ્ધ ધર્મના હીનયાન પંથનું મોટું કેન્દ્ર અને આંતરરાષ્ટ્રીય વિદ્યાધામ હતી?",options:["વલ્લભી વિદ્યાપીઠ (ભાવનગર પાસે)","પાટણ વિદ્યાપીઠ","વડનગર વિદ્યાપીઠ","સોમનાથ વિદ્યાપીઠ"],correctIndex:0,explanation:"જવાબ: ગુજરાતના ભાવનગર પાસે આવેલી 'વલ્લભી વિદ્યાપીઠ' હીનયાન પંથનું કેન્દ્ર અને પ્રસિદ્ધ આંતરરાષ્ટ્રીય વિદ્યાધામ હતી."},{id:"ss_q24_30",questionText:"30) વારાણસી (કાશી) વિદ્યાપીઠ મુખ્યત્વે કયા ધર્મ અને દર્શનના અભ્યાસ માટેનું પ્રસિદ્ધ કેન્દ્ર હતી?",options:["વૈદિક ધર્મ, ઉપનિષદો અને હિન્દુ સંસ્કૃતિના ઊંડાણપૂર્વકના અભ્યાસ માટે","માત્ર જૈન આગમોના અભ્યાસ માટે","ફક્ત અરબી અને ફારસી સાહિત્ય માટે","માત્ર નૌકાવિજ્ઞાન અને વહાણવટા માટે"],correctIndex:0,explanation:"જવાબ: વારાણસી (કાશી) વિદ્યાપીઠ વૈદિક ધર્મ, ઉપનિષદો અને હિન્દુ સંસ્કૃતિના ઊંડાણપૂર્વકના અભ્યાસ માટેનું કેન્દ્ર હતી."}]},h=[e,t,n,o,s,i,_,x,a,c,r,p,d,q,l,u,I,T,C,A,B,D,b];export{h as socialChapters};
